from contextlib import asynccontextmanager
from typing import Literal, Optional

from fastapi import Depends, FastAPI, HTTPException, Request
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import JSONResponse
from pydantic import BaseModel, Field
from sqlmodel import Session, select

from app import services as sv
from app.agent import agent
from app.db import create_db, engine, get_session
from app.models import ROL_NOMBRE, Alerta, Cirugia, Insumo, Paciente, Usuario
from app.stats import dashboard


@asynccontextmanager
async def lifespan(_: FastAPI):
    create_db()
    with Session(engine) as s:
        vacia = s.exec(select(Usuario)).first() is None
    if vacia:
        from app.seed import sembrar

        sembrar()
    yield


app = FastAPI(title="Tablero Inteligente de Seguridad Quirúrgica", version="1.0", lifespan=lifespan)
app.add_middleware(CORSMiddleware, allow_origins=["*"], allow_methods=["*"], allow_headers=["*"])


@app.exception_handler(sv.ErrorNegocio)
async def _error_negocio(_: Request, exc: sv.ErrorNegocio):
    return JSONResponse(status_code=exc.status,
                        content={"estado": "error", "resultado": exc.resultado, "texto": exc.mensaje,
                                 "datos": exc.datos})


@app.exception_handler(sv.RequiereConfirmacion)
async def _requiere_confirmacion(_: Request, exc: sv.RequiereConfirmacion):
    return JSONResponse(status_code=409, content={"estado": "confirmar", "texto": exc.mensaje,
                                                  "datos": exc.datos})


def _ctx(session: Session, usuario_id: int) -> sv.Ctx:
    u = session.get(Usuario, usuario_id)
    if u is None or not u.activo:
        raise HTTPException(401, "Usuario no válido")
    return sv.Ctx(usuario=u, canal="ui")


# ------------------------------------------------------------------ esquemas

class ConUsuario(BaseModel):
    usuario_id: int


class EventoIn(ConUsuario):
    hito: str
    justificacion: Optional[str] = None


class VerificarIn(ConUsuario):
    resultado: Optional[str] = None


class ConsumoIn(ConUsuario):
    insumo_id: int
    cantidad: int = Field(gt=0)
    confirmado: bool = False


class NovedadIn(ConUsuario):
    descripcion: str
    severidad: Literal["baja", "media", "alta"] = "media"
    categoria: Optional[str] = None


class ResolverIn(ConUsuario):
    accion_correctiva: str


class PacienteIn(ConUsuario):
    campos: dict


class CirugiaIn(ConUsuario):
    procedimiento_registrado: Optional[str] = None
    sitio_registrado: Optional[str] = None


class ComandoIn(BaseModel):
    texto: str
    usuario_id: int
    cirugia_id: int
    pending_id: Optional[str] = None
    canal: Literal["voz", "texto"] = "voz"


# ---------------------------------------------------------------- endpoints

@app.get("/api/usuarios")
def usuarios(session: Session = Depends(get_session)):
    return [{**u.model_dump(), "rol_nombre": ROL_NOMBRE[u.rol]}
            for u in session.exec(select(Usuario).where(Usuario.activo == True))]  # noqa: E712


@app.get("/api/cirugias")
def cirugias(session: Session = Depends(get_session)):
    pac = {p.id: p for p in session.exec(select(Paciente))}
    orden = {"en_curso": 0, "programada": 1, "finalizada": 2}
    filas = sorted(session.exec(select(Cirugia)).all(),
                   key=lambda c: (orden.get(c.estado, 3), -c.fecha_programada.timestamp()))
    return [{"id": c.id, "procedimiento": c.procedimiento_programado, "paciente": pac[c.paciente_id].nombre,
             "estado": c.estado, "fase_actual": c.fase_actual, "quirofano": c.quirofano,
             "fecha": c.fecha_programada} for c in filas]


@app.get("/api/cirugias/{cid}")
def cirugia(cid: int, session: Session = Depends(get_session)):
    return sv.estado_cirugia(session, cid)


@app.patch("/api/cirugias/{cid}")
def editar_cirugia(cid: int, body: CirugiaIn, session: Session = Depends(get_session)):
    cambios = body.model_dump(exclude={"usuario_id"}, exclude_unset=True)
    return sv.actualizar_cirugia(session, cid, cambios, _ctx(session, body.usuario_id))


@app.patch("/api/cirugias/{cid}/paciente")
def editar_paciente(cid: int, body: PacienteIn, session: Session = Depends(get_session)):
    return sv.actualizar_paciente(session, cid, body.campos, _ctx(session, body.usuario_id))


@app.post("/api/cirugias/{cid}/eventos")
def evento(cid: int, body: EventoIn, session: Session = Depends(get_session)):
    return sv.registrar_evento(session, cid, body.hito, _ctx(session, body.usuario_id), body.justificacion)


@app.post("/api/cirugias/{cid}/checklist/{item_id}/verificar")
def verificar(cid: int, item_id: int, body: VerificarIn, session: Session = Depends(get_session)):
    return sv.verificar_item(session, cid, item_id, _ctx(session, body.usuario_id), body.resultado)


@app.post("/api/cirugias/{cid}/fases/{n}/cerrar")
def cerrar(cid: int, n: int, body: ConUsuario, session: Session = Depends(get_session)):
    return sv.cerrar_fase(session, cid, n, _ctx(session, body.usuario_id))


@app.get("/api/cirugias/{cid}/insumos")
def insumos(cid: int, session: Session = Depends(get_session)):
    return session.exec(select(Insumo).where(Insumo.cirugia_id == cid).order_by(Insumo.id)).all()


@app.post("/api/cirugias/{cid}/consumos")
def consumo(cid: int, body: ConsumoIn, session: Session = Depends(get_session)):
    return sv.registrar_consumo(session, cid, body.insumo_id, body.cantidad,
                                _ctx(session, body.usuario_id), confirmado=body.confirmado)


@app.post("/api/cirugias/{cid}/novedades")
def novedad(cid: int, body: NovedadIn, session: Session = Depends(get_session)):
    return sv.registrar_novedad(session, cid, body.descripcion, _ctx(session, body.usuario_id),
                                body.severidad, body.categoria)


@app.patch("/api/novedades/{nid}/resolver")
def resolver(nid: int, body: ResolverIn, session: Session = Depends(get_session)):
    return sv.resolver_novedad(session, nid, body.accion_correctiva, _ctx(session, body.usuario_id))


@app.get("/api/cirugias/{cid}/alertas")
def alertas(cid: int, estado: Optional[str] = None, session: Session = Depends(get_session)):
    q = select(Alerta).where(Alerta.cirugia_id == cid)
    if estado:
        q = q.where(Alerta.estado == estado)
    return session.exec(q.order_by(Alerta.id.desc())).all()


@app.get("/api/cirugias/{cid}/trazabilidad")
def trazabilidad(cid: int, usuario_id: Optional[int] = None, accion: Optional[str] = None,
                 canal: Optional[str] = None, resultado: Optional[str] = None,
                 session: Session = Depends(get_session)):
    return sv.listar_trazabilidad(session, cid, usuario_id, accion, canal, resultado)


@app.get("/api/dashboard")
def panel(session: Session = Depends(get_session)):
    return dashboard(session)


@app.post("/api/agent/command")
def comando(body: ComandoIn, session: Session = Depends(get_session)):
    return agent.procesar(session, body.texto, body.usuario_id, body.cirugia_id, body.pending_id, body.canal)


@app.post("/api/demo/reset")
def reset_demo():
    from app.seed import sembrar

    agent.PENDIENTES.clear()
    sembrar()
    return {"ok": True}

