def item(client, codigo):
    for f in estado(client)["fases"]:
        for i in f["items"]:
            if i["codigo"] == codigo:
                return i
    raise KeyError(codigo)


def insumo(client, nombre):
    return next(i for i in estado(client)["insumos"] if i["nombre"] == nombre)


def reglas_activas(client):
    return {a["regla"] for a in estado(client)["alertas"]}

