export function hora(iso) {
  if (!iso) return '--:--'
  return new Date(iso).toLocaleTimeString('es-CO', { hour: '2-digit', minute: '2-digit', hour12: false })
}

export function fechaHora(iso) {
  if (!iso) return '—'
  return new Date(iso).toLocaleString('es-CO', {
    day: '2-digit',
    month: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  })
}

import { useCallback, useEffect, useRef, useState } from 'react'

const SR = typeof window !== 'undefined' ? window.SpeechRecognition || window.webkitSpeechRecognition : null

/** Push-to-talk con Web Speech API (es-CO) y respuesta con speechSynthesis. */
export function useVoz(onFinal) {
  const [escuchando, setEscuchando] = useState(false)
  const [parcial, setParcial] = useState('')
  const [error, setError] = useState(null)
  const recRef = useRef(null)
  const bufferRef = useRef('')
  const onFinalRef = useRef(onFinal)
  const vozRef = useRef(null)

  useEffect(() => {
    onFinalRef.current = onFinal
  }, [onFinal])

  useEffect(() => {
    if (!window.speechSynthesis) return
    const elegir = () => {
      const voces = window.speechSynthesis.getVoices()
      vozRef.current =
        voces.find((v) => v.lang === 'es-CO') ||
        voces.find((v) => v.lang?.startsWith('es-') && /google|microsoft/i.test(v.name)) ||
        voces.find((v) => v.lang?.startsWith('es')) ||
        null
    }
    elegir()
    window.speechSynthesis.onvoiceschanged = elegir
  }, [])

  const iniciar = useCallback(() => {
    if (!SR || recRef.current) return
    window.speechSynthesis?.cancel()
    setError(null)
    bufferRef.current = ''
    setParcial('')
    const rec = new SR()
    rec.lang = 'es-CO'
    rec.interimResults = true
    rec.continuous = true
    rec.maxAlternatives = 1
    rec.onresult = (e) => {
      let final = ''
      let interino = ''
      for (let i = 0; i < e.results.length; i++) {
        const r = e.results[i]
        if (r.isFinal) final += r[0].transcript
        else interino += r[0].transcript
      }
      bufferRef.current = final
      setParcial((final + ' ' + interino).trim())
    }
    rec.onerror = (e) => {
      if (e.error !== 'aborted' && e.error !== 'no-speech') {
        setError(
          e.error === 'not-allowed'
            ? 'Permiso de micrófono denegado.'
            : e.error === 'network'
              ? 'Sin conexión: el reconocimiento de Chrome requiere internet. Use el campo de texto.'
              : `Error de reconocimiento: ${e.error}`,
        )
      }
    }
    rec.onend = () => {
      recRef.current = null
      setEscuchando(false)
      const texto = (bufferRef.current || '').trim()
      setParcial('')
      if (texto) onFinalRef.current?.(texto)
    }
    recRef.current = rec
    setEscuchando(true)
    try {
      rec.start()
    } catch {
      recRef.current = null
      setEscuchando(false)
    }
  }, [])

  const detener = useCallback(() => {
    const rec = recRef.current
    if (!rec) return
    // Espera un instante para no cortar la última palabra
    setTimeout(() => rec.stop(), 350)
  }, [])

  const hablar = useCallback((texto) => {
    if (!window.speechSynthesis || !texto) return
    window.speechSynthesis.cancel()
    const u = new SpeechSynthesisUtterance(texto)
    u.lang = 'es-CO'
    if (vozRef.current) u.voice = vozRef.current
    u.rate = 1.05
    window.speechSynthesis.speak(u)
  }, [])

  return { soportado: !!SR, escuchando, parcial, error, iniciar, detener, hablar }
}

