const DialogoCtx = createContext(null)
const ToastCtx = createContext(null)

export function useDialogo() {
  return useContext(DialogoCtx)
}

export function useToast() {
  return useContext(ToastCtx)
}

export function Proveedores({ children }) {
  const [dialogo, setDialogo] = useState(null)
  const [valor, setValor] = useState('')
  const [toasts, setToasts] = useState([])
  const resolverRef = useRef(null)
  const inputRef = useRef(null)

  const pedir = useCallback((opciones) => {
    setValor(opciones.valorInicial ?? '')
    setDialogo(opciones)
    return new Promise((resolve) => {
      resolverRef.current = resolve
    })
  }, [])

  const cerrar = (resultado) => {
    resolverRef.current?.(resultado)
    resolverRef.current = null
    setDialogo(null)
  }

  const toast = useCallback((texto, tipo = 'info') => {
    const id = Math.random()
    setToasts((t) => [...t, { id, texto, tipo }])
    setTimeout(() => setToasts((t) => t.filter((x) => x.id !== id)), 5000)
  }, [])

  useEffect(() => {
    if (dialogo) setTimeout(() => inputRef.current?.focus(), 30)
  }, [dialogo])

  const invalido = dialogo?.campo && dialogo.requerido && valor.trim().length < 3

  return (
    <DialogoCtx.Provider value={pedir}>
      <ToastCtx.Provider value={toast}>
        {children}
        {dialogo && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 p-4">
            <form
              className="w-full max-w-md rounded-xl bg-white p-5 shadow-xl"
              onSubmit={(e) => {
                e.preventDefault()
                if (!invalido) cerrar(dialogo.campo ? valor.trim() : true)
              }}
            >
              <h3 className="text-lg font-semibold">{dialogo.titulo}</h3>
              {dialogo.mensaje && <p className="mt-2 text-sm text-slate-600">{dialogo.mensaje}</p>}
              {dialogo.campo && (
                <label className="mt-4 block text-sm">
                  <span className="font-medium text-slate-700">{dialogo.campo}</span>
                  <input
                    ref={inputRef}
                    value={valor}
                    onChange={(e) => setValor(e.target.value)}
                    placeholder={dialogo.placeholder}
                    className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 outline-none focus:border-sky-500 focus:ring-2 focus:ring-sky-200"
                  />
                </label>
              )}
              <div className="mt-5 flex justify-end gap-2">
                <Boton type="button" variante="secundario" onClick={() => cerrar(null)}>
                  Cancelar
                </Boton>
                <Boton type="submit" variante={dialogo.peligro ? 'peligro' : 'primario'} disabled={invalido}>
                  {dialogo.confirmar || 'Confirmar'}
                </Boton>
              </div>
            </form>
          </div>
        )}
        <div className="no-print pointer-events-none fixed bottom-4 left-1/2 z-50 flex w-full max-w-xl -translate-x-1/2 flex-col gap-2 px-4">
          {toasts.map((t) => (
            <div
              key={t.id}
              className={`rounded-lg px-4 py-3 text-sm font-medium shadow-lg ${
                t.tipo === 'error'
                  ? 'bg-red-600 text-white'
                  : t.tipo === 'ok'
                    ? 'bg-emerald-600 text-white'
                    : 'bg-slate-800 text-white'
              }`}
            >
              {t.texto}
            </div>
          ))}
        </div>
      </ToastCtx.Provider>
    </DialogoCtx.Provider>
  )
}

