// ------------------------------------------------------------------ paciente

function Paciente({ estado, ejecutar, resaltar }) {
  const pedir = useDialogo()
  const { paciente: p, cirugia: c, equipo } = estado
  const faltan = new Set(p.faltantes)

  const completar = async (campo, etiqueta) => {
    const v = await pedir({ titulo: `Registrar ${etiqueta.toLowerCase()}`, campo: etiqueta, requerido: false })
    if (v === null || v === '') return
    const valor = NUMERICOS.has(campo) ? Number(String(v).replace(',', '.')) : v
    if (NUMERICOS.has(campo) && Number.isNaN(valor)) return
    ejecutar({
      metodo: 'patch',
      url: `/cirugias/${c.id}/paciente`,
      body: { campos: { [campo]: valor } },
      cambios: ['paciente'],
      exito: () => `${etiqueta} registrado`,
    })
  }

  return (
    <Card resaltar={resaltar.has('paciente')} className="col-span-12">
      <div className="flex flex-wrap items-start gap-6">
        <div className="min-w-64 flex-1">
          <div className="text-xs font-semibold uppercase tracking-wide text-slate-500">
            {c.quirofano} · Paciente
          </div>
          <div className="text-2xl font-bold">{p.nombre}</div>
          <div className="mt-1 text-sm text-slate-600">
            <span className="font-semibold text-slate-800">{c.procedimiento_programado}</span> · Sitio:{' '}
            {c.sitio_programado}
          </div>
          <div className="mt-2 flex flex-wrap items-center gap-2">
            {p.alergias ? (
              <Badge className="bg-red-100 text-red-800 ring-1 ring-red-300">Alergia: {p.alergias}</Badge>
            ) : (
              <button onClick={() => completar('alergias', 'Alergias')}>
                <Badge className="bg-red-600 text-white">Alergias sin registrar · Completar</Badge>
              </button>
            )}
            {p.info_clinica && <span className="text-xs text-slate-500">{p.info_clinica}</span>}
          </div>
        </div>

        <dl className="grid grid-cols-3 gap-x-6 gap-y-2 text-sm">
          {CAMPOS_PACIENTE.map(([campo, etiqueta, fmt]) => (
            <div key={campo}>
              <dt className="text-xs text-slate-500">{etiqueta}</dt>
              <dd className="font-medium">
                {p[campo] !== null && p[campo] !== '' ? (
                  fmt ? fmt(p[campo]) : p[campo]
                ) : faltan.has(campo) ? (
                  <button
                    onClick={() => completar(campo, etiqueta)}
                    className="rounded bg-amber-100 px-1.5 py-0.5 text-xs font-semibold text-amber-800 ring-1 ring-amber-300 hover:bg-amber-200"
                  >
                    Falta · Completar
                  </button>
                ) : (
                  <span className="text-slate-400">—</span>
                )}
              </dd>
            </div>
          ))}
        </dl>

        <div className="min-w-56">
          <div className="mb-1 text-xs font-semibold uppercase tracking-wide text-slate-500">Equipo quirúrgico</div>
          <ul className="space-y-1 text-sm">
            {equipo.map((m) => (
              <li key={m.usuario_id} className="flex items-center justify-between gap-3">
                <span>{m.nombre}</span>
                <RolBadge rol={m.rol} />
              </li>
            ))}
          </ul>
        </div>
      </div>
    </Card>
  )
}

