function Hitos({ estado, usuario, ejecutar, resaltar }) {
  const pedir = useDialogo()
  const siguiente = estado.hitos.find((h) => !h.hora)
  const finalizada = estado.cirugia.estado === 'finalizada'
  const d = estado.duraciones

  const registrar = async (h) => {
    const ok = await pedir({ titulo: 'Registrar hito', mensaje: `¿Registrar «${h.nombre}» ahora?` })
    if (!ok) return
    ejecutar({
      url: `/cirugias/${estado.cirugia.id}/eventos`,
      body: { hito: h.codigo },
      cambios: ['hitos'],
      exito: () => `${h.nombre} registrado`,
    })
  }

  return (
    <Card titulo="Tiempos quirúrgicos" resaltar={resaltar.has('hitos')} className="col-span-12"
      extra={
        <div className="flex gap-3 text-xs text-slate-500">
          {d.anestesia_a_incision_min != null && <span>Anestesia → incisión: {d.anestesia_a_incision_min} min</span>}
          {d.cirugia_min != null && <span>Cirugía: {d.cirugia_min} min</span>}
          {d.en_quirofano_min != null && <span>En quirófano: {d.en_quirofano_min} min</span>}
        </div>
      }
    >
      <ol className="grid grid-cols-5 gap-2">
        {estado.hitos.map((h, i) => {
          const hecho = !!h.hora
          const esSiguiente = siguiente?.codigo === h.codigo && !finalizada
          const puede = h.roles.includes(usuario.rol)
          return (
            <li
              key={h.codigo}
              className={`relative rounded-lg border p-3 ${
                hecho ? 'border-emerald-300 bg-emerald-50' : esSiguiente ? 'border-sky-300 bg-sky-50' : 'border-slate-200'
              }`}
            >
              <div className="flex items-center gap-2">
                <span
                  className={`flex h-6 w-6 items-center justify-center rounded-full text-xs font-bold ${
                    hecho ? 'bg-emerald-600 text-white' : 'bg-slate-200 text-slate-600'
                  }`}
                >
                  {hecho ? '✓' : i + 1}
                </span>
                <span className="text-sm font-medium">{h.nombre}</span>
              </div>
              <div className="mt-2 flex items-center justify-between">
                <span className={`font-mono text-xl ${hecho ? 'text-emerald-800' : 'text-slate-300'}`}>
                  {hora(h.hora)}
                </span>
                {esSiguiente && (
                  <Boton
                    onClick={() => registrar(h)}
                    disabled={!puede}
                    title={puede ? '' : `Lo registra: ${h.roles.map((r) => ROL_NOMBRE[r]).join(', ')}`}
                  >
                    Registrar
                  </Boton>
                )}
              </div>
            </li>
          )
        })}
      </ol>
    </Card>
  )
}

