function Checklist({ estado, usuario, ejecutar, resaltar, refs }) {
  const pedir = useDialogo()
  const { cirugia: c, fases } = estado
  const [ver, setVer] = useState(Math.min(c.fase_actual, 3))

  useEffect(() => {
    setVer(Math.min(c.fase_actual, 3))
  }, [c.fase_actual])

  useEffect(() => {
    if (refs.item_id) {
      const f = fases.find((x) => x.items.some((i) => i.id === refs.item_id))
      if (f) setVer(f.numero)
    }
  }, [refs, fases])

  const fase = fases.find((f) => f.numero === ver)
  const cerrable = fase.estado === 'en_curso'

  const verificar = async (it) => {
    const resultado = await pedir({
      titulo: 'Verificar ítem',
      mensaje: `«${it.descripcion}» quedará registrado a nombre de ${usuario.nombre} (${ROL_NOMBRE[usuario.rol]}).`,
      campo: 'Resultado',
      valorInicial: 'Conforme',
    })
    if (resultado === null) return
    ejecutar({
      url: `/cirugias/${c.id}/checklist/${it.id}/verificar`,
      body: { resultado },
      cambios: ['checklist', 'fases'],
      refs: { item_id: it.id },
      exito: () => `Verificado: ${it.descripcion}`,
    })
  }

  const cerrar = async () => {
    const ok = await pedir({
      titulo: `Cerrar fase ${fase.numero}`,
      mensaje: `¿Cerrar «${fase.nombre}»? Se validará que no haya verificaciones obligatorias pendientes.`,
    })
    if (!ok) return
    ejecutar({
      url: `/cirugias/${c.id}/fases/${fase.numero}/cerrar`,
      body: {},
      cambios: ['fases', 'checklist'],
      exito: () => `Fase ${fase.numero} cerrada`,
    })
  }

  return (
    <Card
      titulo="Checklist de seguridad quirúrgica"
      resaltar={resaltar.has('checklist') || resaltar.has('fases')}
    >
      <div className="mb-4 grid grid-cols-3 gap-2">
        {fases.map((f) => {
          const pct = f.total ? Math.round((100 * f.verificados) / f.total) : 0
          const estilo =
            f.estado === 'cerrada'
              ? 'border-emerald-400 bg-emerald-50'
              : f.estado === 'en_curso'
                ? 'border-sky-400 bg-sky-50'
                : 'border-slate-200 bg-slate-50 opacity-70'
          return (
            <button
              key={f.numero}
              onClick={() => setVer(f.numero)}
              className={`rounded-lg border-2 p-2.5 text-left transition ${estilo} ${ver === f.numero ? 'ring-2 ring-slate-800' : ''}`}
            >
              <div className="flex items-center justify-between">
                <span className="text-xs font-semibold uppercase text-slate-500">Fase {f.numero}</span>
                <span className="text-xs font-semibold">
                  {f.estado === 'cerrada' ? 'Cerrada' : f.estado === 'en_curso' ? 'En curso' : 'Pendiente'}
                </span>
              </div>
              <div className="text-sm font-semibold">{f.nombre}</div>
              <div className="mt-1.5 h-1.5 overflow-hidden rounded bg-slate-200">
                <div
                  className={`h-full ${f.estado === 'cerrada' ? 'bg-emerald-500' : 'bg-sky-500'}`}
                  style={{ width: `${pct}%` }}
                />
              </div>
              <div className="mt-1 text-xs text-slate-500">
                {f.verificados}/{f.total} obligatorios
              </div>
            </button>
          )
        })}
      </div>

      <ul className="divide-y divide-slate-100">
        {fase.items.map((it) => {
          const ok = it.estado === 'verificado'
          const habilitado = it.fase <= c.fase_actual && c.estado !== 'finalizada'
          const esMio = it.rol_responsable === usuario.rol
          return (
            <li
              key={it.id}
              className={`flex items-center gap-3 rounded px-2 py-2.5 ${refs.item_id === it.id && resaltar.size ? 'resaltado' : ''}`}
            >
              <span
                className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-full border-2 text-sm font-bold ${
                  ok ? 'border-emerald-600 bg-emerald-600 text-white' : 'border-slate-300 text-transparent'
                }`}
              >
                ✓
              </span>
              <div className="min-w-0 flex-1">
                <div className="flex flex-wrap items-center gap-1.5">
                  <span className={`font-medium ${ok ? 'text-slate-500' : ''}`}>{it.descripcion}</span>
                  {it.tipo === 'equipo' && <Badge className="bg-slate-100 text-slate-600">Equipo</Badge>}
                  {it.tipo === 'recuento' && <Badge className="bg-orange-100 text-orange-700">Recuento</Badge>}
                  {!it.obligatorio && <Badge className="bg-slate-100 text-slate-500">Opcional</Badge>}
                </div>
                <div className="mt-0.5 text-xs text-slate-500">
                  {ok ? (
                    <>
                      <span className="font-medium text-emerald-700">{it.verificado_por_nombre}</span> ·{' '}
                      {hora(it.verificado_en)} · {it.resultado}
                    </>
                  ) : (
                    <>Responsable: {ROL_NOMBRE[it.rol_responsable]}</>
                  )}
                </div>
              </div>
              <RolBadge rol={it.rol_responsable} />
              {!ok && habilitado && (
                <Boton
                  variante={esMio ? 'primario' : 'secundario'}
                  onClick={() => verificar(it)}
                  title={esMio ? '' : `Solo puede verificarlo: ${ROL_NOMBRE[it.rol_responsable]}`}
                >
                  Verificar
                </Boton>
              )}
            </li>
          )
        })}
      </ul>

      {cerrable && (
        <div className="mt-4 flex items-center justify-between border-t border-slate-100 pt-3">
          <span className="text-sm text-slate-500">
            {fase.verificados < fase.total
              ? `Faltan ${fase.total - fase.verificados} verificaciones obligatorias`
              : 'Todas las verificaciones obligatorias completas'}
          </span>
          <Boton variante={fase.verificados < fase.total ? 'secundario' : 'exito'} onClick={cerrar}>
            Cerrar fase {fase.numero}
          </Boton>
        </div>
      )}
    </Card>
  )
}

// ------------------------------------------------------------------- insumos

function Insumos({ estado, usuario, ejecutar, resaltar, refs }) {
  const pedir = useDialogo()
  const cid = estado.cirugia.id
  const puede = ['instrumentador', 'auxiliar'].includes(usuario.rol) && estado.cirugia.estado !== 'finalizada'

  const consumir = async (ins, cantidad) => {
    if (cantidad == null) {
      const v = await pedir({ titulo: `Consumo de ${ins.nombre.toLowerCase()}`, campo: 'Cantidad', valorInicial: '1' })
      if (!v) return
      cantidad = parseInt(v, 10)
      if (!(cantidad > 0)) return
    }
    ejecutar({
      url: `/cirugias/${cid}/consumos`,
      body: { insumo_id: ins.id, cantidad },
      cambios: ['insumos'],
      refs: { insumo_id: ins.id },
      exito: (d) => `Registrado: ${cantidad} ${ins.nombre.toLowerCase()}. Quedan ${d.restante}`,
    })
  }

  return (
    <Card titulo="Insumos" resaltar={resaltar.has('insumos')}>
      <table className="w-full text-sm">
        <thead>
          <tr className="text-left text-xs text-slate-500">
            <th className="pb-2 font-medium">Insumo</th>
            <th className="pb-2 font-medium">Disponible</th>
            <th className="pb-2" />
          </tr>
        </thead>
        <tbody className="divide-y divide-slate-100">
          {estado.insumos.map((ins) => {
            const pct = (100 * ins.cantidad_disponible) / ins.cantidad_inicial
            const agotado = ins.cantidad_disponible === 0
            return (
              <tr key={ins.id} className={refs.insumo_id === ins.id && resaltar.size ? 'resaltado' : ''}>
                <td className="py-2 pr-2 font-medium">
                  {ins.nombre}
                  {agotado && <Badge className="ml-2 bg-red-600 text-white">Agotado</Badge>}
                </td>
                <td className="w-48 py-2 pr-3">
                  <div className="flex items-center gap-2">
                    <div className="h-2 flex-1 overflow-hidden rounded bg-slate-200">
                      <div
                        className={`h-full ${agotado ? 'bg-red-500' : pct <= 30 ? 'bg-amber-500' : 'bg-emerald-500'}`}
                        style={{ width: `${pct}%` }}
                      />
                    </div>
                    <span className="w-14 text-right font-mono">
                      {ins.cantidad_disponible}/{ins.cantidad_inicial}
                    </span>
                  </div>
                </td>
                <td className="py-2 text-right whitespace-nowrap">
                  {puede && (
                    <>
                      <Boton variante="secundario" disabled={agotado} onClick={() => consumir(ins, 1)}>
                        −1
                      </Boton>{' '}
                      <Boton variante="fantasma" disabled={agotado} onClick={() => consumir(ins, null)}>
                        Otro…
                      </Boton>
                    </>
                  )}
                </td>
              </tr>
            )
          })}
        </tbody>
      </table>
      {!puede && <p className="mt-2 text-xs text-slate-400">Los consumos los registran instrumentador y auxiliar.</p>}
    </Card>
  )
}

// ----------------------------------------------------------------- novedades

function Novedades({ estado, usuario, ejecutar, resaltar, refs }) {
  const pedir = useDialogo()
  const [desc, setDesc] = useState('')
  const [sev, setSev] = useState('media')
  const cid = estado.cirugia.id
  const puede = usuario.rol !== 'gestor' && estado.cirugia.estado !== 'finalizada'

  const registrar = async (e) => {
    e.preventDefault()
    if (desc.trim().length < 3) return
    const r = await ejecutar({
      url: `/cirugias/${cid}/novedades`,
      body: { descripcion: desc, severidad: sev },
      cambios: ['novedades'],
      exito: (d) => `Novedad #${d.novedad.numero} registrada`,
    })
    if (r) setDesc('')
  }

  const resolver = async (n) => {
    const accion = await pedir({
      titulo: `Resolver novedad #${n.numero}`,
      mensaje: n.descripcion,
      campo: 'Acción correctiva',
      requerido: true,
      placeholder: 'Ej.: se cambió el cable',
    })
    if (!accion) return
    ejecutar({
      metodo: 'patch',
      url: `/novedades/${n.id}/resolver`,
      body: { accion_correctiva: accion },
      cambios: ['novedades'],
      refs: { novedad_id: n.id },
      exito: () => `Novedad #${n.numero} resuelta`,
    })
  }

  return (
    <Card titulo="Novedades" resaltar={resaltar.has('novedades')}>
      {puede && (
        <form onSubmit={registrar} className="mb-3 flex gap-2">
          <input
            value={desc}
            onChange={(e) => setDesc(e.target.value)}
            placeholder="Describa la novedad (ej.: falla en el cable de la cámara)"
            className="flex-1 rounded-lg border border-slate-300 px-3 py-1.5 text-sm outline-none focus:border-sky-500"
          />
          <select
            value={sev}
            onChange={(e) => setSev(e.target.value)}
            className="rounded-lg border border-slate-300 px-2 text-sm"
          >
            <option value="baja">Baja</option>
            <option value="media">Media</option>
            <option value="alta">Alta</option>
          </select>
          <Boton type="submit" disabled={desc.trim().length < 3}>
            Registrar
          </Boton>
        </form>
      )}
      {estado.novedades.length === 0 ? (
        <p className="text-sm text-slate-400">Sin novedades registradas.</p>
      ) : (
        <ul className="space-y-2">
          {estado.novedades.map((n) => (
            <li
              key={n.id}
              className={`rounded-lg border p-2.5 text-sm ${
                n.estado === 'abierta' ? SEVERIDAD[n.severidad].borde : 'border-slate-200 bg-slate-50'
              } ${refs.novedad_id === n.id && resaltar.size ? 'resaltado' : ''}`}
            >
              <div className="flex items-start justify-between gap-2">
                <div>
                  <span className="font-semibold">#{n.numero}</span> {n.descripcion}
                  <div className="mt-0.5 text-xs text-slate-500">
                    {n.categoria} · {n.registrada_por_nombre} · {hora(n.ts)}
                  </div>
                  {n.estado === 'resuelta' && (
                    <div className="mt-1 text-xs text-emerald-700">
                      Resuelta por {n.resuelta_por_nombre} a las {hora(n.ts_resolucion)}: {n.accion_correctiva}
                    </div>
                  )}
                </div>
                {n.estado === 'abierta' ? (
                  puede && (
                    <Boton variante="secundario" onClick={() => resolver(n)}>
                      Resolver
                    </Boton>
                  )
                ) : (
                  <Badge className="bg-emerald-100 text-emerald-800">Resuelta</Badge>
                )}
              </div>
            </li>
          ))}
        </ul>
      )}
    </Card>
  )
}

// ------------------------------------------------------------------- alertas

const ORDEN_SEV = { alta: 0, media: 1, baja: 2 }

function Alertas({ estado, resaltar }) {
  const alertas = [...estado.alertas].sort((a, b) => ORDEN_SEV[a.severidad] - ORDEN_SEV[b.severidad])
  return (
    <Card
      titulo="Alertas activas"
      resaltar={resaltar.has('alertas')}
      extra={
        <Badge className={alertas.length ? 'bg-red-600 text-white' : 'bg-emerald-100 text-emerald-800'}>
          {alertas.length}
        </Badge>
      }
    >
      {alertas.length === 0 ? (
        <p className="text-sm text-emerald-700">Sin alertas activas.</p>
      ) : (
        <ul className="space-y-2">
          {alertas.map((a) => (
            <li key={a.id} className={`rounded-lg border p-2.5 text-sm ${SEVERIDAD[a.severidad].borde}`}>
              <div className="flex items-center gap-2">
                <Badge className={SEVERIDAD[a.severidad].chip}>{a.regla}</Badge>
                <span className="text-xs text-slate-500">desde {hora(a.creada_en)}</span>
              </div>
              <div className="mt-1 font-medium">{a.mensaje}</div>
            </li>
          ))}
        </ul>
      )}
      <p className="mt-3 text-xs text-slate-400">Las alertas se calculan por reglas y se resuelven solas al cumplirse la condición.</p>
    </Card>
  )
}

