import { useCallback, useEffect, useRef, useState } from 'react'
import { ROL_NOMBRE, api } from '../api'
import { useVoz } from '../useVoz'
import { Boton, Card } from './ui'

const FRASES_DEMO = [
  { texto: '¿Qué nos falta para completar esta fase?', rol: 'cirujano' },
  { texto: 'Torre de laparoscopia verificada, funcionamiento correcto', rol: 'instrumentador' },
  { texto: 'Se utilizaron tres gasas adicionales', rol: 'instrumentador' },
  { texto: 'Se utilizaron cinco gasas adicionales', rol: 'instrumentador' },
  { texto: 'Registrar novedad: falla en el cable de la cámara', rol: 'auxiliar' },
  { texto: 'Novedad uno resuelta, se cambió el cable', rol: 'auxiliar' },
  { texto: 'Recuento de gasas correcto', rol: 'anestesiologo' },
  { texto: 'Paciente ingresó a quirófano', rol: 'auxiliar' },
  { texto: 'Alergias confirmadas', rol: 'anestesiologo' },
  { texto: '¿Hay alertas activas?', rol: 'cirujano' },
  { texto: '¿Cómo va la cirugía?', rol: 'cirujano' },
]

const ESTILO_ESTADO = {
  ok: 'border-emerald-200 bg-emerald-50 text-emerald-900',
  confirmar: 'border-amber-300 bg-amber-50 text-amber-950',
  error: 'border-red-200 bg-red-50 text-red-900',
  no_entendido: 'border-slate-200 bg-slate-50 text-slate-700',
}

export default function AgenteVoz({ usuario, usuarios, cirugiaId, onRespuesta, onCambiarUsuario }) {
  const [historial, setHistorial] = useState([])
  const [pendiente, setPendiente] = useState(null) // { id, expira }
  const [restante, setRestante] = useState(0)
  const [texto, setTexto] = useState('')
  const [silencio, setSilencio] = useState(false)
  const [enviando, setEnviando] = useState(false)
  const [mostrarFrases, setMostrarFrases] = useState(true)
  const finRef = useRef(null)
  const estadoRef = useRef({})
  estadoRef.current = { usuario, pendiente, cirugiaId, silencio }

  const enviar = useCallback(
    async (frase, canal, usuarioForzado) => {
      const { usuario: u, pendiente: p, cirugiaId: cid, silencio: mudo } = estadoRef.current
      const quien = usuarioForzado || u
      if (!frase.trim() || !quien) return
      setEnviando(true)
      setHistorial((h) => [...h, { tipo: 'usuario', texto: frase, canal, quien }])
      const r = await api.post('/agent/command', {
        texto: frase,
        usuario_id: quien.id,
        cirugia_id: cid,
        pending_id: p?.id || null,
        canal,
      })
      setEnviando(false)
      const res = r.ok ? r.data : { estado: 'error', texto: r.data?.texto || 'Error de comunicación con el servidor.' }
      setHistorial((h) => [...h, { tipo: 'agente', ...res }])
      if (res.estado === 'confirmar') setPendiente({ id: res.pending_id, expira: Date.now() + (res.expira_en || 60) * 1000 })
      else setPendiente(null)
      if (!mudo) voz.hablar(res.texto)
      onRespuesta?.(res)
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [onRespuesta],
  )

  const voz = useVoz((t) => enviar(t, 'voz'))

  useEffect(() => {
    finRef.current?.scrollIntoView({ block: 'nearest' })
  }, [historial])

  useEffect(() => {
    if (!pendiente) return
    const t = setInterval(() => {
      const s = Math.max(0, Math.round((pendiente.expira - Date.now()) / 1000))
      setRestante(s)
      if (s === 0) setPendiente(null)
    }, 250)
    return () => clearInterval(t)
  }, [pendiente])

  // Push-to-talk con la barra espaciadora (fuera de campos de texto)
  useEffect(() => {
    const enCampo = (e) => ['INPUT', 'TEXTAREA', 'SELECT'].includes(e.target.tagName)
    const abajo = (e) => {
      if (e.code === 'Space' && !e.repeat && !enCampo(e)) {
        e.preventDefault()
        voz.iniciar()
      }
    }
    const arriba = (e) => {
      if (e.code === 'Space' && !enCampo(e)) {
        e.preventDefault()
        voz.detener()
      }
    }
    window.addEventListener('keydown', abajo)
    window.addEventListener('keyup', arriba)
    return () => {
      window.removeEventListener('keydown', abajo)
      window.removeEventListener('keyup', arriba)
    }
  }, [voz])

  const usarFrase = (f) => {
    const u = usuarios.find((x) => x.rol === f.rol)
    if (u && u.id !== usuario.id) onCambiarUsuario(u)
    enviar(f.texto, 'texto', u || usuario)
  }

  return (
    <Card
      titulo="Agente de voz"
      extra={
        <label className="flex cursor-pointer items-center gap-1 text-xs text-slate-500">
          <input type="checkbox" checked={!silencio} onChange={(e) => setSilencio(!e.target.checked)} />
          Respuesta hablada
        </label>
      }
    >
      <div className="flex items-center gap-4">
        <button
          onPointerDown={(e) => {
            e.preventDefault()
            voz.iniciar()
          }}
          onPointerUp={voz.detener}
          onPointerLeave={() => voz.escuchando && voz.detener()}
          disabled={!voz.soportado}
          className={`relative isolate flex h-20 w-20 shrink-0 select-none items-center justify-center rounded-full text-white shadow-lg transition ${
            voz.escuchando ? 'onda bg-red-600' : 'bg-slate-900 hover:bg-slate-700'
          } disabled:bg-slate-300`}
          title="Mantenga presionado para hablar (o la barra espaciadora)"
        >
          <svg viewBox="0 0 24 24" className="h-9 w-9" fill="currentColor">
            <path d="M12 14a3 3 0 0 0 3-3V5a3 3 0 0 0-6 0v6a3 3 0 0 0 3 3Zm5-3a5 5 0 0 1-10 0H5a7 7 0 0 0 6 6.92V21h2v-3.08A7 7 0 0 0 19 11h-2Z" />
          </svg>
        </button>
        <div className="min-w-0 flex-1 text-sm">
          <div className="font-semibold">
            {voz.escuchando ? 'Escuchando…' : enviando ? 'Procesando…' : 'Mantenga presionado para hablar'}
          </div>
          <div className="text-xs text-slate-500">
            Habla como <span className="font-medium text-slate-700">{usuario.nombre}</span> ({ROL_NOMBRE[usuario.rol]}).
            Atajo: barra espaciadora.
          </div>
          {voz.parcial && <div className="mt-1 italic text-slate-700">«{voz.parcial}»</div>}
          {!voz.soportado && (
            <div className="mt-1 text-xs text-red-600">
              Este navegador no soporta reconocimiento de voz. Use Chrome o el campo de texto.
            </div>
          )}
          {voz.error && <div className="mt-1 text-xs text-red-600">{voz.error}</div>}
        </div>
      </div>

      {pendiente && (
        <div className="mt-3 flex items-center justify-between gap-2 rounded-lg border-2 border-amber-400 bg-amber-50 p-2.5">
          <span className="text-sm font-semibold text-amber-900">Esperando confirmación · {restante}s</span>
          <div className="flex gap-2">
            <Boton variante="exito" onClick={() => enviar('sí', 'texto')}>
              Sí, confirmo
            </Boton>
            <Boton variante="secundario" onClick={() => enviar('no, cancela', 'texto')}>
              No, cancela
            </Boton>
          </div>
        </div>
      )}

      <div className="mt-3 max-h-64 space-y-2 overflow-y-auto pr-1">
        {historial.length === 0 && (
          <p className="text-sm text-slate-400">
            Ejemplos: «¿Qué nos falta para completar esta fase?», «Se utilizaron tres gasas adicionales».
          </p>
        )}
        {historial.map((m, i) =>
          m.tipo === 'usuario' ? (
            <div key={i} className="ml-8 rounded-lg bg-slate-800 px-3 py-2 text-sm text-white">
              <div className="text-[10px] uppercase tracking-wide text-slate-400">
                {m.quien.nombre} · {m.canal}
              </div>
              {m.texto}
            </div>
          ) : (
            <div key={i} className={`mr-8 rounded-lg border px-3 py-2 text-sm ${ESTILO_ESTADO[m.estado] || ''}`}>
              <div className="text-[10px] font-semibold uppercase tracking-wide opacity-60">Agente · {m.estado}</div>
              {m.texto}
              {m.datos?.pendientes?.length > 0 && (
                <ul className="mt-1 list-disc pl-5 text-xs">
                  {m.datos.pendientes.map((p) => (
                    <li key={p}>{p}</li>
                  ))}
                </ul>
              )}
            </div>
          ),
        )}
        <div ref={finRef} />
      </div>

      <form
        className="mt-3 flex gap-2"
        onSubmit={(e) => {
          e.preventDefault()
          enviar(texto, 'texto')
          setTexto('')
        }}
      >
        <input
          value={texto}
          onChange={(e) => setTexto(e.target.value)}
          placeholder="Escriba un comando (respaldo del micrófono)"
          className="flex-1 rounded-lg border border-slate-300 px-3 py-1.5 text-sm outline-none focus:border-sky-500"
        />
        <Boton type="submit" disabled={!texto.trim() || enviando}>
          Enviar
        </Boton>
      </form>

      <div className="mt-3">
        <button
          onClick={() => setMostrarFrases((v) => !v)}
          className="text-xs font-semibold uppercase tracking-wide text-slate-500 hover:text-slate-700"
        >
          {mostrarFrases ? '▾' : '▸'} Frases de demo
        </button>
        {mostrarFrases && (
          <div className="mt-2 flex flex-wrap gap-1.5">
            {FRASES_DEMO.map((f) => (
              <button
                key={f.texto}
                onClick={() => usarFrase(f)}
                className="rounded-full border border-slate-200 bg-slate-50 px-2.5 py-1 text-left text-xs hover:border-sky-300 hover:bg-sky-50"
                title={`Se envía como ${ROL_NOMBRE[f.rol]}`}
              >
                {f.texto} <span className="text-slate-400">· {ROL_NOMBRE[f.rol]}</span>
              </button>
            ))}
          </div>
        )}
      </div>
    </Card>
  )
}

import { useCallback, useEffect, useRef, useState } from 'react'
import { ROL_COLOR, ROL_NOMBRE, api } from './api'
import AgenteVoz from './components/AgenteVoz'
import Gestion from './components/Gestion'
import Quirofano from './components/Quirofano'
import Trazabilidad from './components/Trazabilidad'
import { Badge, Boton, Proveedores, useDialogo, useToast } from './components/ui'

const VISTAS = [
  ['quirofano', 'Tablero de quirófano'],
  ['gestion', 'Panel de gestión'],
  ['trazabilidad', 'Trazabilidad'],
]

function SelectorInicial({ usuarios, onElegir }) {
  return (
    <div className="fixed inset-0 z-40 flex items-center justify-center bg-slate-900/80 p-4">
      <div className="w-full max-w-2xl rounded-2xl bg-white p-6 shadow-2xl">
        <h2 className="text-xl font-bold">¿Quién está usando el tablero?</h2>
        <p className="mt-1 text-sm text-slate-500">
          Cada acción queda registrada con su usuario, rol y hora. (Simula el inicio de sesión.)
        </p>
        <div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-3">
          {usuarios.map((u) => (
            <button
              key={u.id}
              onClick={() => onElegir(u)}
              className="rounded-xl border-2 border-slate-200 p-4 text-left transition hover:border-sky-500 hover:bg-sky-50"
            >
              <div className="font-semibold">{u.nombre}</div>
              <Badge className={`mt-2 ${ROL_COLOR[u.rol]}`}>{ROL_NOMBRE[u.rol]}</Badge>
            </button>
          ))}
        </div>
      </div>
    </div>
  )
}

function Tablero() {
  const pedir = useDialogo()
  const toast = useToast()
  const [usuarios, setUsuarios] = useState([])
  const [usuario, setUsuario] = useState(null)
  const [cirugias, setCirugias] = useState([])
  const [cirugiaId, setCirugiaId] = useState(null)
  const [estado, setEstado] = useState(null)
  const [vista, setVista] = useState(() => location.hash.replace('#', '') || 'quirofano')
  const [resaltar, setResaltar] = useState({ secciones: new Set(), refs: {} })
  const [version, setVersion] = useState(0)
  const [conexion, setConexion] = useState(true)
  const timerResaltado = useRef(null)
  const cargando = useRef(false)

  useEffect(() => {
    location.hash = vista
  }, [vista])

  const cargarListas = useCallback(async () => {
    const [u, c] = await Promise.all([api.get('/usuarios'), api.get('/cirugias')])
    if (u.ok) {
      setUsuarios(u.data)
      const guardado = Number(localStorage.getItem('usuario_id'))
      setUsuario((actual) => actual || u.data.find((x) => x.id === guardado) || null)
    }
    if (c.ok) {
      setCirugias(c.data)
      setCirugiaId((actual) => actual ?? c.data.find((x) => x.estado === 'en_curso')?.id ?? c.data[0]?.id)
    }
  }, [])

  useEffect(() => {
    cargarListas()
  }, [cargarListas])

  const refrescar = useCallback(async () => {
    if (!cirugiaId || cargando.current) return
    cargando.current = true
    try {
      const r = await api.get(`/cirugias/${cirugiaId}`)
      setConexion(r.ok)
      if (r.ok) setEstado(r.data)
    } catch {
      setConexion(false)
    } finally {
      cargando.current = false
    }
  }, [cirugiaId])

  useEffect(() => {
    refrescar()
    const t = setInterval(refrescar, 2000)
    return () => clearInterval(t)
  }, [refrescar])

  const marcar = useCallback((secciones = [], refs = {}) => {
    clearTimeout(timerResaltado.current)
    setResaltar({ secciones: new Set(secciones), refs })
    timerResaltado.current = setTimeout(() => setResaltar({ secciones: new Set(), refs: {} }), 2600)
  }, [])

  const elegirUsuario = (u) => {
    setUsuario(u)
    localStorage.setItem('usuario_id', u.id)
  }

  /** Ejecuta una acción de pantalla con el mismo manejo de confirmaciones y bloqueos que el agente. */
  const ejecutar = useCallback(
    async ({ metodo = 'post', url, body = {}, cambios = [], refs = {}, exito }) => {
      const base = { usuario_id: usuario.id, ...body }
      let r = await api[metodo](url, base)
      if (r.status === 409 && r.data?.estado === 'confirmar') {
        const ok = await pedir({ titulo: 'Confirmación requerida', mensaje: r.data.texto, confirmar: 'Sí, confirmar', peligro: true })
        if (!ok) {
          toast('Cancelado. No se registró nada.')
          return null
        }
        r = await api[metodo](url, { ...base, confirmado: true })
      }
      if (!r.ok && r.data?.datos?.requiere_justificacion) {
        const just = await pedir({
          titulo: 'Autorización con justificación',
          mensaje: r.data.texto,
          campo: 'Justificación (obligatoria)',
          requerido: true,
          confirmar: 'Autorizar',
          peligro: true,
        })
        if (!just) {
          await refrescar()
          return null
        }
        r = await api[metodo](url, { ...base, justificacion: just })
      }
      if (!r.ok) {
        toast(r.data?.texto || 'Error', 'error')
        marcar(['trazabilidad'])
        await refrescar()
        return null
      }
      toast(exito ? exito(r.data) : 'Registrado', 'ok')
      marcar([...cambios, 'trazabilidad', ...(r.data?.alertas_nuevas?.length ? ['alertas'] : [])], refs)
      await refrescar()
      setVersion((v) => v + 1)
      return r.data
    },
    [usuario, pedir, toast, marcar, refrescar],
  )

  const onRespuestaAgente = useCallback(
    async (res) => {
      marcar([...(res.cambios || []), ...(res.alertas_nuevas?.length ? ['alertas'] : [])], res.refs || {})
      await refrescar()
      setVersion((v) => v + 1)
    },
    [marcar, refrescar],
  )

  const reiniciar = async () => {
    const ok = await pedir({
      titulo: 'Reiniciar demo',
      mensaje: 'Se borran todos los registros y se vuelve a cargar la semilla. ¿Continuar?',
      confirmar: 'Reiniciar',
      peligro: true,
    })
    if (!ok) return
    await api.post('/demo/reset')
    setEstado(null)
    setCirugiaId(null)
    await cargarListas()
    setVersion((v) => v + 1)
    toast('Datos de demo reiniciados', 'ok')
  }

  const abrirCirugia = (id) => {
    setCirugiaId(id)
    setEstado(null)
    setVista('quirofano')
  }

  return (
    <div className="min-h-screen">
      <header className="no-print sticky top-0 z-30 bg-slate-900 text-white shadow">
        <div className="mx-auto flex max-w-[1600px] flex-wrap items-center gap-4 px-4 py-2.5">
          <div className="flex items-center gap-2">
            <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-sky-500 text-lg font-black">+</div>
            <div>
              <div className="text-sm font-bold leading-tight">Tablero Inteligente de Seguridad Quirúrgica</div>
              <div className="text-xs text-slate-400">Registrar sin dejar de operar</div>
            </div>
          </div>
          <nav className="flex gap-1">
            {VISTAS.map(([id, nombre]) => (
              <button
                key={id}
                onClick={() => setVista(id)}
                className={`rounded-lg px-3 py-1.5 text-sm font-medium ${
                  vista === id ? 'bg-white text-slate-900' : 'text-slate-300 hover:bg-slate-800'
                }`}
              >
                {nombre}
              </button>
            ))}
          </nav>
          <div className="ml-auto flex items-center gap-3">
            {!conexion && <Badge className="bg-red-600 text-white">Sin conexión con el servidor</Badge>}
            <select
              value={cirugiaId ?? ''}
              onChange={(e) => abrirCirugia(Number(e.target.value))}
              className="max-w-64 rounded-lg bg-slate-800 px-2 py-1.5 text-sm"
            >
              {cirugias.map((c) => (
                <option key={c.id} value={c.id}>
                  {c.estado === 'en_curso' ? '● ' : ''}
                  {c.procedimiento} · {c.paciente}
                </option>
              ))}
            </select>
            <select
              value={usuario?.id ?? ''}
              onChange={(e) => elegirUsuario(usuarios.find((u) => u.id === Number(e.target.value)))}
              className="rounded-lg bg-slate-800 px-2 py-1.5 text-sm"
              title="Usuario activo"
            >
              {usuarios.map((u) => (
                <option key={u.id} value={u.id}>
                  {u.nombre} · {ROL_NOMBRE[u.rol]}
                </option>
              ))}
            </select>
            <Boton variante="secundario" onClick={reiniciar} className="!bg-slate-800 !text-slate-200 !border-slate-700">
              Reiniciar demo
            </Boton>
          </div>
        </div>
      </header>

      <main className="mx-auto max-w-[1600px] p-4">
        {!estado || !usuario ? (
          <p className="text-slate-500">{conexion ? 'Cargando…' : 'No se pudo conectar con la API en el puerto 8000.'}</p>
        ) : vista === 'gestion' ? (
          <Gestion onAbrir={abrirCirugia} version={version} />
        ) : vista === 'trazabilidad' ? (
          <Trazabilidad cirugiaId={cirugiaId} estado={estado} usuarios={usuarios} version={version} />
        ) : (
          <Quirofano
            estado={estado}
            usuario={usuario}
            ejecutar={ejecutar}
            resaltar={resaltar.secciones}
            refs={resaltar.refs}
            onVerTrazabilidad={() => setVista('trazabilidad')}
            agente={
              estado.cirugia.estado !== 'finalizada' && (
                <AgenteVoz
                  key={cirugiaId}
                  usuario={usuario}
                  usuarios={usuarios}
                  cirugiaId={cirugiaId}
                  onRespuesta={onRespuestaAgente}
                  onCambiarUsuario={elegirUsuario}
                />
              )
            }
          />
        )}
      </main>

      {usuarios.length > 0 && !usuario && <SelectorInicial usuarios={usuarios} onElegir={elegirUsuario} />}
    </div>
  )
}

export default function App() {
  return (
    <Proveedores>
      <Tablero />
    </Proveedores>
  )
}

