"""Motor de alertas R1–R9.

Cada regla devuelve las alertas que *deberían* estar activas según el estado actual.
`evaluar_alertas` las compara con las activas en la BD: crea las nuevas, actualiza las
existentes y resuelve automáticamente las que ya no se cumplen (RN-10). Las alertas de una
regla desactivada desde gestión pasan a estado "suprimida".
"""

import json
import math
from dataclasses import dataclass
from datetime import datetime

from sqlmodel import Session, select

from app.catalogos import CAMPOS_OBLIGATORIOS_PACIENTE, UMBRAL_PREVENTIVO_PCT
from app.models import (
    HITOS,
    ORDEN_HITOS,
    Alerta,
    ChecklistItem,
    Cirugia,
    Configuracion,
    Insumo,
    InsumoCatalogo,
    Novedad,
    Paciente,
    ReglaAlerta,
)


@dataclass
class Contexto:
    cir: Cirugia
    pac: Paciente
    items: list
    insumos: list
    novedades: list
    catalogo: dict
    pct: int


def umbral_pct(session: Session) -> int:
    fila = session.get(Configuracion, "umbral_preventivo_pct")
    try:
        return int(fila.valor) if fila else UMBRAL_PREVENTIVO_PCT
    except ValueError:
        return UMBRAL_PREVENTIVO_PCT


def umbral_insumo(ins: Insumo, catalogo: dict, pct: int) -> int:
    cat = catalogo.get(ins.catalogo_id)
    if cat is not None and cat.umbral_preventivo is not None:
        return cat.umbral_preventivo
    return max(1, math.floor(ins.cantidad_inicial * pct / 100))


def _pendiente(items, codigo):
    it = next((i for i in items if i.codigo == codigo), None)
    return it is not None and it.estado != "verificado"


def r1_datos_paciente(c: Contexto):
    faltan = [et for campo, et in CAMPOS_OBLIGATORIOS_PACIENTE.items() if getattr(c.pac, campo) in (None, "")]
    if faltan:
        yield ("R1", "paciente", "media", f"Datos obligatorios del paciente faltantes: {', '.join(faltan)}.",
               {"faltantes": faltan})


def r2_sitio(c: Contexto):
    if c.cir.t_ingreso and _pendiente(c.items, "F1-SITIO"):
        sev = "alta" if c.cir.fase_actual >= 2 else "media"
        yield ("R2", "F1-SITIO", sev, "Sitio quirúrgico sin confirmar.", {"sitio_programado": c.cir.sitio_programado})


def r3_discrepancia(c: Contexto):
    cir = c.cir
    if cir.procedimiento_registrado and cir.procedimiento_registrado != cir.procedimiento_programado:
        yield ("R3", "procedimiento", "alta",
               f"El procedimiento registrado ({cir.procedimiento_registrado}) no coincide con el programado "
               f"({cir.procedimiento_programado}).",
               {"programado": cir.procedimiento_programado, "registrado": cir.procedimiento_registrado})
    if cir.sitio_registrado and cir.sitio_registrado != cir.sitio_programado:
        yield ("R3", "sitio", "alta",
               f"El sitio registrado ({cir.sitio_registrado}) no coincide con el programado ({cir.sitio_programado}).",
               {"programado": cir.sitio_programado, "registrado": cir.sitio_registrado})


def r4_antibiotico(c: Contexto):
    if c.cir.fase_actual >= 2 and _pendiente(c.items, "F2-ANTIB"):
        yield ("R4", "F2-ANTIB", "alta", "Antibiótico profiláctico sin registrar antes de la incisión.", {})


def r5_alergia(c: Contexto):
    alergias = (c.pac.alergias or "").strip().lower()
    if alergias and alergias not in ("ninguna", "ninguna conocida", "no refiere") and _pendiente(c.items, "F1-ALERG"):
        yield ("R5", "F1-ALERG", "baja", f"Alergia registrada ({c.pac.alergias}) pendiente de validación.",
               {"alergias": c.pac.alergias})


def _info_insumo(ins, umbral):
    return {"insumo": ins.nombre, "inicial": ins.cantidad_inicial, "utilizado": ins.cantidad_utilizada,
            "disponible": ins.cantidad_disponible, "umbral": umbral, "unidad": ins.unidad}


def r6_agotado(c: Contexto):
    for ins in c.insumos:
        if ins.cantidad_inicial > 0 and ins.cantidad_disponible <= 0:
            yield ("R6", f"insumo:{ins.id}", "alta", f"Alerta: {ins.nombre.lower()} agotadas." if ins.nombre.endswith("s")
                   else f"Alerta: {ins.nombre.lower()} agotado.", _info_insumo(ins, umbral_insumo(ins, c.catalogo, c.pct)))


def r9_preventivo(c: Contexto):
    for ins in c.insumos:
        umbral = umbral_insumo(ins, c.catalogo, c.pct)
        if ins.cantidad_inicial > 0 and 0 < ins.cantidad_disponible <= umbral:
            yield ("R9", f"insumo:{ins.id}", "media",
                   f"Advertencia: quedan {ins.cantidad_disponible} {ins.unidad} de {ins.nombre.lower()}. "
                   f"El insumo se encuentra próximo a agotarse.", _info_insumo(ins, umbral))


def r7_recuento(c: Contexto):
    if c.cir.t_fin_cirugia:
        pend = [i.descripcion for i in c.items if i.tipo == "recuento" and i.estado != "verificado"]
        if pend:
            yield ("R7", "recuentos", "alta", f"Recuento pendiente: {', '.join(pend)}.", {"pendientes": pend})


def r8_novedad_tiempos(c: Contexto):
    for nov in c.novedades:
        if nov.estado == "abierta":
            sev = "alta" if nov.severidad == "alta" else "media"
            yield ("R8", f"novedad:{nov.id}", sev, f"Novedad #{nov.numero} sin resolver: {nov.descripcion}",
                   {"novedad": nov.numero, "categoria": nov.categoria})
    previo = None
    for hito in ORDEN_HITOS:
        t = getattr(c.cir, HITOS[hito][0])
        if t is None:
            continue
        if previo and t < previo[1]:
            yield ("R8", f"tiempos:{hito}", "media",
                   f"Inconsistencia de tiempos: {HITOS[hito][1]} es anterior a {HITOS[previo[0]][1]}.", {})
        previo = (hito, t)


REGLAS = [r1_datos_paciente, r2_sitio, r3_discrepancia, r4_antibiotico, r5_alergia,
          r6_agotado, r7_recuento, r8_novedad_tiempos, r9_preventivo]


def evaluar_alertas(session: Session, cirugia_id: int) -> list[Alerta]:
    """Reevalúa las reglas para una cirugía. Devuelve las alertas recién creadas."""
    cir = session.get(Cirugia, cirugia_id)
    if cir is None:
        return []
    reglas = {r.codigo: r for r in session.exec(select(ReglaAlerta)).all()}
    ctx = Contexto(
        cir=cir,
        pac=session.get(Paciente, cir.paciente_id),
        items=session.exec(select(ChecklistItem).where(ChecklistItem.cirugia_id == cirugia_id)).all(),
        insumos=session.exec(select(Insumo).where(Insumo.cirugia_id == cirugia_id)).all(),
        novedades=session.exec(select(Novedad).where(Novedad.cirugia_id == cirugia_id)).all(),
        catalogo={c.id: c for c in session.exec(select(InsumoCatalogo)).all()},
        pct=umbral_pct(session),
    )

    esperadas = {}
    for regla in REGLAS:
        for codigo, ref, sev, msg, detalle in regla(ctx):
            conf = reglas.get(codigo)
            if conf is not None and not conf.activa:
                continue
            esperadas[(codigo, ref)] = (sev, msg, detalle)

    ahora = datetime.now()
    activas = session.exec(select(Alerta).where(Alerta.cirugia_id == cirugia_id, Alerta.estado == "activa")).all()
    nuevas, vistas = [], set()
    for al in activas:
        clave = (al.regla, al.referencia)
        if clave in esperadas:
            sev, msg, detalle = esperadas[clave]
            if sev == "alta" and al.severidad != "alta":
                al.interrumpe = True
                al.reconocida_por = al.reconocida_en = None
            al.severidad, al.mensaje = sev, msg
            al.detalle = json.dumps(detalle, ensure_ascii=False)
            vistas.add(clave)
        else:
            conf = reglas.get(al.regla)
            al.estado = "suprimida" if conf is not None and not conf.activa else "resuelta"
            al.resuelta_en = ahora
        session.add(al)

    for (codigo, ref), (sev, msg, detalle) in esperadas.items():
        if (codigo, ref) in vistas:
            continue
        conf = reglas.get(codigo)
        al = Alerta(cirugia_id=cirugia_id, regla=codigo, referencia=ref, severidad=sev, mensaje=msg,
                    detalle=json.dumps(detalle, ensure_ascii=False),
                    accion_requerida=conf.accion_requerida if conf else None,
                    interrumpe=sev == "alta" or bool(conf and conf.modal))
        session.add(al)
        nuevas.append(al)
    session.flush()
    return nuevas


def reevaluar_en_curso(session: Session) -> None:
    for cir in session.exec(select(Cirugia).where(Cirugia.estado != "finalizada")).all():
        evaluar_alertas(session, cir.id)

"""Lógica de negocio única. La usan tanto los endpoints de la UI como el agente de voz.

Todo cambio de estado termina en `registrar_accion`, que escribe la trazabilidad y
reevalúa las alertas.
"""

import json
from dataclasses import dataclass
from datetime import datetime
from typing import Optional

from sqlmodel import Session, func, select

from app.catalogos import (
    CAMPOS_OBLIGATORIOS_PACIENTE,
    CATEGORIAS_NOVEDAD,
    CHECKLIST_PLANTILLA,
    GRUPOS_SANGUINEOS,
    TIPOS_ANESTESIA,
)
from app.models import (
    BLOQUES_FASE1,
    FASES,
    HITOS,
    ORDEN_HITOS,
    Alerta,
    AnestesiaRegistro,
    ChecklistItem,
    Cirugia,
    Consumo,
    Dren,
    EquipoQuirurgico,
    Insumo,
    InsumoCatalogo,
    Novedad,
    Paciente,
    ProcedimientoInsumo,
    TipoPersona,
    TipoProcedimiento,
    Trazabilidad,
    Usuario,
)
from app.rules import evaluar_alertas, umbral_insumo, umbral_pct

# Fase que debe estar cerrada antes de cada hito (fase_actual mínima); se puede autorizar con justificación
FASE_REQUERIDA_HITO = {"inicio_cirugia": 3, "salida_recuperacion": 4}
BLOQUE = {b[0]: b for b in BLOQUES_FASE1}


@dataclass
class Ctx:
    usuario: Usuario
    canal: str = "ui"
    transcripcion: Optional[str] = None


class ErrorNegocio(Exception):
    def __init__(self, mensaje: str, resultado: str = "rechazado", datos: Optional[dict] = None,
                 status: int = 422):
        super().__init__(mensaje)
        self.mensaje = mensaje
        self.resultado = resultado
        self.datos = datos or {}
        self.status = status


class PermisoDenegado(ErrorNegocio):
    def __init__(self, mensaje: str):
        super().__init__(mensaje, resultado="rechazado", status=403)


class RequiereConfirmacion(Exception):
    def __init__(self, mensaje: str, datos: Optional[dict] = None):
        super().__init__(mensaje)
        self.mensaje = mensaje
        self.datos = datos or {}


def hhmm(dt) -> str:
    if isinstance(dt, str):
        dt = datetime.fromisoformat(dt)
    return dt.strftime("%H:%M") if dt else "--:--"


# ---------------------------------------------------------------- trazabilidad

def _traza(session: Session, cirugia_id: Optional[int], ctx: Optional[Ctx], accion: str, entidad: str,
           entidad_id: Optional[int] = None, detalle: Optional[dict] = None, resultado: str = "ok",
           canal: Optional[str] = None):
    session.add(Trazabilidad(
        cirugia_id=cirugia_id,
        usuario_id=ctx.usuario.id if ctx else None,
        rol=ctx.usuario.rol if ctx else None,
        accion=accion,
        entidad=entidad,
        entidad_id=entidad_id,
        detalle=json.dumps(detalle or {}, ensure_ascii=False, default=str),
        resultado=resultado,
        canal=canal or (ctx.canal if ctx else "sistema"),
        transcripcion=ctx.transcripcion if ctx else None,
    ))


def registrar_accion(session: Session, cirugia_id: Optional[int], ctx: Optional[Ctx], accion: str,
                     entidad: str, entidad_id: Optional[int] = None,
                     detalle: Optional[dict] = None, resultado: str = "ok") -> list[Alerta]:
    _traza(session, cirugia_id, ctx, accion, entidad, entidad_id, detalle, resultado)
    session.flush()
    if resultado != "ok" or cirugia_id is None:
        return []
    nuevas = evaluar_alertas(session, cirugia_id)
    for al in nuevas:
        _traza(session, cirugia_id, None, "alerta_generada", "alerta", al.id,
               {"regla": al.regla, "mensaje": al.mensaje, "severidad": al.severidad})
    return nuevas


def _rechazar(session: Session, cirugia_id: Optional[int], ctx: Ctx, accion: str, entidad: str,
              entidad_id: Optional[int], mensaje: str, resultado: str = "rechazado",
              datos: Optional[dict] = None, permiso: bool = False):
    registrar_accion(session, cirugia_id, ctx, accion, entidad, entidad_id,
                     {"motivo": mensaje, **(datos or {})}, resultado=resultado)
    session.commit()
    if permiso:
        raise PermisoDenegado(mensaje)
    raise ErrorNegocio(mensaje, resultado=resultado, datos=datos)


def registrar_cancelacion(session: Session, cirugia_id: int, ctx: Ctx, accion: str, detalle: dict):
    registrar_accion(session, cirugia_id, ctx, accion, "agente", None, detalle, resultado="cancelado")
    session.commit()


def _alertas(nuevas) -> list[dict]:
    return [serializar_alerta(a) for a in nuevas]


# -------------------------------------------------------------------- permisos

def tipo_persona(session: Session, codigo: str) -> Optional[TipoPersona]:
    return session.exec(select(TipoPersona).where(TipoPersona.codigo == codigo)).first()


def nombre_rol(session: Session, codigo: Optional[str]) -> Optional[str]:
    if not codigo:
        return None
    t = tipo_persona(session, codigo)
    return t.nombre if t else codigo


def puede_operar(session: Session, usuario: Usuario) -> bool:
    t = tipo_persona(session, usuario.rol)
    return bool(usuario.activo and t and t.activo and t.acceso_operativo)


def puede_configurar(session: Session, usuario: Usuario) -> bool:
    t = tipo_persona(session, usuario.rol)
    return bool(usuario.activo and t and t.activo and (t.puede_configurar or t.acceso_operativo))


def _cirugia(session: Session, cirugia_id: int) -> Cirugia:
    cir = session.get(Cirugia, cirugia_id)
    if cir is None:
        raise ErrorNegocio("La cirugía no existe.", status=404)
    return cir


def _exigir_operativo(session: Session, cir: Optional[Cirugia], ctx: Ctx, accion: str, entidad: str,
                      entidad_id: Optional[int] = None):
    if not puede_operar(session, ctx.usuario):
        _rechazar(session, cir.id if cir else None, ctx, accion, entidad, entidad_id,
                  f"{ctx.usuario.nombre} ({nombre_rol(session, ctx.usuario.rol)}) no tiene acceso operativo; "
                  f"solo puede consultar.", permiso=True)
    if cir is not None and cir.estado == "finalizada":
        _rechazar(session, cir.id, ctx, accion, entidad, entidad_id,
                  "La cirugía ya finalizó; no admite nuevos registros.")


def exigir_configurador(session: Session, ctx: Ctx, accion: str, entidad: str):
    if not puede_configurar(session, ctx.usuario):
        _rechazar(session, None, ctx, accion, entidad, None,
                  f"{ctx.usuario.nombre} no tiene permiso para modificar la configuración.", permiso=True)


# ----------------------------------------------------------------------- hitos

def _hora_hito(cir: Cirugia, hito: str):
    return getattr(cir, HITOS[hito][0])


def _marcar_hito(session: Session, cir: Cirugia, hito: str, ctx: Ctx, extra: Optional[dict] = None) -> datetime:
    ahora = datetime.now()
    setattr(cir, HITOS[hito][0], ahora)
    if hito == "preparacion" and cir.estado == "programada":
        cir.estado = "en_curso"
    if hito == "salida_recuperacion":
        cir.estado = "finalizada"
    session.add(cir)
    if HITOS[hito][2] or (extra or {}).get("automatico"):
        _traza(session, cir.id, ctx, "registrar_evento", "hito", None,
               {"hito": hito, "nombre": HITOS[hito][1], "hora": hhmm(ahora), "automatico": True, **(extra or {})})
    return ahora


def _asegurar_preparacion(session: Session, cir: Cirugia, ctx: Ctx):
    if cir.t_preparacion is None:
        _marcar_hito(session, cir, "preparacion", ctx, {"automatico": True})


def _completar_bloque(session: Session, cir: Cirugia, bloque: str, ctx: Ctx) -> Optional[str]:
    _, nombre, hito, _ = BLOQUE[bloque]
    if _hora_hito(cir, hito) is not None:
        return None
    pend = session.exec(select(ChecklistItem).where(
        ChecklistItem.cirugia_id == cir.id, ChecklistItem.bloque == bloque,
        ChecklistItem.obligatorio == True, ChecklistItem.estado != "verificado")).all()  # noqa: E712
    if pend:
        return None
    _marcar_hito(session, cir, hito, ctx, {"bloque": nombre})
    return hito


def registrar_evento(session: Session, cirugia_id: int, hito: str, ctx: Ctx,
                     justificacion: Optional[str] = None, simular: bool = False) -> dict:
    cir = _cirugia(session, cirugia_id)
    if hito not in HITOS:
        raise ErrorNegocio(f"Hito desconocido: {hito}.")
    campo, nombre, automatico = HITOS[hito]
    if automatico:
        bloque = next(b for b in BLOQUES_FASE1 if b[2] == hito)
        raise ErrorNegocio(f"«{nombre}» se registra automáticamente al completar «{bloque[1]}» en el checklist.")
    _exigir_operativo(session, cir, ctx, "registrar_evento", "hito")
    actual = getattr(cir, campo)
    if actual is not None:
        raise ErrorNegocio(f"«{nombre}» ya se registró a las {hhmm(actual)}.", status=409)
    idx = ORDEN_HITOS.index(hito)
    if idx > 0:
        previo = ORDEN_HITOS[idx - 1]
        if _hora_hito(cir, previo) is None:
            if HITOS[previo][2]:
                bloque = next(b for b in BLOQUES_FASE1 if b[2] == previo)
                msg = f"Primero complete «{bloque[1]}» en el checklist de la fase 1."
            else:
                msg = f"Primero debe registrarse «{HITOS[previo][1]}»."
            _rechazar(session, cir.id, ctx, "registrar_evento", "hito", None, msg, datos={"hito": hito})

    override = False
    requerida = FASE_REQUERIDA_HITO.get(hito)
    if requerida and cir.fase_actual < requerida:
        if not (justificacion and justificacion.strip()):
            _rechazar(session, cir.id, ctx, "registrar_evento", "hito", None,
                      f"No se puede registrar «{nombre}» sin cerrar la fase {requerida - 1} "
                      f"({FASES[requerida - 1]}). Se requiere una justificación para autorizarlo.",
                      resultado="bloqueado", datos={"hito": hito, "requiere_justificacion": True})
        override = True
    if simular:
        return {}

    ahora = _marcar_hito(session, cir, hito, ctx)
    detalle = {"hito": hito, "nombre": nombre, "hora": hhmm(ahora)}
    if override:
        detalle.update({"override": True, "justificacion": justificacion.strip()})
    nuevas = registrar_accion(session, cir.id, ctx, "registrar_evento", "hito", None, detalle)
    session.commit()
    return {"hito": hito, "hora": ahora.isoformat(), "override": override, "alertas_nuevas": _alertas(nuevas)}


# ------------------------------------------------------------------- checklist

def verificar_item(session: Session, cirugia_id: int, item_id: int, ctx: Ctx,
                   resultado: Optional[str] = None, simular: bool = False) -> dict:
    cir = _cirugia(session, cirugia_id)
    item = session.get(ChecklistItem, item_id)
    if item is None or item.cirugia_id != cirugia_id:
        raise ErrorNegocio("El ítem no existe en esta cirugía.", status=404)
    _exigir_operativo(session, cir, ctx, "verificar_item", "checklist_item", item.id)
    if item.estado == "verificado":
        quien = session.get(Usuario, item.verificado_por)
        raise ErrorNegocio(f"«{item.descripcion}» ya fue verificado por {quien.nombre if quien else '—'} "
                           f"a las {hhmm(item.verificado_en)}.", status=409)

    def rechazar(msg):
        _rechazar(session, cir.id, ctx, "verificar_item", "checklist_item", item.id, msg,
                  datos={"codigo": item.codigo})

    if item.fase > cir.fase_actual:
        rechazar(f"«{item.descripcion}» pertenece a la fase {item.fase} ({FASES[item.fase]}). "
                 f"Primero debe cerrarse la fase {cir.fase_actual}.")
    if item.fase == 1 and item.bloque:
        requisito = BLOQUE[item.bloque][3]
        if requisito and _hora_hito(cir, requisito) is None:
            if HITOS[requisito][2]:
                previo = next(b for b in BLOQUES_FASE1 if b[2] == requisito)
                rechazar(f"Primero complete «{previo[1]}» antes de «{BLOQUE[item.bloque][1]}».")
            rechazar(f"«{BLOQUE[item.bloque][1]}» empieza después de registrar «{HITOS[requisito][1]}».")
    if item.fase == 3 and cir.t_inicio_cirugia is None:
        rechazar("Las verificaciones de la fase 3 se registran después del inicio de la cirugía.")
    if item.tipo == "insumos":
        insumos = session.exec(select(Insumo).where(Insumo.cirugia_id == cir.id)).all()
        if not insumos:
            rechazar("No hay insumos cargados para esta cirugía.")
        sin_registrar = [i.nombre for i in insumos if i.inicial_registrada_en is None]
        if sin_registrar:
            rechazar(f"Falta registrar la cantidad inicial de: {', '.join(sin_registrar)}.")
    if item.tipo == "drenes" and cir.drenes_presentes is None:
        rechazar("Registre los drenes (tipo y cantidad) o indique que no hay drenes.")
    if simular:
        return {}

    if item.fase == 1:
        _asegurar_preparacion(session, cir, ctx)
    item.estado = "verificado"
    item.verificado_por = ctx.usuario.id
    item.verificado_en = datetime.now()
    item.resultado = (resultado or "Conforme").strip() or "Conforme"
    session.add(item)
    session.flush()
    hito_auto = _completar_bloque(session, cir, item.bloque, ctx) if item.bloque else None
    nuevas = registrar_accion(session, cir.id, ctx, "verificar_item", "checklist_item", item.id,
                              {"codigo": item.codigo, "descripcion": item.descripcion,
                               "fase": item.fase, "resultado": item.resultado})
    session.commit()
    return {"item": item.model_dump(), "hito_automatico": hito_auto, "alertas_nuevas": _alertas(nuevas)}


def pendientes_fase(session: Session, cirugia_id: int, fase: int, solo_obligatorios=True):
    q = select(ChecklistItem).where(ChecklistItem.cirugia_id == cirugia_id, ChecklistItem.fase == fase,
                                    ChecklistItem.estado != "verificado")
    if solo_obligatorios:
        q = q.where(ChecklistItem.obligatorio == True)  # noqa: E712
    return session.exec(q.order_by(ChecklistItem.id)).all()


def cerrar_fase(session: Session, cirugia_id: int, fase: int, ctx: Ctx, simular: bool = False) -> dict:
    cir = _cirugia(session, cirugia_id)
    _exigir_operativo(session, cir, ctx, "cerrar_fase", "fase", fase)
    if fase not in FASES:
        raise ErrorNegocio("La fase debe ser 1, 2 o 3.")
    if fase < cir.fase_actual:
        raise ErrorNegocio(f"La fase {fase} ya está cerrada.", status=409)
    if fase > cir.fase_actual:
        _rechazar(session, cir.id, ctx, "cerrar_fase", "fase", fase,
                  f"La fase actual es la {cir.fase_actual} ({FASES[cir.fase_actual]}).")

    def bloquear(msg, datos):
        _rechazar(session, cir.id, ctx, "cerrar_fase", "fase", fase, msg, resultado="bloqueado", datos=datos)

    pend = pendientes_fase(session, cir.id, fase)
    if pend:
        nombres = [p.descripcion for p in pend]
        bloquear(f"No se puede cerrar la fase {fase}. Faltan {len(pend)} verificaciones obligatorias: "
                 f"{'; '.join(nombres)}.", {"pendientes": nombres})
    if fase == 1 and cir.t_inicio_anestesia is None:
        bloquear("No se puede cerrar la fase 1 sin registrar «Inicio de anestesia».",
                 {"pendientes": ["Inicio de anestesia"]})
    if fase == 3:
        if cir.t_fin_cirugia is None:
            bloquear("No se puede cerrar la fase 3 sin registrar «Fin de cirugía».",
                     {"pendientes": ["Fin de cirugía"]})
        abiertas = session.exec(select(Novedad).where(Novedad.cirugia_id == cir.id,
                                                      Novedad.estado == "abierta")).all()
        if abiertas:
            bloquear(f"No se puede cerrar la fase 3 con {len(abiertas)} novedad(es) abierta(s).",
                     {"novedades_abiertas": [n.numero for n in abiertas]})
    if simular:
        return {}

    cir.fase_actual = fase + 1
    session.add(cir)
    nuevas = registrar_accion(session, cir.id, ctx, "cerrar_fase", "fase", fase,
                              {"fase": fase, "nombre": FASES[fase]})
    session.commit()
    return {"fase_actual": cir.fase_actual, "alertas_nuevas": _alertas(nuevas)}


# --------------------------------------------------------------------- insumos

def _insumo(session: Session, cirugia_id: int, insumo_id: int) -> Insumo:
    ins = session.get(Insumo, insumo_id)
    if ins is None or ins.cirugia_id != cirugia_id:
        raise ErrorNegocio("El insumo no existe en esta cirugía.", status=404)
    return ins


def establecer_cantidad_inicial(session: Session, cirugia_id: int, insumo_id: int, cantidad: int, ctx: Ctx,
                                simular: bool = False) -> dict:
    cir = _cirugia(session, cirugia_id)
    ins = _insumo(session, cirugia_id, insumo_id)
    _exigir_operativo(session, cir, ctx, "registrar_cantidad_inicial", "insumo", ins.id)
    if cantidad is None or cantidad < 0:
        raise ErrorNegocio("La cantidad inicial debe ser 0 o mayor.")
    if cantidad < ins.cantidad_utilizada:
        _rechazar(session, cir.id, ctx, "registrar_cantidad_inicial", "insumo", ins.id,
                  f"Ya se utilizaron {ins.cantidad_utilizada} {ins.unidad} de {ins.nombre.lower()}; "
                  f"la cantidad inicial no puede ser menor.")
    if simular:
        return {}
    _asegurar_preparacion(session, cir, ctx)
    antes = ins.cantidad_inicial if ins.inicial_registrada_en else None
    ins.cantidad_inicial = cantidad
    ins.inicial_registrada_por = ctx.usuario.id
    ins.inicial_registrada_en = datetime.now()
    session.add(ins)
    nuevas = registrar_accion(session, cir.id, ctx, "registrar_cantidad_inicial", "insumo", ins.id,
                              {"insumo": ins.nombre, "antes": antes, "despues": cantidad,
                               "disponible": ins.cantidad_disponible})
    session.commit()
    return {"insumo": serializar_insumo(session, ins), "alertas_nuevas": _alertas(nuevas)}


def agregar_insumo_cirugia(session: Session, cirugia_id: int, catalogo_id: int, ctx: Ctx) -> dict:
    cir = _cirugia(session, cirugia_id)
    cat = session.get(InsumoCatalogo, catalogo_id)
    if cat is None or not cat.activo:
        raise ErrorNegocio("El insumo no existe en el catálogo.", status=404)
    _exigir_operativo(session, cir, ctx, "agregar_insumo", "insumo")
    existe = session.exec(select(Insumo).where(Insumo.cirugia_id == cir.id, Insumo.catalogo_id == cat.id)).first()
    if existe:
        raise ErrorNegocio(f"{cat.nombre} ya está en el inventario de esta cirugía.", status=409)
    ins = Insumo(cirugia_id=cir.id, catalogo_id=cat.id, nombre=cat.nombre, aliases=cat.aliases, unidad=cat.unidad)
    session.add(ins)
    session.flush()
    nuevas = registrar_accion(session, cir.id, ctx, "agregar_insumo", "insumo", ins.id, {"insumo": cat.nombre})
    session.commit()
    return {"insumo": serializar_insumo(session, ins), "alertas_nuevas": _alertas(nuevas)}


def registrar_consumo(session: Session, cirugia_id: int, insumo_id: int, cantidad: int, ctx: Ctx,
                      confirmado: bool = False) -> dict:
    cir = _cirugia(session, cirugia_id)
    ins = _insumo(session, cirugia_id, insumo_id)
    _exigir_operativo(session, cir, ctx, "registrar_consumo", "insumo", ins.id)
    if cantidad is None or cantidad <= 0:
        raise ErrorNegocio("La cantidad debe ser mayor que cero.")

    def rechazar(msg, datos=None):
        _rechazar(session, cir.id, ctx, "registrar_consumo", "insumo", ins.id, msg, datos=datos)

    if ins.inicial_registrada_en is None or ins.cantidad_inicial == 0:
        rechazar(f"Primero registre la cantidad inicial de {ins.nombre.lower()} para esta cirugía.",
                 {"sugerencia": "registrar_cantidad_inicial"})
    disponible = ins.cantidad_disponible
    if disponible == 0:
        rechazar(f"{ins.nombre} está agotado. No se puede registrar el consumo; ¿desea registrar una novedad?",
                 {"sugerencia": "registrar_novedad"})
    if cantidad > disponible:
        rechazar(f"Solo quedan {disponible} {ins.unidad} de {ins.nombre.lower()}. No se registró el consumo "
                 f"de {cantidad}; ¿desea registrar una novedad?",
                 {"sugerencia": "registrar_novedad", "disponible": disponible})
    restante = disponible - cantidad
    if restante == 0 and not confirmado:
        raise RequiereConfirmacion(
            f"Con {cantidad} {ins.nombre.lower()} el disponible queda en 0 (agotado). ¿Confirma el consumo?",
            {"insumo_id": ins.id, "cantidad": cantidad})

    ins.cantidad_utilizada += cantidad
    session.add(ins)
    consumo = Consumo(cirugia_id=cir.id, insumo_id=ins.id, cantidad=cantidad, usuario_id=ctx.usuario.id,
                      confirmado=confirmado)
    session.add(consumo)
    session.flush()
    nuevas = registrar_accion(session, cir.id, ctx, "registrar_consumo", "insumo", ins.id,
                              {"insumo": ins.nombre, "cantidad": cantidad, "inicial": ins.cantidad_inicial,
                               "utilizado": ins.cantidad_utilizada, "restante": restante,
                               "consumo_id": consumo.id})
    session.commit()
    return {"insumo": serializar_insumo(session, ins), "restante": restante, "alertas_nuevas": _alertas(nuevas)}


# ------------------------------------------------------------------- novedades

PALABRAS_CATEGORIA = {
    "equipo": ("falla", "cable", "camara", "torre", "monitor", "electrobisturi", "equipo", "luz",
               "lampara", "maquina", "aspirador", "bateria"),
    "insumo": ("gasa", "sutura", "insumo", "falta", "agot", "trocar", "clip", "guante"),
    "paciente": ("paciente", "sangrado", "hipotension", "reaccion", "alergi", "saturacion"),
    "proceso": ("retraso", "demora", "espera", "consentimiento", "personal"),
}


def inferir_categoria(texto: str) -> str:
    from app.agent.normalizer import normalizar

    t = normalizar(texto)
    for cat, palabras in PALABRAS_CATEGORIA.items():
        if any(p in t for p in palabras):
            return cat
    return "otro"


def registrar_novedad(session: Session, cirugia_id: int, descripcion: str, ctx: Ctx,
                      severidad: str = "media", categoria: Optional[str] = None) -> dict:
    cir = _cirugia(session, cirugia_id)
    _exigir_operativo(session, cir, ctx, "registrar_novedad", "novedad")
    descripcion = (descripcion or "").strip()
    if len(descripcion) < 3:
        raise ErrorNegocio("La novedad necesita una descripción.")
    if severidad not in ("baja", "media", "alta"):
        severidad = "media"
    categoria = categoria if categoria in CATEGORIAS_NOVEDAD else inferir_categoria(descripcion)
    numero = (session.exec(select(func.count()).select_from(Novedad)
                           .where(Novedad.cirugia_id == cir.id)).one() or 0) + 1
    nov = Novedad(cirugia_id=cir.id, numero=numero, descripcion=descripcion, categoria=categoria,
                  severidad=severidad, registrada_por=ctx.usuario.id)
    session.add(nov)
    session.flush()
    nuevas = registrar_accion(session, cir.id, ctx, "registrar_novedad", "novedad", nov.id,
                              {"numero": numero, "descripcion": descripcion,
                               "categoria": categoria, "severidad": severidad})
    session.commit()
    return {"novedad": nov.model_dump(), "alertas_nuevas": _alertas(nuevas)}


def resolver_novedad(session: Session, novedad_id: int, accion_correctiva: str, ctx: Ctx,
                     simular: bool = False) -> dict:
    nov = session.get(Novedad, novedad_id)
    if nov is None:
        raise ErrorNegocio("La novedad no existe.", status=404)
    cir = _cirugia(session, nov.cirugia_id)
    _exigir_operativo(session, cir, ctx, "resolver_novedad", "novedad", nov.id)
    if nov.estado == "resuelta":
        raise ErrorNegocio(f"La novedad #{nov.numero} ya está resuelta.", status=409)
    accion_correctiva = (accion_correctiva or "").strip()
    if len(accion_correctiva) < 3:
        raise ErrorNegocio("Para resolver una novedad se requiere la acción correctiva.")
    if simular:
        return {}
    nov.estado = "resuelta"
    nov.resuelta_por = ctx.usuario.id
    nov.ts_resolucion = datetime.now()
    nov.accion_correctiva = accion_correctiva
    session.add(nov)
    nuevas = registrar_accion(session, cir.id, ctx, "resolver_novedad", "novedad", nov.id,
                              {"numero": nov.numero, "accion_correctiva": accion_correctiva})
    session.commit()
    return {"novedad": nov.model_dump(), "alertas_nuevas": _alertas(nuevas)}


# ------------------------------------------------------------------- anestesia

def nombre_tipo_anestesia(tipo: str) -> str:
    from app.agent.normalizer import normalizar

    t = normalizar(tipo)
    for nombre, aliases in TIPOS_ANESTESIA:
        if t == normalizar(nombre) or t in aliases.split("|"):
            return nombre
    return tipo.strip()[:1].upper() + tipo.strip()[1:]


def registrar_anestesia(session: Session, cirugia_id: int, tipo: str, ctx: Ctx,
                        observaciones: Optional[str] = None, simular: bool = False) -> dict:
    cir = _cirugia(session, cirugia_id)
    _exigir_operativo(session, cir, ctx, "registrar_anestesia", "anestesia")
    tipo = nombre_tipo_anestesia(tipo or "")
    if len(tipo) < 3:
        raise ErrorNegocio("Indique el tipo de anestesia.")
    existe = session.exec(select(AnestesiaRegistro).where(
        AnestesiaRegistro.cirugia_id == cir.id, AnestesiaRegistro.tipo == tipo,
        AnestesiaRegistro.estado == "activo")).first()
    if existe:
        raise ErrorNegocio(f"La anestesia «{tipo}» ya está registrada (desde las {hhmm(existe.ts)}).", status=409)
    if simular:
        return {}
    reg = AnestesiaRegistro(cirugia_id=cir.id, tipo=tipo, observaciones=(observaciones or "").strip() or None,
                            registrado_por=ctx.usuario.id)
    session.add(reg)
    session.flush()
    nuevas = registrar_accion(session, cir.id, ctx, "registrar_anestesia", "anestesia", reg.id,
                              {"tipo": tipo, "observaciones": reg.observaciones})
    session.commit()
    return {"anestesia": reg.model_dump(), "alertas_nuevas": _alertas(nuevas)}


def anular_anestesia(session: Session, registro_id: int, ctx: Ctx, motivo: Optional[str] = None) -> dict:
    reg = session.get(AnestesiaRegistro, registro_id)
    if reg is None:
        raise ErrorNegocio("El registro de anestesia no existe.", status=404)
    cir = _cirugia(session, reg.cirugia_id)
    _exigir_operativo(session, cir, ctx, "anular_anestesia", "anestesia", reg.id)
    if reg.estado == "anulado":
        raise ErrorNegocio("El registro ya estaba anulado.", status=409)
    reg.estado = "anulado"
    reg.anulado_por = ctx.usuario.id
    reg.ts_anulacion = datetime.now()
    session.add(reg)
    nuevas = registrar_accion(session, cir.id, ctx, "anular_anestesia", "anestesia", reg.id,
                              {"tipo": reg.tipo, "motivo": (motivo or "").strip() or None})
    session.commit()
    return {"anestesia": reg.model_dump(), "alertas_nuevas": _alertas(nuevas)}


# ---------------------------------------------------------------------- drenes

def _resumen_drenes(session: Session, cir: Cirugia) -> str:
    drenes = session.exec(select(Dren).where(Dren.cirugia_id == cir.id).order_by(Dren.numero)).all()
    if not drenes:
        return "Sin drenes"
    total = sum(d.cantidad for d in drenes)
    tipos = ", ".join(f"{d.cantidad} × {d.tipo or 'tipo sin especificar'}" for d in drenes)
    return f"{total} dren{'es' if total != 1 else ''}: {tipos}"


def _verificar_item_drenes(session: Session, cir: Cirugia, ctx: Ctx):
    item = session.exec(select(ChecklistItem).where(ChecklistItem.cirugia_id == cir.id,
                                                    ChecklistItem.tipo == "drenes")).first()
    if item is None or item.fase > cir.fase_actual:
        return
    if item.estado != "verificado":
        item.estado = "verificado"
        item.verificado_por = ctx.usuario.id
        item.verificado_en = datetime.now()
    item.resultado = _resumen_drenes(session, cir)
    session.add(item)


def registrar_dren(session: Session, cirugia_id: int, ctx: Ctx, tipo: Optional[str] = None, cantidad: int = 1,
                   observaciones: Optional[str] = None, simular: bool = False) -> dict:
    cir = _cirugia(session, cirugia_id)
    _exigir_operativo(session, cir, ctx, "registrar_dren", "dren")
    if cir.t_inicio_cirugia is None:
        _rechazar(session, cir.id, ctx, "registrar_dren", "dren", None,
                  "Los drenes se registran después del inicio de la cirugía.")
    if not cantidad or cantidad < 1:
        raise ErrorNegocio("La cantidad de drenes debe ser al menos 1.")
    if simular:
        return {}
    numero = (session.exec(select(func.count()).select_from(Dren).where(Dren.cirugia_id == cir.id)).one() or 0) + 1
    dren = Dren(cirugia_id=cir.id, numero=numero, tipo=(tipo or "").strip() or None, cantidad=cantidad,
                observaciones=(observaciones or "").strip() or None, registrado_por=ctx.usuario.id)
    session.add(dren)
    cir.drenes_presentes = True
    session.add(cir)
    session.flush()
    _verificar_item_drenes(session, cir, ctx)
    nuevas = registrar_accion(session, cir.id, ctx, "registrar_dren", "dren", dren.id,
                              {"numero": numero, "tipo": dren.tipo, "cantidad": cantidad,
                               "observaciones": dren.observaciones})
    session.commit()
    return {"dren": dren.model_dump(), "alertas_nuevas": _alertas(nuevas)}


def declarar_sin_drenes(session: Session, cirugia_id: int, ctx: Ctx, simular: bool = False) -> dict:
    cir = _cirugia(session, cirugia_id)
    _exigir_operativo(session, cir, ctx, "declarar_sin_drenes", "dren")
    if cir.t_inicio_cirugia is None:
        _rechazar(session, cir.id, ctx, "declarar_sin_drenes", "dren", None,
                  "Los drenes se registran después del inicio de la cirugía.")
    if session.exec(select(Dren).where(Dren.cirugia_id == cir.id)).first():
        raise ErrorNegocio("Ya hay drenes registrados en esta cirugía.", status=409)
    if simular:
        return {}
    cir.drenes_presentes = False
    session.add(cir)
    session.flush()
    _verificar_item_drenes(session, cir, ctx)
    nuevas = registrar_accion(session, cir.id, ctx, "declarar_sin_drenes", "dren", None, {"drenes": "ninguno"})
    session.commit()
    return {"alertas_nuevas": _alertas(nuevas)}


# ------------------------------------------------------------- datos clínicos

CAMPOS_PACIENTE_EDITABLES = {"nombre", "documento", "edad", "peso", "talla", "grupo_sanguineo", "alergias",
                             "presion_arterial", "frecuencia_cardiaca", "saturacion_o2", "temperatura",
                             "glucometria", "reserva_sangre", "info_clinica"}
CAMPOS_CIRUGIA_EDITABLES = {"procedimiento_registrado", "sitio_registrado"}


def normalizar_grupo(valor: str) -> Optional[str]:
    v = (valor or "").upper().replace(" ", "").replace("POSITIVO", "+").replace("NEGATIVO", "-").replace("0", "O")
    return v if v in GRUPOS_SANGUINEOS else None


def actualizar_paciente(session: Session, cirugia_id: int, cambios: dict, ctx: Ctx, simular: bool = False) -> dict:
    cir = _cirugia(session, cirugia_id)
    _exigir_operativo(session, cir, ctx, "actualizar_paciente", "paciente", cir.paciente_id)
    pac = session.get(Paciente, cir.paciente_id)
    registro = {}
    for campo, valor in cambios.items():
        if campo not in CAMPOS_PACIENTE_EDITABLES:
            continue
        if isinstance(valor, str):
            valor = valor.strip() or None
        if campo == "grupo_sanguineo" and valor is not None:
            grupo = normalizar_grupo(valor)
            if grupo is None:
                raise ErrorNegocio(f"Grupo sanguíneo no válido: {valor}. Use {', '.join(GRUPOS_SANGUINEOS)}.")
            valor = grupo
        anterior = getattr(pac, campo)
        if anterior != valor:
            registro[campo] = {"antes": anterior, "despues": valor}
    if not registro:
        raise ErrorNegocio("No hay cambios que registrar.")
    if simular:
        return {}
    for campo, v in registro.items():
        setattr(pac, campo, v["despues"])
    session.add(pac)
    nuevas = registrar_accion(session, cir.id, ctx, "actualizar_paciente", "paciente", pac.id, registro)
    session.commit()
    return {"paciente": pac.model_dump(), "alertas_nuevas": _alertas(nuevas)}


def actualizar_cirugia(session: Session, cirugia_id: int, cambios: dict, ctx: Ctx) -> dict:
    cir = _cirugia(session, cirugia_id)
    _exigir_operativo(session, cir, ctx, "actualizar_cirugia", "cirugia", cir.id)
    registro = {}
    for campo, valor in cambios.items():
        if campo in CAMPOS_CIRUGIA_EDITABLES:
            valor = (valor or "").strip() or None
            anterior = getattr(cir, campo)
            if anterior != valor:
                registro[campo] = {"antes": anterior, "despues": valor}
                setattr(cir, campo, valor)
    if not registro:
        raise ErrorNegocio("No hay cambios que registrar.")
    session.add(cir)
    nuevas = registrar_accion(session, cir.id, ctx, "actualizar_cirugia", "cirugia", cir.id, registro)
    session.commit()
    return {"alertas_nuevas": _alertas(nuevas)}


