        al.reconocida_en = datetime.now()
        session.add(al)
        _traza(session, al.cirugia_id, ctx, "reconocer_alerta", "alerta", al.id,
               {"regla": al.regla, "mensaje": al.mensaje})
        session.commit()
    return {"alerta": serializar_alerta(al)}


# -------------------------------------------------------------- crear cirugía

def instanciar_cirugia(session: Session, cir: Cirugia, procedimiento_id: Optional[int]) -> None:
    """Copia la plantilla del checklist y los insumos del procedimiento (todos en 0)."""
    for fase, bloque, codigo, desc, tipo, oblig, rol, aliases in CHECKLIST_PLANTILLA:
        session.add(ChecklistItem(cirugia_id=cir.id, fase=fase, bloque=bloque, codigo=codigo, descripcion=desc,
                                  tipo=tipo, obligatorio=oblig, rol_responsable=rol, aliases=aliases))
    if procedimiento_id:
        asociados = session.exec(select(ProcedimientoInsumo).where(
            ProcedimientoInsumo.procedimiento_id == procedimiento_id).order_by(ProcedimientoInsumo.id)).all()
        for a in asociados:
            cat = session.get(InsumoCatalogo, a.insumo_id)
            if cat and cat.activo:
                session.add(Insumo(cirugia_id=cir.id, catalogo_id=cat.id, nombre=cat.nombre, aliases=cat.aliases,
                                   unidad=cat.unidad))
    session.flush()


def crear_cirugia(session: Session, datos: dict, ctx: Ctx) -> dict:
    _exigir_operativo(session, None, ctx, "crear_cirugia", "cirugia")
    proc = session.get(TipoProcedimiento, datos.get("tipo_procedimiento_id") or 0)
    if proc is None or not proc.activo:
        raise ErrorNegocio("Seleccione un tipo de procedimiento válido.")
    pdatos = {k: v for k, v in (datos.get("paciente") or {}).items() if k in CAMPOS_PACIENTE_EDITABLES}
    if not (pdatos.get("nombre") or "").strip():
        raise ErrorNegocio("El nombre del paciente es obligatorio.")
    if pdatos.get("grupo_sanguineo"):
        grupo = normalizar_grupo(pdatos["grupo_sanguineo"])
        if grupo is None:
            raise ErrorNegocio("Grupo sanguíneo no válido.")
        pdatos["grupo_sanguineo"] = grupo
    pac = Paciente(**{k: (v.strip() or None) if isinstance(v, str) else v for k, v in pdatos.items()})
    session.add(pac)
    session.flush()
    fecha = datos.get("fecha_programada")
    cir = Cirugia(paciente_id=pac.id, tipo_procedimiento_id=proc.id, procedimiento_programado=proc.nombre,
                  sitio_programado=(datos.get("sitio") or proc.sitio_sugerido or "Sin especificar").strip(),
                  quirofano=(datos.get("quirofano") or "Quirófano 3").strip(),
                  fecha_programada=datetime.fromisoformat(fecha) if fecha else datetime.now())
    cir.procedimiento_registrado, cir.sitio_registrado = cir.procedimiento_programado, cir.sitio_programado
    session.add(cir)
    session.flush()
    ids = datos.get("equipo") or []
    usuarios = [session.get(Usuario, i) for i in ids] if ids else session.exec(
        select(Usuario).where(Usuario.activo == True)).all()  # noqa: E712
    for u in usuarios:
        if u and u.rol != "gestor":
            session.add(EquipoQuirurgico(cirugia_id=cir.id, usuario_id=u.id, rol=u.rol))
    instanciar_cirugia(session, cir, proc.id)
    nuevas = registrar_accion(session, cir.id, ctx, "crear_cirugia", "cirugia", cir.id,
                              {"procedimiento": proc.nombre, "sitio": cir.sitio_programado, "paciente": pac.nombre})
    session.commit()
    return {"cirugia_id": cir.id, "alertas_nuevas": _alertas(nuevas)}


# ------------------------------------------------------------------- consultas

def _usuarios(session: Session) -> dict[int, Usuario]:
    return {u.id: u for u in session.exec(select(Usuario)).all()}


def _roles(session: Session) -> dict[str, str]:
    return {t.codigo: t.nombre for t in session.exec(select(TipoPersona)).all()}


def _nombre(usuarios, uid):
    u = usuarios.get(uid)
    return u.nombre if u else None


def serializar_alerta(a: Alerta, usuarios: Optional[dict] = None) -> dict:
    d = a.model_dump()
    d["detalle"] = json.loads(a.detalle or "{}")
    if usuarios is not None:
        d["reconocida_por_nombre"] = _nombre(usuarios, a.reconocida_por)
    return d


def serializar_insumo(session: Session, ins: Insumo, catalogo=None, pct=None, usuarios=None) -> dict:
    if catalogo is None:
        catalogo = {c.id: c for c in session.exec(select(InsumoCatalogo)).all()}
    if pct is None:
        pct = umbral_pct(session)
    return {
        "id": ins.id,
        "catalogo_id": ins.catalogo_id,
        "nombre": ins.nombre,
        "unidad": ins.unidad,
        "cantidad_inicial": ins.cantidad_inicial,
        "cantidad_utilizada": ins.cantidad_utilizada,
        "cantidad_disponible": ins.cantidad_disponible,
        "umbral_preventivo": umbral_insumo(ins, catalogo, pct),
        "inicial_registrada": ins.inicial_registrada_en is not None,
        "inicial_registrada_en": ins.inicial_registrada_en,
        "inicial_registrada_por_nombre": _nombre(usuarios or _usuarios(session), ins.inicial_registrada_por),
    }


def serializar_traza(t: Trazabilidad, usuarios, roles) -> dict:
    d = t.model_dump()
    d["detalle"] = json.loads(t.detalle or "{}")
    d["usuario_nombre"] = _nombre(usuarios, t.usuario_id) or "Sistema"
    d["rol_nombre"] = roles.get(t.rol, t.rol) if t.rol else None
    return d


def listar_trazabilidad(session: Session, cirugia_id: Optional[int], usuario_id: Optional[int] = None,
                        accion: Optional[str] = None, canal: Optional[str] = None,
                        resultado: Optional[str] = None, limite: int = 500) -> list[dict]:
    q = select(Trazabilidad).where(Trazabilidad.cirugia_id == cirugia_id) if cirugia_id is not None else \
        select(Trazabilidad).where(Trazabilidad.cirugia_id == None)  # noqa: E711
    if usuario_id:
        q = q.where(Trazabilidad.usuario_id == usuario_id)
    if accion:
        q = q.where(Trazabilidad.accion == accion)
    if canal:
        q = q.where(Trazabilidad.canal == canal)
    if resultado:
        q = q.where(Trazabilidad.resultado == resultado)
    filas = session.exec(q.order_by(Trazabilidad.id.desc()).limit(limite)).all()
    usuarios, roles = _usuarios(session), _roles(session)
    return [serializar_traza(t, usuarios, roles) for t in filas]


def estado_cirugia(session: Session, cirugia_id: int) -> dict:
    cir = _cirugia(session, cirugia_id)
    usuarios, roles = _usuarios(session), _roles(session)
    pac = session.get(Paciente, cir.paciente_id)
    faltantes = [c for c in CAMPOS_OBLIGATORIOS_PACIENTE if getattr(pac, c) in (None, "")]
    equipo = session.exec(select(EquipoQuirurgico).where(EquipoQuirurgico.cirugia_id == cir.id)).all()
    items = session.exec(select(ChecklistItem).where(ChecklistItem.cirugia_id == cir.id)
                         .order_by(ChecklistItem.fase, ChecklistItem.id)).all()
    insumos = session.exec(select(Insumo).where(Insumo.cirugia_id == cir.id).order_by(Insumo.id)).all()
    novedades = session.exec(select(Novedad).where(Novedad.cirugia_id == cir.id)
                             .order_by(Novedad.numero.desc())).all()
    alertas = session.exec(select(Alerta).where(Alerta.cirugia_id == cir.id, Alerta.estado == "activa")
                           .order_by(Alerta.id.desc())).all()
    anestesias = session.exec(select(AnestesiaRegistro).where(AnestesiaRegistro.cirugia_id == cir.id)
                              .order_by(AnestesiaRegistro.id)).all()
    drenes = session.exec(select(Dren).where(Dren.cirugia_id == cir.id).order_by(Dren.numero)).all()
    catalogo = {c.id: c for c in session.exec(select(InsumoCatalogo)).all()}
    pct = umbral_pct(session)

    def item_dict(i):
        return {**i.model_dump(), "aliases": None, "verificado_por_nombre": _nombre(usuarios, i.verificado_por),
                "rol_responsable_nombre": roles.get(i.rol_responsable, i.rol_responsable)}

    fases = []
    for n, nombre in FASES.items():
        del_fase = [i for i in items if i.fase == n]
        oblig = [i for i in del_fase if i.obligatorio]
        fase = {
            "numero": n,
            "nombre": nombre,
            "estado": "cerrada" if cir.fase_actual > n else ("en_curso" if cir.fase_actual == n else "pendiente"),
            "total": len(oblig),
            "verificados": sum(1 for i in oblig if i.estado == "verificado"),
            "items": [item_dict(i) for i in del_fase],
            "bloques": [],
        }
        if n == 1:
            for codigo, bnombre, hito, requisito in BLOQUES_FASE1:
                b_items = [i for i in del_fase if i.bloque == codigo]
                habilitado = cir.fase_actual >= 1 and (requisito is None or _hora_hito(cir, requisito) is not None)
                fase["bloques"].append({
                    "codigo": codigo, "nombre": bnombre, "hito": hito,
                    "completado": _hora_hito(cir, hito) is not None, "habilitado": habilitado,
                    "requisito": HITOS[requisito][1] if requisito else None,
                    "items": [i.id for i in b_items],
                })
        if n == 3:
            fase["habilitado"] = cir.t_inicio_cirugia is not None
        fases.append(fase)

    hitos = [{"codigo": h, "nombre": HITOS[h][1], "hora": _hora_hito(cir, h), "automatico": HITOS[h][2]}
             for h in ORDEN_HITOS]
    duraciones = {}

    def minutos(a, b):
        return round((b - a).total_seconds() / 60) if a and b else None

    for clave, a, b in (("preparacion_min", cir.t_preparacion, cir.t_ingreso),
                        ("anestesia_a_incision_min", cir.t_inicio_anestesia, cir.t_inicio_cirugia),
                        ("cirugia_min", cir.t_inicio_cirugia, cir.t_fin_cirugia),
                        ("en_quirofano_min", cir.t_ingreso, cir.t_salida_recuperacion)):
        if (m := minutos(a, b)) is not None:
            duraciones[clave] = m

    return {
        "cirugia": cir.model_dump(),
        "fase_nombre": FASES.get(cir.fase_actual, "Fases completas"),
        "paciente": {**pac.model_dump(), "faltantes": faltantes},
        "equipo": [{"usuario_id": e.usuario_id, "nombre": _nombre(usuarios, e.usuario_id), "rol": e.rol,
                    "rol_nombre": roles.get(e.rol, e.rol)} for e in equipo],
        "fases": fases,
        "hitos": hitos,
        "duraciones": duraciones,
        "insumos": [serializar_insumo(session, i, catalogo, pct, usuarios) for i in insumos],
        "anestesias": [{**a.model_dump(), "registrado_por_nombre": _nombre(usuarios, a.registrado_por)}
                       for a in anestesias],
        "drenes": [{**d.model_dump(), "registrado_por_nombre": _nombre(usuarios, d.registrado_por)} for d in drenes],
        "novedades": [{**n.model_dump(),
                       "registrada_por_nombre": _nombre(usuarios, n.registrada_por),
                       "resuelta_por_nombre": _nombre(usuarios, n.resuelta_por)} for n in novedades],
        "alertas": [serializar_alerta(a, usuarios) for a in alertas],
        "trazabilidad": listar_trazabilidad(session, cir.id, limite=40),
    }

"""Configuración administrable desde el panel de gestión.

Los cambios quedan en la trazabilidad con cirugia_id = None (trazabilidad de configuración).
"""

import re
from typing import Optional

from sqlmodel import Session, select

from app.agent.normalizer import sin_tildes
from app.models import (
    Configuracion,
    InsumoCatalogo,
    ProcedimientoInsumo,
    ReglaAlerta,
    TipoPersona,
    TipoProcedimiento,
    Usuario,
)
from app.rules import reevaluar_en_curso, umbral_pct
from app.services import Ctx, ErrorNegocio, exigir_configurador, registrar_accion


def _slug(texto: str) -> str:
    return re.sub(r"[^a-z0-9]+", "_", sin_tildes(texto.lower())).strip("_")


def _guardar(session: Session, ctx: Ctx, accion: str, entidad: str, entidad_id, detalle: dict):
    registrar_accion(session, None, ctx, accion, entidad, entidad_id, detalle)
    session.commit()


# ---------------------------------------------------------------------- reglas

def listar_reglas(session: Session) -> dict:
    reglas = session.exec(select(ReglaAlerta).order_by(ReglaAlerta.id)).all()
    return {"reglas": [r.model_dump() for r in reglas], "umbral_preventivo_pct": umbral_pct(session)}


def actualizar_regla(session: Session, codigo: str, cambios: dict, ctx: Ctx) -> dict:
    exigir_configurador(session, ctx, "actualizar_regla", "regla_alerta")
    regla = session.exec(select(ReglaAlerta).where(ReglaAlerta.codigo == codigo)).first()
    if regla is None:
        raise ErrorNegocio("La regla no existe.", status=404)
    registro = {}
    for campo in ("activa", "modal"):
        if campo in cambios and cambios[campo] is not None and getattr(regla, campo) != bool(cambios[campo]):
            registro[campo] = {"antes": getattr(regla, campo), "despues": bool(cambios[campo])}
            setattr(regla, campo, bool(cambios[campo]))
    if not registro:
        raise ErrorNegocio("No hay cambios que registrar.")
    session.add(regla)
    session.flush()
    reevaluar_en_curso(session)
    _guardar(session, ctx, "actualizar_regla", "regla_alerta", regla.id,
             {"regla": regla.codigo, "nombre": regla.nombre, **registro})
    return regla.model_dump()


def actualizar_umbral_pct(session: Session, valor: int, ctx: Ctx) -> dict:
    exigir_configurador(session, ctx, "actualizar_umbral", "configuracion")
    if valor is None or not 1 <= valor <= 90:
        raise ErrorNegocio("El umbral preventivo debe estar entre 1 % y 90 %.")
    fila = session.get(Configuracion, "umbral_preventivo_pct") or Configuracion(clave="umbral_preventivo_pct", valor="25")
    antes = int(fila.valor)
    fila.valor = str(valor)
    session.add(fila)
    session.flush()
    reevaluar_en_curso(session)
    _guardar(session, ctx, "actualizar_umbral", "configuracion", None,
             {"umbral_preventivo_pct": {"antes": antes, "despues": valor}})
    return {"umbral_preventivo_pct": valor}


