def listar_tipos(session: Session) -> list[dict]:
    return [t.model_dump() for t in session.exec(select(TipoPersona).order_by(TipoPersona.id)).all()]


def crear_tipo(session: Session, nombre: str, acceso_operativo: bool, puede_configurar: bool, ctx: Ctx) -> dict:
    exigir_configurador(session, ctx, "crear_tipo_persona", "tipo_persona")
    nombre = (nombre or "").strip()
    if len(nombre) < 3:
        raise ErrorNegocio("El nombre del tipo de persona debe tener al menos 3 caracteres.")
    codigo = _slug(nombre)
    if session.exec(select(TipoPersona).where(TipoPersona.codigo == codigo)).first():
        raise ErrorNegocio(f"Ya existe un tipo de persona «{nombre}».", status=409)
    t = TipoPersona(codigo=codigo, nombre=nombre, acceso_operativo=acceso_operativo, puede_configurar=puede_configurar)
    session.add(t)
    session.flush()
    _guardar(session, ctx, "crear_tipo_persona", "tipo_persona", t.id,
             {"nombre": nombre, "acceso_operativo": acceso_operativo, "puede_configurar": puede_configurar})
    return t.model_dump()


def actualizar_tipo(session: Session, tipo_id: int, cambios: dict, ctx: Ctx) -> dict:
    exigir_configurador(session, ctx, "actualizar_tipo_persona", "tipo_persona")
    t = session.get(TipoPersona, tipo_id)
    if t is None:
        raise ErrorNegocio("El tipo de persona no existe.", status=404)
    registro = {}
    for campo in ("nombre", "activo", "acceso_operativo", "puede_configurar"):
        if cambios.get(campo) is None:
            continue
        valor = cambios[campo].strip() if campo == "nombre" else bool(cambios[campo])
        if getattr(t, campo) != valor:
            registro[campo] = {"antes": getattr(t, campo), "despues": valor}
            setattr(t, campo, valor)
    if not registro:
        raise ErrorNegocio("No hay cambios que registrar.")
    if t.codigo == ctx.usuario.rol and (not t.activo or not (t.puede_configurar or t.acceso_operativo)):
        raise ErrorNegocio("No puede retirarse a sí mismo el acceso a la configuración.")
    session.add(t)
    _guardar(session, ctx, "actualizar_tipo_persona", "tipo_persona", t.id, {"tipo": t.nombre, **registro})
    return t.model_dump()


def listar_usuarios(session: Session, todos: bool = False) -> list[dict]:
    tipos = {t.codigo: t for t in session.exec(select(TipoPersona)).all()}
    out = []
    for u in session.exec(select(Usuario).order_by(Usuario.id)).all():
        t = tipos.get(u.rol)
        if not todos and not (u.activo and t and t.activo):
            continue
        out.append({**u.model_dump(), "rol_nombre": t.nombre if t else u.rol,
                    "acceso_operativo": bool(t and t.activo and t.acceso_operativo and u.activo),
                    "puede_configurar": bool(t and t.activo and (t.puede_configurar or t.acceso_operativo) and u.activo),
                    "tipo_activo": bool(t and t.activo)})
    return out


def crear_usuario(session: Session, nombre: str, rol: str, ctx: Ctx) -> dict:
    exigir_configurador(session, ctx, "crear_usuario", "usuario")
    nombre = (nombre or "").strip()
    if len(nombre) < 3:
        raise ErrorNegocio("El nombre debe tener al menos 3 caracteres.")
    t = session.exec(select(TipoPersona).where(TipoPersona.codigo == rol)).first()
    if t is None or not t.activo:
        raise ErrorNegocio("Seleccione un tipo de persona activo.")
    u = Usuario(nombre=nombre, rol=rol)
    session.add(u)
    session.flush()
    _guardar(session, ctx, "crear_usuario", "usuario", u.id, {"nombre": nombre, "tipo": t.nombre})
    return u.model_dump()


def actualizar_usuario(session: Session, usuario_id: int, activo: bool, ctx: Ctx) -> dict:
    exigir_configurador(session, ctx, "actualizar_usuario", "usuario")
    u = session.get(Usuario, usuario_id)
    if u is None:
        raise ErrorNegocio("El usuario no existe.", status=404)
    if u.id == ctx.usuario.id and not activo:
        raise ErrorNegocio("No puede desactivarse a sí mismo.")
    if u.activo == activo:
        raise ErrorNegocio("No hay cambios que registrar.")
    u.activo = activo
    session.add(u)
    _guardar(session, ctx, "actualizar_usuario", "usuario", u.id,
             {"nombre": u.nombre, "activo": {"antes": not activo, "despues": activo}})
    return u.model_dump()


