def crear_procedimiento(session: Session, nombre: str, sitio: Optional[str], ctx: Ctx) -> dict:
    exigir_configurador(session, ctx, "crear_procedimiento", "procedimiento")
    nombre = (nombre or "").strip()
    if len(nombre) < 3:
