def actualizar_insumo_catalogo(session: Session, insumo_id: int, cambios: dict, ctx: Ctx) -> dict:
    exigir_configurador(session, ctx, "actualizar_insumo_catalogo", "insumo_catalogo")
    c = session.get(InsumoCatalogo, insumo_id)
    if c is None:
        raise ErrorNegocio("El insumo no existe.", status=404)
    registro = {}
    if "umbral_preventivo" in cambios:
        v = cambios["umbral_preventivo"]
        v = None if v in (None, "") else int(v)
        if v is not None and v < 0:
            raise ErrorNegocio("El umbral no puede ser negativo.")
        if c.umbral_preventivo != v:
            registro["umbral_preventivo"] = {"antes": c.umbral_preventivo, "despues": v}
            c.umbral_preventivo = v
    if cambios.get("activo") is not None and c.activo != bool(cambios["activo"]):
        registro["activo"] = {"antes": c.activo, "despues": bool(cambios["activo"])}
        c.activo = bool(cambios["activo"])
    if not registro:
        raise ErrorNegocio("No hay cambios que registrar.")
    session.add(c)
    session.flush()
    reevaluar_en_curso(session)
    _guardar(session, ctx, "actualizar_insumo_catalogo", "insumo_catalogo", c.id, {"insumo": c.nombre, **registro})
    return c.model_dump()

"""Intérprete determinista: frase -> intención + entidades.

Las entidades (ítems, insumos) se buscan SOLO en los catálogos de la cirugía activa.
Si falta un dato (cantidad, tipo) o es ambiguo, la intención lo marca y el agente pregunta: nunca se inventa.
"""

import re
from dataclasses import dataclass, field
from typing import Optional

from app.agent.normalizer import normalizar, numeros
from app.catalogos import TIPOS_ANESTESIA, TIPOS_DREN

try:
    from rapidfuzz import fuzz

    def _parcial(a: str, b: str) -> float:
        return fuzz.partial_ratio(a, b)
except ImportError:  # pragma: no cover
    from difflib import SequenceMatcher

    def _parcial(a: str, b: str) -> float:
        if len(a) > len(b):
            a, b = b, a
        mejor = 0.0
        for i in range(0, max(1, len(b) - len(a) + 1)):
            mejor = max(mejor, SequenceMatcher(None, a, b[i:i + len(a)]).ratio() * 100)
        return mejor

UMBRAL_FUERTE = 88
UMBRAL_DUDA = 72

CONFIRMAR = {"si", "confirmo", "confirma", "confirmar", "confirmado", "correcto", "afirmativo",
             "ok", "okay", "dale", "de", "acuerdo", "claro", "adelante", "hazlo", "registra", "eso"}
CANCELAR = {"no", "cancela", "cancelar", "cancelo", "cancelado", "negativo", "olvidalo", "anula",
            "detente", "espera"}

PALABRAS_PREGUNTA = ("que ", "cual ", "cuales ", "cuanto", "cuanta", "como ", "hay ", "dame ",
                     "dime ", "muestrame ", "quien", "donde ", "lee ", "leer ", "consulta",
                     "resumen", "estado ", "tiene ")

RE_CERRAR_FASE = re.compile(r"\b(cerrar|cierra|cierre|cerramos|cerremos|finalizar|finaliza)\b.*\bfase\b")
RE_RESOLVER = re.compile(r"\b(resuelt[ao]s?|resolver|resuelve|resolvemos|solucionad[ao]s?|cerrar novedad|cerrada)\b")

_INICIO = r"\b(inicio|inicia|iniciamos|iniciar|iniciando|comienza|comenzamos|comenzar|empieza|empezamos|empezar|arranca)\b"
HITO_PATRONES = [
    ("preparacion", re.compile(_INICIO + r"( de| la| el)*( la)? preparacion\b")),
    ("ingreso", re.compile(r"\b(ingres\w*|entr[oa]|llego|llega)\b.*\b(quirofano|sala)\b|\bingreso del paciente\b|\bpaciente ingres\w*")),
    ("inicio_anestesia", re.compile(_INICIO + r"( de| la| el)*( la)? (anestesia|induccion)\b|\binduccion anestesica\b")),
    ("inicio_cirugia", re.compile(_INICIO + r"( de| la| el)*( la)? (cirugia|procedimiento)\b|\b(hacemos|se hace|realiza\w*) (la )?incision\b")),
    ("fin_cirugia", re.compile(r"\b(fin|final|termina|terminamos|termino|terminada|finaliza|finalizamos|finalizo)\b( de| la| el)*( la)? (cirugia|procedimiento)\b")),
    ("salida_recuperacion", re.compile(r"\b(salida|sale|salio|pasa|paso|traslado|trasladamos)\b( del paciente)? (a|al|hacia) (la )?(sala de )?recuperacion\b")),
]

RE_CONSUMO = re.compile(
    r"\b(utiliz\w*|usamos|usaron|use|uso|usado|usada|usados|usadas|consum\w*|gast\w*|abri\w*|abiert\w*|"
    r"se fue|se fueron|descarta\w*)\b")

RE_CARGA_INICIAL = re.compile(
    r"\b(registr\w*|carg\w*|ingres\w*|tenemos|hay|recib\w*|inicial\w*|disponemos|contamos|alist\w*|"
    r"dispon\w*|agreg\w*|anad\w*|pon\w*)\b")

RE_VERIFICACION = re.compile(
    r"\b(verific\w*|confirmad[oa]s?|confirmo|confirmaron|confirmamos|correct[oa]s?|chequ\w*|comprob\w*|"
    r"revis\w*|funcionando|funciona|list[oa]s?|administrad[oa]s?|aplicad[oa]s?|firmad[oa]s?|marcad[oa]s?|"
    r"etiquetad[oa]s?|comunicad[oa]s?|registrad[oa]s?|presentad[oa]s?|disponibles?|complet[oa]s?|conforme|"
    r"ok|identificad[oa]s?|realizad[oa]s?|validad[oa]s?|validaron)\b")

RE_GRUPO = re.compile(r"\b(ab|a|b|o|0)\s*(\+|-|positivo|negativo|pos|neg)(?=\s|$)")
RE_PESO = re.compile(r"\b(peso|pesa)\b\D*(\d+)")


@dataclass
class Coincidencia:
    id: int
    nombre: str
    score: float
    alias: str


@dataclass
class Intencion:
    nombre: str
    entidades: dict = field(default_factory=dict)
    duda: Optional[Coincidencia] = None


def es_confirmacion(t: str) -> bool:
    palabras = t.split()
    return 0 < len(palabras) <= 4 and palabras[0] != "no" and all(p in CONFIRMAR for p in palabras)


def es_cancelacion(t: str) -> bool:
    palabras = t.split()
    return 0 < len(palabras) <= 5 and (palabras[0] in CANCELAR or any(
        p in ("cancela", "cancelar", "cancelo", "negativo", "anula") for p in palabras))


def buscar(texto: str, catalogo: list[tuple[int, str, list[str]]], solo_exacto: bool = False) -> Optional[Coincidencia]:
    """catalogo: [(id, nombre_visible, [alias normalizados])]. Devuelve la mejor coincidencia."""
    mejor: Optional[Coincidencia] = None
    for ent_id, nombre, aliases in catalogo:
        for alias in aliases:
            if not alias:
                continue
            if re.search(rf"\b{re.escape(alias)}\b", texto):
                score = 100 + len(alias)
            elif len(alias) >= 5 and not solo_exacto:
                score = _parcial(alias, texto)
            else:
                continue
            if mejor is None or score > mejor.score:
                mejor = Coincidencia(ent_id, nombre, score, alias)
    return mejor


def _catalogo_simple(tabla) -> list:
    return [(i, nombre, [normalizar(nombre)] + [normalizar(a) for a in aliases.split("|")])
            for i, (nombre, aliases) in enumerate(tabla)]


CAT_ANESTESIA = _catalogo_simple(TIPOS_ANESTESIA)
CAT_DREN = _catalogo_simple(TIPOS_DREN)


def _resto_despues(original: str, patron: str) -> str:
    partes = re.split(patron, original, maxsplit=1, flags=re.IGNORECASE)
    if len(partes) < 2:
        return ""
    return partes[-1].strip(" :,.;-")


def _capitalizar(s: str) -> str:
    return s[:1].upper() + s[1:] if s else s


def _fase_mencionada(t: str) -> Optional[int]:
    ns = numeros(t)
    if ns and ns[0] in (1, 2, 3):
        return ns[0]
    if "incision" in t or "pausa" in t:
        return 2
    if "salir" in t or "salida" in t:
        return 3
    if "anestesia" in t or "entrada" in t or "preparacion" in t:
        return 1
    return None


def _cantidades(t: str, alias: Optional[str] = None) -> list[int]:
    """Números distintos de la frase, excluyendo los que forman parte del nombre del insumo (p. ej. 2-0)."""
    if alias:
        t = t.replace(alias, " ")
    t = re.sub(r"\b\d+-\d+\b", " ", t)
    vistos = []
    for n in numeros(t):
        if n not in vistos:
            vistos.append(n)
    return vistos


def _entidades_cantidad(t: str, match: Coincidencia) -> dict:
    cant = _cantidades(t, match.alias)
    ent = {"insumo_id": match.id, "insumo": match.nombre, "cantidad": cant[0] if len(cant) == 1 else None}
    if len(cant) > 1:
        ent["opciones"] = cant
    return ent


def _resultado_verificacion(original: str, t: str, alias: str) -> str:
    if "," in original:
        resto = original.split(",", 1)[1].strip(" .")
        if resto:
            return _capitalizar(resto)
    resto = t.replace(alias, " ", 1)
    resto = RE_VERIFICACION.sub(" ", resto, count=1)
    resto = re.sub(r"\b(el|la|los|las|de|del|esta|ya|y|fue|se|que|registrar|registra|registro|"
                   r"todos|todas|bien|fueron|han|sido)\b", " ", resto)
    resto = re.sub(r"\s+", " ", resto).strip()
    return _capitalizar(resto) if len(resto) > 3 else "Conforme"


def interpretar(original: str, items: list, insumos: list) -> Intencion:
    t = normalizar(original, numeros=True)
    if not t:
        return Intencion("no_entendido")
    pregunta = "?" in original or "¿" in original or t.startswith(PALABRAS_PREGUNTA) or t in (
        "resumen", "estado")

    # Novedades
    if re.search(r"\bnovedad(es)?\b", t) and not pregunta:
        if RE_RESOLVER.search(t):
            accion = _resto_despues(original, r"resuelt[ao]s?|solucionad[ao]s?|resolver|resuelve|cerrada")
            accion = re.sub(r"^(con|por)\s+", "", accion, flags=re.IGNORECASE)
            ns = numeros(t)
            return Intencion("resolver_novedad", {"numero": ns[0] if ns else None,
                                                  "accion_correctiva": _capitalizar(accion)})
        desc = _resto_despues(original, r"novedad(?:es)?")
        desc = re.sub(r"^(de|que|:)\s*", "", desc, flags=re.IGNORECASE)
        return Intencion("registrar_novedad", {"descripcion": _capitalizar(desc)})

    if not pregunta and RE_CERRAR_FASE.search(t):
        return Intencion("cerrar_fase", {"fase": _fase_mencionada(t)})

    if not pregunta:
        for hito, patron in HITO_PATRONES:
            if patron.search(t):
                just = _resto_despues(original, r"justificaci[oó]n|porque|debido a")
                return Intencion("registrar_evento", {"hito": hito, "justificacion": just or None})

    # Datos del paciente (grupo sanguíneo, peso)
    if not pregunta and re.search(r"\b(grupo sanguineo|tipo de sangre|grupo de sangre|rh)\b", t):
        m = RE_GRUPO.search(t.replace("tipo de sangre", " ").replace("grupo sanguineo", " "))
        if m:
            letra = "O" if m.group(1) in ("o", "0") else m.group(1).upper()
            signo = "+" if m.group(2) in ("+", "positivo", "pos") else "-"
            return Intencion("actualizar_paciente", {"campo": "grupo_sanguineo", "valor": letra + signo})
        if re.search(r"\b(registr\w*|cambi\w*|actualiz\w*|correg\w*|es|ponga|pon)\b", t):
            return Intencion("actualizar_paciente", {"campo": "grupo_sanguineo", "valor": None})
    if not pregunta and (m := RE_PESO.search(t)) and re.search(r"\b(registr\w*|pesa|cambi\w*|actualiz\w*|kilo\w*|kg)\b", t):
        return Intencion("actualizar_paciente", {"campo": "peso", "valor": int(m.group(2))})

    # Anestesia (tipos; el inicio de la anestesia es un hito y se capturó arriba)
    if not pregunta and re.search(r"\b(anestesia|sedacion|bloqueo)\b", t):
        tipo = buscar(t, CAT_ANESTESIA, solo_exacto=True)
        hay_item = RE_VERIFICACION.search(t) and (m := buscar(t, items)) and m.score >= UMBRAL_FUERTE
        if tipo and not hay_item:
            return Intencion("registrar_anestesia", {"tipo": tipo.nombre})
        if not hay_item and re.search(r"\b(agreg\w*|anad\w*|registr\w*|adiciona\w*)\b", t):
            return Intencion("registrar_anestesia", {"tipo": None})

    # Drenes
    if not pregunta and re.search(r"\b(dren|drenes|drenaje|drenajes)\b", t):
        if re.search(r"\b(sin|ningun|ninguno|no hay|no se dej\w*|no lleva|no tiene|no requiere)\b", t):
            return Intencion("registrar_sin_drenes")
        tipo = buscar(t, CAT_DREN, solo_exacto=True)
        t_sin_tipo = t.replace(tipo.alias, " ") if tipo else t
        numero = re.search(r"\b(numero|nro|no)\s+(\d+)\b", t_sin_tipo)
        resto = re.sub(r"\b(numero|nro|no)\s+\d+\b", " ", t_sin_tipo)
        cant = _cantidades(resto)
        obs = _resto_despues(original, r"observaci[oó]n(?:es)?|nota")
        return Intencion("registrar_dren", {
            "tipo": tipo.nombre if tipo else None, "numero": int(numero.group(2)) if numero else None,
            "cantidad": cant[0] if len(cant) == 1 else (1 if not cant else None),
            "opciones": cant if len(cant) > 1 else None, "observaciones": obs or None})

    match_insumo = buscar(t, insumos)
    if not pregunta and RE_CONSUMO.search(t):
        if match_insumo and match_insumo.score >= UMBRAL_FUERTE:
            return Intencion("registrar_consumo", _entidades_cantidad(t, match_insumo))
        if match_insumo and match_insumo.score >= UMBRAL_DUDA:
            return Intencion("registrar_consumo", duda=match_insumo)

    if not pregunta and RE_CARGA_INICIAL.search(t) and match_insumo and match_insumo.score >= UMBRAL_FUERTE \
            and not RE_VERIFICACION.search(t):
        return Intencion("registrar_cantidad_inicial", _entidades_cantidad(t, match_insumo))

    if not pregunta and RE_VERIFICACION.search(t):
        match_item = buscar(t, items)
        if match_item and match_item.score >= UMBRAL_FUERTE:
            return Intencion("registrar_verificacion", {
                "item_id": match_item.id, "item": match_item.nombre,
                "resultado": _resultado_verificacion(original, t, match_item.alias)})
        if match_item and match_item.score >= UMBRAL_DUDA:
            return Intencion("registrar_verificacion", duda=match_item)

    # Consultas
    if "alerta" in t or "novedades" in t:
        return Intencion("consultar_alertas")
    if re.search(r"\b(grupo sanguineo|tipo de sangre|grupo de sangre|rh)\b", t):
        return Intencion("consultar_procedimiento", {"tema": "grupo"})
    if any(k in t for k in ("vitales", "presion", "saturacion", "frecuencia", "temperatura", "signos")):
        return Intencion("consultar_procedimiento", {"tema": "vitales"})
    if re.search(r"\b(anestesia|anestesias|sedacion)\b", t) and "anestesiologo" not in t:
        return Intencion("consultar_anestesia")
    if re.search(r"\b(dren|drenes|drenaje)\b", t):
        return Intencion("consultar_drenes")
    if any(k in t for k in ("insumo", "stock", "inventario", "agotad", "quedan", "queda ", "disponible",
                            "utilizad")) or (pregunta and match_insumo and match_insumo.score >= UMBRAL_FUERTE):
        ent = {}
        if match_insumo and match_insumo.score >= UMBRAL_FUERTE:
            ent = {"insumo_id": match_insumo.id, "insumo": match_insumo.nombre}
        ent["agotados"] = "agotad" in t
        return Intencion("consultar_insumos", ent)
    if any(k in t for k in ("falta", "pendiente", "verificaciones", "checklist", "chequeo", "lista de verificacion")):
        return Intencion("consultar_checklist", {"fase": _fase_mencionada(t) if "fase" in t and numeros(t) else None})
    temas = [("alergias", ("alergi",)), ("sitio", ("sitio", "lateralidad")),
             ("equipo", ("equipo", "quien opera", "quienes", "cirujano", "anestesiologo")),
             ("paciente", ("paciente", "peso", "edad", "sangre", "documento", "glucometria", "talla")),
             ("procedimiento", ("procedimiento", "que cirugia", "cual cirugia", "operacion"))]
    for tema, claves in temas:
        if any(k in t for k in claves):
            return Intencion("consultar_procedimiento", {"tema": tema})
    if any(k in t for k in ("como va", "resumen", "estado", "en que fase", "fase actual", "como vamos")):
        return Intencion("consultar_estado")
    return Intencion("no_entendido")

"""Agente conversacional: traduce una frase en una llamada a los servicios.

No decide nada clínico ni escribe directamente en la BD: todo pasa por `app.services`,
exactamente las mismas funciones que usa la interfaz.
"""

import time
import uuid
from dataclasses import dataclass, field
from typing import Optional

from sqlmodel import Session, func, select

from app import services as sv
from app.agent.interpreter import Intencion, es_cancelacion, es_confirmacion, interpretar
from app.agent.normalizer import normalizar
from app.models import FASES, HITOS, ChecklistItem, Cirugia, Dren, Insumo, Novedad, Usuario

EXPIRACION_S = 60


@dataclass
class Pendiente:
    accion: str
    params: dict
    usuario_id: int
    cirugia_id: int
    mensaje: str
    transcripcion: str
    canal: str
    cambios: list
    refs: dict = field(default_factory=dict)
    expira: float = field(default_factory=lambda: time.time() + EXPIRACION_S)


PENDIENTES: dict[str, Pendiente] = {}


def _limpiar_expirados():
    ahora = time.time()
    for pid in [k for k, p in PENDIENTES.items() if p.expira < ahora]:
        PENDIENTES.pop(pid, None)


def _respuesta(estado: str, texto: str, cambios=None, alertas=None, pending_id=None,
               intencion=None, datos=None, refs=None) -> dict:
    return {
        "estado": estado,
        "texto": texto,
        "pending_id": pending_id,
        "expira_en": EXPIRACION_S if pending_id else None,
        "cambios": cambios or [],
        "alertas_nuevas": alertas or [],
        "intencion": intencion,
        "datos": datos or {},
        "refs": refs or {},
    }


def _catalogos(session: Session, cirugia_id: int):
    items = session.exec(select(ChecklistItem).where(ChecklistItem.cirugia_id == cirugia_id)).all()
    insumos = session.exec(select(Insumo).where(Insumo.cirugia_id == cirugia_id)).all()
    cat_items = [(i.id, i.descripcion,
                  [normalizar(a) for a in i.aliases.split("|")] + [normalizar(i.descripcion)]) for i in items]
    cat_insumos = [(i.id, i.nombre,
                    [normalizar(a) for a in i.aliases.split("|")] + [normalizar(i.nombre)]) for i in insumos]
    return cat_items, cat_insumos


# ------------------------------------------------------------------ consultas

def _lista(nombres: list[str]) -> str:
    if len(nombres) <= 1:
        return "".join(nombres)
    return ", ".join(nombres[:-1]) + " y " + nombres[-1]


def _txt_insumo(i: dict) -> str:
    if not i["inicial_registrada"]:
        return f"{i['nombre']}: cantidad inicial sin registrar"
    if i["cantidad_disponible"] == 0:
        return f"{i['nombre']}: agotado (inicial {i['cantidad_inicial']}, utilizado {i['cantidad_utilizada']})"
    return (f"{i['nombre']}: inicial {i['cantidad_inicial']}, utilizado {i['cantidad_utilizada']}, "
            f"disponible {i['cantidad_disponible']}")


def _consultar(session: Session, intencion: Intencion, cir: Cirugia) -> tuple[str, dict, list]:
    est = sv.estado_cirugia(session, cir.id)
    nombre = intencion.nombre
    e = intencion.entidades
    pac = est["paciente"]

    if nombre == "consultar_checklist":
        fase = e.get("fase") or min(cir.fase_actual, 3)
        if cir.fase_actual > 3 and not e.get("fase"):
            return "Las tres fases del checklist están cerradas.", {}, ["checklist"]
        pend = sv.pendientes_fase(session, cir.id, fase)
        opc = [p for p in sv.pendientes_fase(session, cir.id, fase, solo_obligatorios=False) if not p.obligatorio]
        if not pend:
            txt = f"La fase {fase}, {FASES[fase].lower()}, no tiene verificaciones obligatorias pendientes."
            if fase == cir.fase_actual:
                txt += " Ya puede cerrarse."
        else:
            txt = (f"Faltan {len(pend)} verificaciones en la fase {fase}, {FASES[fase].lower()}: "
                   f"{_lista([p.descripcion.lower() for p in pend])}.")
        if opc:
            txt += f" Opcional: {_lista([o.descripcion.lower() for o in opc])}."
        return txt, {"fase": fase, "pendientes": [p.descripcion for p in pend]}, ["checklist"]

    if nombre == "consultar_alertas":
        alertas = est["alertas"]
        abiertas = [n for n in est["novedades"] if n["estado"] == "abierta"]
        if not alertas:
            txt = "No hay alertas activas."
        else:
            s = "s" if len(alertas) != 1 else ""
            txt = f"Hay {len(alertas)} alerta{s} activa{s}: " + " ".join(a["mensaje"] for a in alertas)
        if abiertas:
            txt += f" Novedades abiertas: {len(abiertas)}."
        return txt, {"alertas": [a["mensaje"] for a in alertas]}, ["alertas"]

    if nombre == "consultar_insumos":
        insumos = est["insumos"]
        if e.get("insumo_id"):
            ins = next(i for i in insumos if i["id"] == e["insumo_id"])
            return _txt_insumo(ins) + ".", {"insumo_id": ins["id"]}, ["insumos"]
        agotados = [i["nombre"] for i in insumos if i["inicial_registrada"] and i["cantidad_disponible"] == 0]
        if e.get("agotados"):
            txt = f"Insumos agotados: {_lista(agotados)}." if agotados else "No hay insumos agotados."
        else:
            txt = "Insumos. " + "; ".join(_txt_insumo(i) for i in insumos) + "."
        return txt, {"agotados": agotados}, ["insumos"]

    if nombre == "consultar_anestesia":
        activas = [a for a in est["anestesias"] if a["estado"] == "activo"]
        tipos = _lista([a["tipo"].lower() for a in activas]) if activas else "ningún tipo registrado"
        inicio = f"inicio a las {sv.hhmm(cir.t_inicio_anestesia)}" if cir.t_inicio_anestesia else \
            "inicio de anestesia sin registrar"
        return f"Anestesia: {tipos}; {inicio}.", {}, ["anestesia"]

    if nombre == "consultar_drenes":
        drenes = est["drenes"]
        if drenes:
            txt = "Drenes: " + "; ".join(
                f"número {d['numero']}, {d['tipo'] or 'tipo sin especificar'}, cantidad {d['cantidad']}" for d in drenes) + "."
        elif cir.drenes_presentes is False:
            txt = "Se registró que no hay drenes."
        else:
            txt = "No hay drenes registrados."
        return txt, {}, ["drenes"]

    if nombre == "consultar_procedimiento":
        tema = e.get("tema")
        if tema == "alergias":
            txt = f"Alergias del paciente: {pac['alergias']}." if pac["alergias"] else \
                "Las alergias del paciente no están registradas."
        elif tema == "grupo":
            txt = f"Grupo sanguíneo: {pac['grupo_sanguineo']}." if pac["grupo_sanguineo"] else \
                "El grupo sanguíneo no está registrado."
        elif tema == "vitales":
            partes = [f"presión {pac['presion_arterial']}" if pac["presion_arterial"] else None,
                      f"frecuencia cardiaca {pac['frecuencia_cardiaca']}" if pac["frecuencia_cardiaca"] else None,
                      f"saturación {pac['saturacion_o2']} %" if pac["saturacion_o2"] else None,
                      f"temperatura {pac['temperatura']} grados" if pac["temperatura"] else None]
            partes = [p for p in partes if p]
            txt = f"Signos vitales: {_lista(partes)}." if partes else "No hay signos vitales registrados."
        elif tema == "sitio":
            txt = f"Sitio quirúrgico programado: {cir.sitio_programado}."
        elif tema == "equipo":
            txt = "Equipo: " + "; ".join(f"{m['nombre']}, {m['rol_nombre'].lower()}" for m in est["equipo"]) + "."
        elif tema == "paciente":
            txt = (f"Paciente {pac['nombre']}, {pac['edad']} años, documento {pac['documento']}. "
                   f"Peso: {str(pac['peso']) + ' kg' if pac['peso'] else 'sin registrar'}. "
                   f"Grupo sanguíneo: {pac['grupo_sanguineo'] or 'sin registrar'}. "
                   f"Alergias: {pac['alergias'] or 'sin registrar'}.")
        else:
            txt = f"Procedimiento: {cir.procedimiento_programado}, sitio {cir.sitio_programado}."
        return txt, {}, ["paciente"]

    # consultar_estado
    fase_txt = (f"fase {cir.fase_actual}, {FASES[cir.fase_actual].lower()}" if 1 <= cir.fase_actual <= 3
                else "checklist completo")
    f = next((x for x in est["fases"] if x["numero"] == cir.fase_actual), None)
    progreso = f" {f['verificados']} de {f['total']} verificaciones." if f else ""
    ultimo = next((h for h in reversed(est["hitos"]) if h["hora"]), None)
    hito_txt = f" Último hito: {ultimo['nombre'].lower()} a las {sv.hhmm(ultimo['hora'])}." if ultimo else \
        " Aún no hay hitos registrados."
    n_al = len(est["alertas"])
    s = "s" if n_al != 1 else ""
    txt = f"{cir.procedimiento_programado}. Estamos en {fase_txt}.{progreso}{hito_txt} {n_al} alerta{s} activa{s}."
    return txt, {}, ["estado"]


# ------------------------------------------------------------------- acciones

def _ejecutar(session: Session, accion: str, params: dict, ctx: sv.Ctx, cirugia_id: int,
              simular: bool = False) -> dict:
    if accion == "registrar_verificacion":
        return sv.verificar_item(session, cirugia_id, params["item_id"], ctx, params.get("resultado"),
                                 simular=simular)
    if accion == "registrar_consumo":
        return sv.registrar_consumo(session, cirugia_id, params["insumo_id"], params["cantidad"], ctx,
                                    confirmado=params.get("confirmado", False))
    if accion == "registrar_cantidad_inicial":
        return sv.establecer_cantidad_inicial(session, cirugia_id, params["insumo_id"], params["cantidad"], ctx,
                                              simular=simular)
    if accion == "registrar_novedad":
        return sv.registrar_novedad(session, cirugia_id, params["descripcion"], ctx)
    if accion == "registrar_evento":
        return sv.registrar_evento(session, cirugia_id, params["hito"], ctx, params.get("justificacion"),
                                   simular=simular)
    if accion == "cerrar_fase":
        return sv.cerrar_fase(session, cirugia_id, params["fase"], ctx, simular=simular)
    if accion == "resolver_novedad":
        return sv.resolver_novedad(session, params["novedad_id"], params["accion_correctiva"], ctx,
                                   simular=simular)
    if accion == "registrar_anestesia":
        return sv.registrar_anestesia(session, cirugia_id, params["tipo"], ctx, simular=simular)
    if accion == "registrar_dren":
        return sv.registrar_dren(session, cirugia_id, ctx, params.get("tipo"), params.get("cantidad", 1),
                                 params.get("observaciones"), simular=simular)
    if accion == "registrar_sin_drenes":
        return sv.declarar_sin_drenes(session, cirugia_id, ctx, simular=simular)
    if accion == "actualizar_paciente":
        return sv.actualizar_paciente(session, cirugia_id, {params["campo"]: params["valor"]}, ctx, simular=simular)
    raise sv.ErrorNegocio("Acción no soportada.")


CAMBIOS = {
    "registrar_verificacion": ["checklist", "fases", "hitos", "alertas", "trazabilidad"],
    "registrar_consumo": ["insumos", "alertas", "trazabilidad"],
    "registrar_cantidad_inicial": ["insumos", "alertas", "trazabilidad"],
    "registrar_novedad": ["novedades", "alertas", "trazabilidad"],
    "registrar_evento": ["hitos", "alertas", "trazabilidad"],
    "cerrar_fase": ["fases", "checklist", "alertas", "trazabilidad"],
    "resolver_novedad": ["novedades", "alertas", "trazabilidad"],
    "registrar_anestesia": ["anestesia", "trazabilidad"],
    "registrar_dren": ["drenes", "checklist", "trazabilidad"],
    "registrar_sin_drenes": ["drenes", "checklist", "trazabilidad"],
    "actualizar_paciente": ["paciente", "alertas", "trazabilidad"],
}

CAMPO_NOMBRE = {"grupo_sanguineo": "grupo sanguíneo", "peso": "peso"}


def _texto_exito(session: Session, accion: str, params: dict, res: dict, cir: Cirugia, ctx: sv.Ctx) -> str:
    if accion == "registrar_verificacion":
        item = res["item"]
        pend = sv.pendientes_fase(session, cir.id, item["fase"])
        resto = f" Faltan {len(pend)} en la fase {item['fase']}." if pend else \
            f" La fase {item['fase']} ya no tiene obligatorios pendientes."
        auto = f" Hito automático: {HITOS[res['hito_automatico']][1].lower()}." if res.get("hito_automatico") else ""
        return (f"Registrado: {item['descripcion'].lower()}, por {ctx.usuario.nombre} a las "
                f"{sv.hhmm(item['verificado_en'])}.{auto}{resto}")
    if accion == "registrar_consumo":
        ins = res["insumo"]
        nombre = ins["nombre"].lower()
        if res["restante"] == 0:
            return f"Registrado: {params['cantidad']} {nombre}. {ins['nombre']} agotado; se generó una alerta."
        return (f"Registrado consumo de {params['cantidad']} {nombre}. Utilizado {ins['cantidad_utilizada']}, "
                f"disponible {res['restante']}.")
    if accion == "registrar_cantidad_inicial":
        ins = res["insumo"]
        return (f"Registrado: cantidad inicial de {ins['nombre'].lower()} {ins['cantidad_inicial']}. "
                f"Disponible {ins['cantidad_disponible']}.")
    if accion == "registrar_novedad":
        n = res["novedad"]
        return f"Novedad número {n['numero']} registrada: {n['descripcion']}."
    if accion == "registrar_evento":
        from datetime import datetime

        extra = " Con autorización justificada." if res.get("override") else ""
        return f"Registrado: {HITOS[params['hito']][1].lower()} a las {sv.hhmm(datetime.fromisoformat(res['hora']))}.{extra}"
    if accion == "cerrar_fase":
        fa = res["fase_actual"]
        sig = f" Ahora: fase {fa}, {FASES[fa].lower()}." if fa <= 3 else " Checklist completo."
        return f"Fase {params['fase']} cerrada.{sig}"
    if accion == "resolver_novedad":
        return f"Novedad número {res['novedad']['numero']} resuelta."
    if accion == "registrar_anestesia":
        return f"Registrada anestesia {res['anestesia']['tipo'].lower()} a las {sv.hhmm(res['anestesia']['ts'])}."
    if accion == "registrar_dren":
        d = res["dren"]
        return f"Registrado dren número {d['numero']}{', ' + d['tipo'] if d['tipo'] else ''}, cantidad {d['cantidad']}."
    if accion == "registrar_sin_drenes":
        return "Registrado: sin drenes."
    if accion == "actualizar_paciente":
        return f"Actualizado {CAMPO_NOMBRE.get(params['campo'], params['campo'])}: {res['paciente'][params['campo']]}."
    return "Registrado."


def _pedir_confirmacion(accion: str, params: dict, mensaje: str, ctx: sv.Ctx, cir: Cirugia,
                        intencion: str, refs: dict) -> dict:
    pid = uuid.uuid4().hex[:12]
    PENDIENTES[pid] = Pendiente(accion=accion, params=params, usuario_id=ctx.usuario.id,
                                cirugia_id=cir.id, mensaje=mensaje,
                                transcripcion=ctx.transcripcion or "", canal=ctx.canal,
                                cambios=CAMBIOS.get(accion, []), refs=refs)
    return _respuesta("confirmar", mensaje + " Diga sí o no.", pending_id=pid, intencion=intencion,
                      datos={"accion": accion, "params": params}, refs=refs)


def _intentar(session: Session, accion: str, params: dict, ctx: sv.Ctx, cir: Cirugia,
              intencion: str, refs: dict) -> dict:
    try:
        res = _ejecutar(session, accion, params, ctx, cir.id)
    except sv.RequiereConfirmacion as e:
        return _pedir_confirmacion(accion, {**params, "confirmado": True}, e.mensaje, ctx, cir, intencion, refs)
    except sv.ErrorNegocio as e:
        session.rollback()
        return _respuesta("error", e.mensaje, cambios=["trazabilidad"], intencion=intencion,
                          datos=e.datos, refs=refs)
    session.refresh(cir)
    return _respuesta("ok", _texto_exito(session, accion, params, res, cir, ctx),
                      cambios=CAMBIOS.get(accion), alertas=res.get("alertas_nuevas"),
                      intencion=intencion, refs=refs)


def _preguntar(texto: str, intencion: str) -> dict:
    return _respuesta("no_entendido", texto, intencion=intencion)


def _opciones(opciones: list[int], nombre: str) -> str:
    return " o ".join(f"{n} {nombre}" for n in opciones)


# ------------------------------------------------------------------ pipeline

NO_ENTENDIDO = "No logré identificar la acción. ¿Desea registrar un consumo, una verificación o un evento?"


def procesar(session: Session, texto: str, usuario_id: int, cirugia_id: int,
             pending_id: Optional[str] = None, canal: str = "voz") -> dict:
    _limpiar_expirados()
    usuario = session.get(Usuario, usuario_id)
    cir = session.get(Cirugia, cirugia_id)
    if usuario is None or cir is None:
        return _respuesta("error", "Usuario o cirugía inexistente.")
    ctx = sv.Ctx(usuario=usuario, canal=canal if canal in ("voz", "texto") else "voz",
                 transcripcion=texto)
    t = normalizar(texto)

    # 1. ¿Responde a una confirmación pendiente?
    pend = PENDIENTES.get(pending_id) if pending_id else None
    if pend is None:
        pend_id = next((k for k, p in reversed(list(PENDIENTES.items()))
                        if p.usuario_id == usuario_id and p.cirugia_id == cirugia_id), None)
        pend = PENDIENTES.get(pend_id) if pend_id else None
        pending_id = pend_id
    si, no = es_confirmacion(t), es_cancelacion(t)
    if pend is not None and (si or no):
        if pend.usuario_id != usuario_id:
            return _respuesta("error", "Solo quien dio la orden puede confirmarla.")
        PENDIENTES.pop(pending_id, None)
        ctx.transcripcion = f"{pend.transcripcion} → «{texto}»"
        if no:
            sv.registrar_cancelacion(session, cir.id, ctx, pend.accion,
                                     {"motivo": "Cancelado por el usuario", **pend.params})
            return _respuesta("ok", "Cancelado. No se registró nada.", cambios=["trazabilidad"],
                              intencion="cancelar")
        return _intentar(session, pend.accion, pend.params, ctx, cir, "confirmar", pend.refs)
    if (si or no) and pend is None:
        return _respuesta("error", "No hay ninguna acción pendiente de confirmar.", intencion="confirmar")

    if pend is not None:  # llegó otra orden: la confirmación anterior se descarta
        PENDIENTES.pop(pending_id, None)

    # 2. Intención y entidades
    cat_items, cat_insumos = _catalogos(session, cir.id)
    it = interpretar(texto, cat_items, cat_insumos)

    if it.duda:
        return _preguntar(f"No estoy seguro. ¿Se refiere a «{it.duda.nombre}»? Repita el comando con ese nombre.",
                          it.nombre)
    if it.nombre == "no_entendido":
        return _preguntar(NO_ENTENDIDO, "no_entendido")

    # 3. Consultas: responden directamente
    if it.nombre.startswith("consultar_"):
        txt, datos, cambios = _consultar(session, it, cir)
        sv.registrar_accion(session, cir.id, ctx, it.nombre, "consulta", None, {"respuesta": txt})
        session.commit()
        return _respuesta("ok", txt, cambios=cambios + ["trazabilidad"], intencion=it.nombre, datos=datos)

    e = it.entidades

    # 4. Datos incompletos o ambiguos: se pregunta, nunca se supone
    if it.nombre in ("registrar_consumo", "registrar_cantidad_inicial", "registrar_dren"):
        nombre_cosa = e.get("insumo", "drenes").lower()
        if e.get("opciones"):
            return _preguntar(f"¿Desea registrar {_opciones(e['opciones'], nombre_cosa)}?", it.nombre)
        if e.get("cantidad") is None:
            pregunta = (f"¿Cuántas unidades de {nombre_cosa} se consumieron?" if it.nombre == "registrar_consumo"
                        else f"¿Cuál es la cantidad inicial de {nombre_cosa} para esta cirugía?")
            return _preguntar(pregunta, it.nombre)

    if it.nombre == "registrar_consumo":
        return _intentar(session, "registrar_consumo",
                         {"insumo_id": e["insumo_id"], "cantidad": e["cantidad"]},
                         ctx, cir, it.nombre, {"insumo_id": e["insumo_id"]})

    if it.nombre == "registrar_novedad":
        if not e.get("descripcion") or len(e["descripcion"]) < 3:
            return _preguntar("¿Cuál es la novedad? Diga, por ejemplo: registrar novedad, falla en el cable de la cámara.",
                              it.nombre)
        return _intentar(session, "registrar_novedad", {"descripcion": e["descripcion"]}, ctx, cir,
                         it.nombre, {})

    # 5. Acciones que piden confirmación: se validan (simulación) antes de preguntar
    if it.nombre == "registrar_verificacion":
        accion, params, refs = "registrar_verificacion", {"item_id": e["item_id"], "resultado": e["resultado"]}, \
            {"item_id": e["item_id"]}
        msg = f"Confirma: «{e['item']}», resultado: {e['resultado'].lower()}, por {usuario.nombre}."
    elif it.nombre == "registrar_cantidad_inicial":
        ins = session.get(Insumo, e["insumo_id"])
        accion, params, refs = "registrar_cantidad_inicial", {"insumo_id": ins.id, "cantidad": e["cantidad"]}, \
            {"insumo_id": ins.id}
        previo = f" (reemplaza el valor anterior: {ins.cantidad_inicial})" if ins.inicial_registrada_en else ""
        msg = f"¿Confirma registrar {e['cantidad']} {ins.nombre.lower()} como cantidad inicial para esta cirugía{previo}?"
    elif it.nombre == "registrar_evento":
        accion, params, refs = "registrar_evento", {"hito": e["hito"], "justificacion": e.get("justificacion")}, \
            {"hito": e["hito"]}
        msg = f"¿Confirma registrar «{HITOS[e['hito']][1]}» ahora?"
        if e.get("justificacion"):
            msg += f" Justificación: {e['justificacion']}."
    elif it.nombre == "cerrar_fase":
        fase = e.get("fase") or cir.fase_actual
        if fase > 3:
            return _respuesta("error", "Las tres fases ya están cerradas.", intencion=it.nombre)
        accion, params, refs = "cerrar_fase", {"fase": fase}, {"fase": fase}
        msg = f"¿Confirma cerrar la fase {fase}, {FASES[fase].lower()}?"
    elif it.nombre == "resolver_novedad":
        abiertas = session.exec(select(Novedad).where(Novedad.cirugia_id == cir.id,
                                                      Novedad.estado == "abierta")).all()
        num = e.get("numero")
        nov = next((n for n in abiertas if n.numero == num), None) if num else (
            abiertas[0] if len(abiertas) == 1 else None)
        if nov is None:
            txt = "No hay novedades abiertas." if not abiertas else \
                f"¿Qué novedad desea resolver? Abiertas: {_lista(['número ' + str(n.numero) for n in abiertas])}."
            return _preguntar(txt, it.nombre)
        if not e.get("accion_correctiva"):
            return _preguntar(f"Indique la acción correctiva. Por ejemplo: novedad {nov.numero} resuelta, se cambió el cable.",
                              it.nombre)
        accion, params, refs = "resolver_novedad", {"novedad_id": nov.id, "accion_correctiva": e["accion_correctiva"]}, \
            {"novedad_id": nov.id}
        msg = f"¿Confirma resolver la novedad número {nov.numero} con la acción: {e['accion_correctiva'].lower()}?"
    elif it.nombre == "registrar_anestesia":
        if not e.get("tipo"):
            return _preguntar("¿Qué tipo de anestesia desea registrar? General, regional raquídea, epidural, "
                              "bloqueo de nervio periférico, local o sedación.", it.nombre)
        accion, params, refs = "registrar_anestesia", {"tipo": e["tipo"]}, {}
        msg = f"¿Confirma agregar anestesia {e['tipo'].lower()} a esta cirugía?"
    elif it.nombre == "registrar_dren":
        siguiente = (session.exec(select(func.count()).select_from(Dren).where(Dren.cirugia_id == cir.id)).one() or 0) + 1
        if e.get("numero") and e["numero"] != siguiente:
            return _respuesta("error", f"El dren número {e['numero']} no corresponde: el siguiente a registrar es el "
                                       f"número {siguiente}.", intencion=it.nombre)
        accion = "registrar_dren"
        params = {"tipo": e.get("tipo"), "cantidad": e["cantidad"], "observaciones": e.get("observaciones")}
        refs = {}
        msg = (f"¿Confirma registrar el dren número {siguiente}, tipo {(e.get('tipo') or 'sin especificar').lower()}, "
               f"cantidad {e['cantidad']}?")
    elif it.nombre == "registrar_sin_drenes":
        accion, params, refs = "registrar_sin_drenes", {}, {}
        msg = "¿Confirma registrar que el paciente sale sin drenes?"
    elif it.nombre == "actualizar_paciente":
        campo, valor = e["campo"], e.get("valor")
        if valor is None:
            return _preguntar(f"¿Cuál es el {CAMPO_NOMBRE[campo]}? Por ejemplo: grupo sanguíneo O positivo.", it.nombre)
        accion, params, refs = "actualizar_paciente", {"campo": campo, "valor": valor}, {}
        msg = f"¿Confirma registrar {CAMPO_NOMBRE[campo]} {valor}{' kg' if campo == 'peso' else ''}?"
    else:
        return _preguntar(NO_ENTENDIDO, it.nombre)

    try:
        _ejecutar(session, accion, params, ctx, cir.id, simular=True)
    except sv.ErrorNegocio as err:
        session.rollback()
        return _respuesta("error", err.mensaje, cambios=["trazabilidad"], intencion=it.nombre,
                          datos=err.datos, refs=refs)
    return _pedir_confirmacion(accion, params, msg, ctx, cir, it.nombre, refs)

