from contextlib import asynccontextmanager
from typing import Literal, Optional

from fastapi import Depends, FastAPI, HTTPException, Request
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import JSONResponse
from pydantic import BaseModel, Field
from sqlmodel import Session, select

from app import config_services as cfg
from app import services as sv
from app.agent import agent
from app.catalogos import GRUPOS_SANGUINEOS, TIPOS_ANESTESIA, TIPOS_DREN
from app.db import create_db, engine, esquema_desactualizado, get_session
from app.models import Alerta, Cirugia, Insumo, Paciente, Usuario
from app.stats import dashboard


@asynccontextmanager
async def lifespan(_: FastAPI):
    create_db()
    with Session(engine) as s:
        vacia = s.exec(select(Usuario)).first() is None
    if vacia or esquema_desactualizado():
        from app.seed import sembrar

        sembrar()
    yield


app = FastAPI(title="Tablero Inteligente de Seguridad Quirúrgica", version="2.0", lifespan=lifespan)
app.add_middleware(CORSMiddleware, allow_origins=["*"], allow_methods=["*"], allow_headers=["*"])


@app.exception_handler(sv.ErrorNegocio)
async def _error_negocio(_: Request, exc: sv.ErrorNegocio):
    return JSONResponse(status_code=exc.status,
                        content={"estado": "error", "resultado": exc.resultado, "texto": exc.mensaje,
                                 "datos": exc.datos})


@app.exception_handler(sv.RequiereConfirmacion)
async def _requiere_confirmacion(_: Request, exc: sv.RequiereConfirmacion):
    return JSONResponse(status_code=409, content={"estado": "confirmar", "texto": exc.mensaje,
                                                  "datos": exc.datos})


def _ctx(session: Session, usuario_id: int) -> sv.Ctx:
    u = session.get(Usuario, usuario_id)
    if u is None or not u.activo:
        raise HTTPException(401, "Usuario no válido")
    return sv.Ctx(usuario=u, canal="ui")


# ------------------------------------------------------------------ esquemas

class ConUsuario(BaseModel):
    usuario_id: int


class EventoIn(ConUsuario):
    hito: str
    justificacion: Optional[str] = None


class VerificarIn(ConUsuario):
    resultado: Optional[str] = None


class ConsumoIn(ConUsuario):
    insumo_id: int
    cantidad: int = Field(gt=0)
    confirmado: bool = False


class InicialIn(ConUsuario):
    cantidad: int = Field(ge=0)


class AgregarInsumoIn(ConUsuario):
    catalogo_id: int


class NovedadIn(ConUsuario):
    descripcion: str
    severidad: Literal["baja", "media", "alta"] = "media"
    categoria: Optional[str] = None


class ResolverIn(ConUsuario):
    accion_correctiva: str


class PacienteIn(ConUsuario):
    campos: dict


class CirugiaIn(ConUsuario):
    procedimiento_registrado: Optional[str] = None
    sitio_registrado: Optional[str] = None


class NuevaCirugiaIn(ConUsuario):
    tipo_procedimiento_id: int
    paciente: dict
    sitio: Optional[str] = None
    quirofano: Optional[str] = None
    fecha_programada: Optional[str] = None
    equipo: list[int] = []


class AnestesiaIn(ConUsuario):
    tipo: str
    observaciones: Optional[str] = None


class AnularIn(ConUsuario):
    motivo: Optional[str] = None


class DrenIn(ConUsuario):
    tipo: Optional[str] = None
    cantidad: int = Field(default=1, ge=1)
    observaciones: Optional[str] = None


class ReglaIn(ConUsuario):
    activa: Optional[bool] = None
    modal: Optional[bool] = None


class UmbralIn(ConUsuario):
    umbral_preventivo_pct: int


class TipoPersonaIn(ConUsuario):
    nombre: str
    acceso_operativo: bool = False
    puede_configurar: bool = False


class TipoPersonaPatch(ConUsuario):
    nombre: Optional[str] = None
    activo: Optional[bool] = None
    acceso_operativo: Optional[bool] = None
    puede_configurar: Optional[bool] = None


class UsuarioIn(ConUsuario):
    nombre: str
    rol: str


class UsuarioPatch(ConUsuario):
    activo: bool


class ProcedimientoIn(ConUsuario):
    nombre: str
    sitio_sugerido: Optional[str] = None


class AsociacionIn(ConUsuario):
    insumo_id: int
    cantidad_sugerida: Optional[int] = Field(default=None, ge=0)


class CatalogoIn(ConUsuario):
    nombre: str
    unidad: str = "unidades"
    umbral_preventivo: Optional[int] = Field(default=None, ge=0)
    aliases: str = ""


class CatalogoPatch(ConUsuario):
    umbral_preventivo: Optional[int] = Field(default=None, ge=0)
    activo: Optional[bool] = None


class ComandoIn(BaseModel):
    texto: str
    usuario_id: int
    cirugia_id: int
    pending_id: Optional[str] = None
    canal: Literal["voz", "texto"] = "voz"


# ------------------------------------------------------------- catálogos y personas

