def crear_usuario(body: UsuarioIn, session: Session = Depends(get_session)):
    return cfg.crear_usuario(session, body.nombre, body.rol, _ctx(session, body.usuario_id))


@app.patch("/api/usuarios/{uid}")
def editar_usuario(uid: int, body: UsuarioPatch, session: Session = Depends(get_session)):
    return cfg.actualizar_usuario(session, uid, body.activo, _ctx(session, body.usuario_id))


