                          _ctx(session, body.usuario_id))


@app.patch("/api/tipos-persona/{tid}")
def editar_tipo(tid: int, body: TipoPersonaPatch, session: Session = Depends(get_session)):
    return cfg.actualizar_tipo(session, tid, body.model_dump(exclude={"usuario_id"}), _ctx(session, body.usuario_id))


@app.get("/api/catalogos")
def catalogos(session: Session = Depends(get_session)):
    return {"tipos_anestesia": [n for n, _ in TIPOS_ANESTESIA], "tipos_dren": [n for n, _ in TIPOS_DREN],
            "grupos_sanguineos": list(GRUPOS_SANGUINEOS)}


@app.get("/api/procedimientos")
def procedimientos(session: Session = Depends(get_session)):
