@app.delete("/api/procedimientos/insumos/{aid}")
def quitar_insumo(aid: int, usuario_id: int, session: Session = Depends(get_session)):
    return cfg.quitar_insumo(session, aid, _ctx(session, usuario_id))


@app.get("/api/catalogo-insumos")
def catalogo_insumos(session: Session = Depends(get_session)):
    return cfg.listar_catalogo(session)


@app.post("/api/catalogo-insumos")
def crear_insumo_catalogo(body: CatalogoIn, session: Session = Depends(get_session)):
    return cfg.crear_insumo_catalogo(session, body.nombre, body.unidad, body.umbral_preventivo, body.aliases,
                                     _ctx(session, body.usuario_id))


@app.patch("/api/catalogo-insumos/{iid}")
def editar_insumo_catalogo(iid: int, body: CatalogoPatch, session: Session = Depends(get_session)):
    return cfg.actualizar_insumo_catalogo(session, iid, body.model_dump(exclude={"usuario_id"}, exclude_unset=True),
                                          _ctx(session, body.usuario_id))


# ------------------------------------------------------------------ reglas

@app.get("/api/reglas")
def reglas(session: Session = Depends(get_session)):
    return cfg.listar_reglas(session)


@app.patch("/api/reglas/{codigo}")
def editar_regla(codigo: str, body: ReglaIn, session: Session = Depends(get_session)):
    return cfg.actualizar_regla(session, codigo, body.model_dump(exclude={"usuario_id"}), _ctx(session, body.usuario_id))


@app.put("/api/configuracion/umbral")
def umbral(body: UmbralIn, session: Session = Depends(get_session)):
    return cfg.actualizar_umbral_pct(session, body.umbral_preventivo_pct, _ctx(session, body.usuario_id))


@app.get("/api/trazabilidad/configuracion")
def trazabilidad_config(session: Session = Depends(get_session)):
    return sv.listar_trazabilidad(session, None, limite=200)


# ------------------------------------------------------------------ cirugías

@app.get("/api/cirugias")
def cirugias(session: Session = Depends(get_session)):
    pac = {p.id: p for p in session.exec(select(Paciente))}
    orden = {"en_curso": 0, "programada": 1, "finalizada": 2}
    filas = sorted(session.exec(select(Cirugia)).all(),
                   key=lambda c: (orden.get(c.estado, 3), -c.fecha_programada.timestamp()))
    return [{"id": c.id, "procedimiento": c.procedimiento_programado, "paciente": pac[c.paciente_id].nombre,
             "estado": c.estado, "fase_actual": c.fase_actual, "quirofano": c.quirofano,
             "fecha": c.fecha_programada} for c in filas]


@app.post("/api/cirugias")
def nueva_cirugia(body: NuevaCirugiaIn, session: Session = Depends(get_session)):
    return sv.crear_cirugia(session, body.model_dump(exclude={"usuario_id"}), _ctx(session, body.usuario_id))


@app.get("/api/cirugias/{cid}")
def cirugia(cid: int, session: Session = Depends(get_session)):
