@app.get("/api/cirugias/{cid}/trazabilidad")
def trazabilidad(cid: int, usuario_id: Optional[int] = None, accion: Optional[str] = None,
                 canal: Optional[str] = None, resultado: Optional[str] = None,
                 session: Session = Depends(get_session)):
