import { useCallback, useEffect, useRef, useState } from 'react'

const SR = typeof window !== 'undefined' ? window.SpeechRecognition || window.webkitSpeechRecognition : null

const CONFIANZA_MINIMA = 0.35

/**
 * Escucha continua con Web Speech API (es-CO).
 * Ciclo: escuchando → (frase final) procesando → respondiendo (TTS, micrófono en pausa) → escuchando.
 * `onFrase(texto)` devuelve una promesa con el texto a hablar (o null para no responder en voz).
 */
export function useVoz(onFrase, { activoInicial = true } = {}) {
  const [modo, setModo] = useState('pausado') // escuchando | procesando | respondiendo | pausado
  const [activo, setActivo] = useState(false)
  const [parcial, setParcial] = useState('')
  const [error, setError] = useState(null)
  const recRef = useRef(null)
  const activoRef = useRef(false)
  const ocupadoRef = useRef(false)
  const onFraseRef = useRef(onFrase)
  const vozRef = useRef(null)
  const reintentoRef = useRef(null)
  const escucharRef = useRef(() => {})

  useEffect(() => {
    onFraseRef.current = onFrase
  }, [onFrase])

  useEffect(() => {
    if (!window.speechSynthesis) return
    const elegir = () => {
      const voces = window.speechSynthesis.getVoices()
      vozRef.current =
        voces.find((v) => v.lang === 'es-CO') ||
        voces.find((v) => v.lang?.startsWith('es-') && /google|microsoft/i.test(v.name)) ||
        voces.find((v) => v.lang?.startsWith('es')) ||
        null
    }
    elegir()
    window.speechSynthesis.onvoiceschanged = elegir
  }, [])

  const cortarMicrofono = () => {
    clearTimeout(reintentoRef.current)
    const rec = recRef.current
    recRef.current = null
    if (rec) {
      rec.onend = null
      rec.onresult = null
      rec.onerror = null
      try {
        rec.abort()
      } catch {
        /* ya detenido */
      }
    }
  }

  const reanudar = useCallback(() => {
    ocupadoRef.current = false
    if (activoRef.current) escucharRef.current()
    else setModo('pausado')
  }, [])

  const hablar = useCallback((texto) => {
    return new Promise((resolve) => {
      if (!window.speechSynthesis || !texto) return resolve()
      window.speechSynthesis.cancel()
      const u = new SpeechSynthesisUtterance(texto)
      u.lang = 'es-CO'
      if (vozRef.current) u.voice = vozRef.current
      u.rate = 1.05
      const limite = setTimeout(resolve, 2000 + texto.length * 90)
      u.onend = u.onerror = () => {
        clearTimeout(limite)
        resolve()
      }
      window.speechSynthesis.speak(u)
    })
  }, [])

  /** Habla con el micrófono en pausa para que el agente no se escuche a sí mismo. */
  const responder = useCallback(
    async (texto) => {
      if (!texto) return
      ocupadoRef.current = true
      cortarMicrofono()
      setModo('respondiendo')
      await hablar(texto)
      await new Promise((r) => setTimeout(r, 250))
      reanudar()
    },
    [hablar, reanudar],
  )

  const procesar = useCallback(
    async (texto) => {
      ocupadoRef.current = true
      cortarMicrofono()
      setParcial('')
      setModo('procesando')
      let respuesta = null
      try {
        respuesta = await onFraseRef.current?.(texto)
      } catch {
        respuesta = null
      }
      if (respuesta) {
        setModo('respondiendo')
        await hablar(respuesta)
        await new Promise((r) => setTimeout(r, 250))
      }
      reanudar()
    },
    [hablar, reanudar],
  )

  const escuchar = useCallback(() => {
    if (!SR || recRef.current || !activoRef.current || ocupadoRef.current) return
    const rec = new SR()
    rec.lang = 'es-CO'
    rec.continuous = true
    rec.interimResults = true
    rec.maxAlternatives = 1
    rec.onresult = (e) => {
      let interino = ''
      for (let i = e.resultIndex; i < e.results.length; i++) {
        const r = e.results[i]
        const texto = r[0].transcript.trim()
        if (r.isFinal) {
          const conf = r[0].confidence
          const fiable = !conf || conf >= CONFIANZA_MINIMA
          if (texto.length >= 2 && fiable) {
            procesar(texto)
            return
          }
        } else {
          interino += ' ' + texto
        }
      }
      setParcial(interino.trim())
    }
    rec.onerror = (e) => {
      if (e.error === 'not-allowed' || e.error === 'service-not-allowed') {
        setError('Permiso de micrófono denegado. Habilítelo en el navegador y pulse «Reanudar».')
        activoRef.current = false
        setActivo(false)
      } else if (e.error === 'network') {
        setError('Sin conexión: el reconocimiento de voz de Chrome requiere internet. Use el campo de texto.')
        activoRef.current = false
        setActivo(false)
      } else if (e.error === 'audio-capture') {
        setError('No se detecta micrófono.')
        activoRef.current = false
        setActivo(false)
      }
    }
    rec.onend = () => {
      recRef.current = null
      setParcial('')
      if (activoRef.current && !ocupadoRef.current) {
        reintentoRef.current = setTimeout(() => escucharRef.current(), 300)
      } else if (!ocupadoRef.current) {
        setModo('pausado')
      }
    }
    recRef.current = rec
    try {
      rec.start()
      setError(null)
      setModo('escuchando')
    } catch {
      recRef.current = null
    }
  }, [procesar])

  useEffect(() => {
    escucharRef.current = escuchar
  }, [escuchar])

  const activar = useCallback(() => {
    if (!SR) return
    activoRef.current = true
    setActivo(true)
    localStorage.setItem('voz_pausada', '0')
    if (!ocupadoRef.current) escucharRef.current()
  }, [])

  const pausar = useCallback(() => {
    activoRef.current = false
    setActivo(false)
    localStorage.setItem('voz_pausada', '1')
    cortarMicrofono()
    window.speechSynthesis?.cancel()
    ocupadoRef.current = false
    setParcial('')
    setModo('pausado')
  }, [])

  useEffect(() => {
    if (activoInicial && SR && localStorage.getItem('voz_pausada') !== '1') activar()
    return () => {
      activoRef.current = false
      cortarMicrofono()
      window.speechSynthesis?.cancel()
    }
  }, [activoInicial, activar])

  return { soportado: !!SR, modo, activo, parcial, error, activar, pausar, responder }
}

import { useCallback, useEffect, useRef, useState } from 'react'
import { api } from '../api'
import { useVoz } from '../useVoz'
import { Boton, Card } from './ui'

const FRASES_DEMO = [
  'Registrar 20 gasas para esta cirugía',
  'Registrar que se verificaron los equipos',
  'Registrar consumo de 3 gasas',
  '¿Cuántas gasas quedan?',
  '¿Cuál es el grupo sanguíneo?',
  'Registrar que el paciente ingresó a quirófano',
  'Agregar anestesia general',
  'Registrar inicio de anestesia',
  'Registrar dren número 1',
  'Registrar una novedad',
  'Registrar novedad: falla en el cable de la cámara',
  '¿Qué nos falta para completar esta fase?',
  '¿Hay alertas activas?',
]

const ESTILO_ESTADO = {
  ok: 'border-emerald-200 bg-emerald-50 text-emerald-900',
  confirmar: 'border-amber-300 bg-amber-50 text-amber-950',
  error: 'border-red-200 bg-red-50 text-red-900',
  no_entendido: 'border-slate-200 bg-slate-50 text-slate-700',
}

const MODO = {
  escuchando: { texto: 'Escuchando', color: 'bg-emerald-600', anillo: 'onda-verde' },
  procesando: { texto: 'Procesando', color: 'bg-sky-600', anillo: 'animate-pulse' },
  respondiendo: { texto: 'Respondiendo', color: 'bg-violet-600', anillo: 'animate-pulse' },
  pausado: { texto: 'Pausado', color: 'bg-slate-500', anillo: '' },
}

/** Frases muy cortas sin intención reconocible se consideran ruido de quirófano y no se responden. */
const esRuido = (frase, res) =>
  res.estado === 'no_entendido' && res.intencion === 'no_entendido' && frase.trim().split(/\s+/).length < 3

export default function AgenteVoz({ usuario, cirugiaId, onRespuesta }) {
  const [historial, setHistorial] = useState([])
  const [pendiente, setPendiente] = useState(null)
  const [restante, setRestante] = useState(0)
  const [texto, setTexto] = useState('')
  const [silencio, setSilencio] = useState(false)
  const [enviando, setEnviando] = useState(false)
  const [mostrarFrases, setMostrarFrases] = useState(true)
  const finRef = useRef(null)
  const estadoRef = useRef({})
  estadoRef.current = { usuario, pendiente, cirugiaId, silencio }

  /** Envía la frase al backend; devuelve el texto a hablar (o null). */
  const enviar = useCallback(
    async (frase, canal) => {
      const { usuario: u, pendiente: p, cirugiaId: cid, silencio: mudo } = estadoRef.current
      if (!frase.trim() || !u) return null
      setEnviando(true)
      const r = await api.post('/agent/command', {
        texto: frase,
        usuario_id: u.id,
        cirugia_id: cid,
        pending_id: p?.id || null,
        canal,
      })
      setEnviando(false)
      const res = r.ok ? r.data : { estado: 'error', texto: r.data?.texto || 'Error de comunicación con el servidor.' }
      if (canal === 'voz' && esRuido(frase, res)) {
        setHistorial((h) => [...h, { tipo: 'ruido', texto: frase }])
        return null
      }
      setHistorial((h) => [...h, { tipo: 'usuario', texto: frase, canal, quien: u }, { tipo: 'agente', ...res }])
      if (res.estado === 'confirmar') setPendiente({ id: res.pending_id, expira: Date.now() + (res.expira_en || 60) * 1000 })
      else setPendiente(null)
      onRespuesta?.(res)
      return mudo ? null : res.texto
    },
    [onRespuesta],
  )

  const voz = useVoz((t) => enviar(t, 'voz'))

  const enviarTexto = async (frase) => {
    const hablar = await enviar(frase, 'texto')
    if (hablar) voz.responder(hablar)
  }

  useEffect(() => {
    finRef.current?.scrollIntoView({ block: 'nearest' })
  }, [historial])

  useEffect(() => {
    if (!pendiente) return
    const t = setInterval(() => {
      const s = Math.max(0, Math.round((pendiente.expira - Date.now()) / 1000))
      setRestante(s)
      if (s === 0) setPendiente(null)
    }, 250)
    return () => clearInterval(t)
  }, [pendiente])

  const m = MODO[voz.modo] || MODO.pausado

  return (
    <Card
      titulo="Agente de voz"
      extra={
        <label className="flex cursor-pointer items-center gap-1 text-xs text-slate-500">
          <input type="checkbox" checked={!silencio} onChange={(e) => setSilencio(!e.target.checked)} />
          Respuesta hablada
        </label>
      }
    >
      <div className="flex items-center gap-4">
        <div
          className={`relative isolate flex h-16 w-16 shrink-0 items-center justify-center rounded-full text-white shadow-lg ${m.color} ${
            voz.modo === 'escuchando' ? 'onda-verde' : m.anillo
          }`}
          aria-label={`Agente: ${m.texto}`}
        >
          <svg viewBox="0 0 24 24" className="h-8 w-8" fill="currentColor">
            <path d="M12 14a3 3 0 0 0 3-3V5a3 3 0 0 0-6 0v6a3 3 0 0 0 3 3Zm5-3a5 5 0 0 1-10 0H5a7 7 0 0 0 6 6.92V21h2v-3.08A7 7 0 0 0 19 11h-2Z" />
          </svg>
        </div>
        <div className="min-w-0 flex-1 text-sm">
          <div className="flex flex-wrap items-center gap-2">
            <span className="font-bold">{voz.activo ? '🎙 Agente activo' : 'Agente en pausa'}</span>
            <span className={`rounded-full px-2 py-0.5 text-xs font-bold uppercase tracking-wide text-white ${m.color}`}>
              {enviando && voz.modo !== 'procesando' ? 'Procesando' : m.texto}
            </span>
          </div>
          <div className="mt-0.5 text-xs text-slate-500">
            Registra como <span className="font-medium text-slate-700">{usuario.nombre}</span> ({usuario.rol_nombre}).
            {voz.activo ? ' Hable con normalidad; no hace falta pulsar nada.' : ''}
          </div>
          {voz.parcial && <div className="mt-1 italic text-slate-700">«{voz.parcial}»</div>}
          {!voz.soportado && (
            <div className="mt-1 text-xs text-red-600">
              Este navegador no soporta reconocimiento de voz. Use Chrome o Edge, o el campo de texto.
            </div>
          )}
          {voz.error && <div className="mt-1 text-xs font-medium text-red-600">{voz.error}</div>}
        </div>
        {voz.soportado && (
          <Boton variante={voz.activo ? 'secundario' : 'exito'} onClick={voz.activo ? voz.pausar : voz.activar}>
            {voz.activo ? 'Pausar' : 'Reanudar'}
          </Boton>
        )}
      </div>

      {pendiente && (
        <div className="mt-3 flex items-center justify-between gap-2 rounded-lg border-2 border-amber-400 bg-amber-50 p-2.5">
          <span className="text-sm font-semibold text-amber-900">Esperando confirmación · diga «sí» o «no» · {restante}s</span>
          <div className="flex gap-2">
            <Boton variante="exito" onClick={() => enviarTexto('sí')}>
              Sí, confirmo
            </Boton>
            <Boton variante="secundario" onClick={() => enviarTexto('no, cancela')}>
              No, cancela
            </Boton>
          </div>
        </div>
      )}

      <div className="mt-3 max-h-72 space-y-2 overflow-y-auto pr-1">
        {historial.length === 0 && (
          <p className="text-sm text-slate-400">
            Ejemplos: «Registrar 20 gasas para esta cirugía», «Registrar consumo de 3 gasas», «¿Cuál es el grupo sanguíneo?».
          </p>
        )}
        {historial.map((h, i) =>
          h.tipo === 'ruido' ? (
            <div key={i} className="ml-8 text-right text-[11px] italic text-slate-400">
              Ignorado (posible ruido): «{h.texto}»
            </div>
          ) : h.tipo === 'usuario' ? (
            <div key={i} className="ml-8 rounded-lg bg-slate-800 px-3 py-2 text-sm text-white">
              <div className="text-[10px] uppercase tracking-wide text-slate-400">
                {h.quien.nombre} · {h.canal}
              </div>
              {h.texto}
            </div>
          ) : (
            <div key={i} className={`mr-8 rounded-lg border px-3 py-2 text-sm ${ESTILO_ESTADO[h.estado] || ''}`}>
              <div className="text-[10px] font-semibold uppercase tracking-wide opacity-60">Agente · {h.estado}</div>
              {h.texto}
              {h.datos?.pendientes?.length > 0 && (
                <ul className="mt-1 list-disc pl-5 text-xs">
                  {h.datos.pendientes.map((p) => (
                    <li key={p}>{p}</li>
                  ))}
                </ul>
              )}
            </div>
          ),
        )}
        <div ref={finRef} />
      </div>

      <form
        className="mt-3 flex gap-2"
        onSubmit={(e) => {
          e.preventDefault()
          enviarTexto(texto)
          setTexto('')
        }}
      >
        <input
          value={texto}
          onChange={(e) => setTexto(e.target.value)}
          placeholder="Escriba un comando (respaldo del micrófono)"
          className="flex-1 rounded-lg border border-slate-300 px-3 py-1.5 text-sm outline-none focus:border-sky-500"
        />
        <Boton type="submit" disabled={!texto.trim() || enviando}>
          Enviar
        </Boton>
      </form>

      <div className="mt-3">
        <button
          onClick={() => setMostrarFrases((v) => !v)}
          className="text-xs font-semibold uppercase tracking-wide text-slate-500 hover:text-slate-700"
        >
          {mostrarFrases ? '▾' : '▸'} Frases de demo
        </button>
        {mostrarFrases && (
          <div className="mt-2 flex flex-wrap gap-1.5">
            {FRASES_DEMO.map((f) => (
              <button
                key={f}
                onClick={() => enviarTexto(f)}
                className="rounded-full border border-slate-200 bg-slate-50 px-2.5 py-1 text-left text-xs hover:border-sky-300 hover:bg-sky-50"
              >
                {f}
              </button>
            ))}
          </div>
        )}
      </div>
    </Card>
  )
}

