import { useEffect, useRef } from 'react'
import { hora } from '../api'
import { Boton, SEVERIDAD } from './ui'

const ETIQUETA = {
  insumo: 'Insumo',
  inicial: 'Cantidad inicial',
  utilizado: 'Utilizado',
  disponible: 'Disponible',
  umbral: 'Umbral preventivo',
  faltantes: 'Datos faltantes',
  sitio_programado: 'Sitio programado',
  programado: 'Programado',
  registrado: 'Registrado',
  alergias: 'Alergias',
  pendientes: 'Pendientes',
  novedad: 'Novedad #',
  categoria: 'Categoría',
}

const ORDEN = { alta: 0, media: 1, baja: 2 }

function pitido() {
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)()
    ;[0, 0.25].forEach((t) => {
      const o = ctx.createOscillator()
      const g = ctx.createGain()
      o.frequency.value = 880
      g.gain.setValueAtTime(0.15, ctx.currentTime + t)
      g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + t + 0.2)
      o.connect(g).connect(ctx.destination)
      o.start(ctx.currentTime + t)
      o.stop(ctx.currentTime + t + 0.2)
    })
  } catch {
    /* sin audio */
  }
}

export function alertasInterruptivas(alertas = []) {
  return alertas
    .filter((a) => a.interrumpe && !a.reconocida_en)
    .sort((a, b) => ORDEN[a.severidad] - ORDEN[b.severidad] || a.id - b.id)
}

/** Modal central para alertas importantes: aparece sobre cualquier sección hasta que se reconoce. */
export default function AlertaModal({ alertas, reglas, onReconocer, onIrAResolver }) {
  const cola = alertasInterruptivas(alertas)
  const a = cola[0]
  const vistas = useRef(new Set())

  useEffect(() => {
    if (a && !vistas.current.has(a.id)) {
      vistas.current.add(a.id)
      pitido()
    }
  }, [a])

  if (!a) return null
  const s = SEVERIDAD[a.severidad]
  const regla = reglas[a.regla] || {}
  const detalle = Object.entries(a.detalle || {}).filter(([k, v]) => v !== null && v !== '' && k !== 'unidad')

  return (
    <div className="fixed inset-0 z-[70] flex items-center justify-center bg-slate-950/70 p-4 backdrop-blur-sm" role="alertdialog" aria-modal="true">
      <div className={`w-full max-w-2xl overflow-hidden rounded-2xl bg-white shadow-2xl ${a.severidad === 'alta' ? 'latido' : ''}`}>
        <div className={`${s.modal} px-6 py-4 text-white`}>
          <div className="flex items-center justify-between gap-3">
            <div className="flex items-center gap-3">
              <span className="flex h-12 w-12 items-center justify-center rounded-full bg-white/20 text-3xl font-black">!</span>
              <div>
                <div className="text-sm font-bold uppercase tracking-widest opacity-90">
                  {s.texto} · {a.regla} {regla.nombre ? `· ${regla.nombre}` : ''}
                </div>
                <div className="text-xs opacity-80">Generada a las {hora(a.creada_en)}</div>
              </div>
            </div>
            {cola.length > 1 && (
              <span className="rounded-full bg-white/25 px-3 py-1 text-sm font-bold">1 de {cola.length}</span>
            )}
          </div>
          <p className="mt-3 text-2xl font-bold leading-snug">{a.mensaje}</p>
        </div>

        <div className="space-y-4 px-6 py-5 text-base">
          {regla.descripcion && (
            <div>
              <div className="text-xs font-bold uppercase tracking-wide text-slate-500">Motivo</div>
              <p className="text-slate-800">{regla.descripcion}</p>
            </div>
          )}
          {detalle.length > 0 && (
            <div>
              <div className="text-xs font-bold uppercase tracking-wide text-slate-500">Información relacionada</div>
              <dl className="mt-1 grid grid-cols-2 gap-x-6 gap-y-1 sm:grid-cols-3">
                {detalle.map(([k, v]) => (
                  <div key={k}>
                    <dt className="text-xs text-slate-500">{ETIQUETA[k] || k}</dt>
                    <dd className="font-semibold">{Array.isArray(v) ? v.join(', ') : String(v)}</dd>
                  </div>
                ))}
              </dl>
            </div>
          )}
          {a.accion_requerida && (
            <div className="rounded-lg border-2 border-slate-800 bg-slate-50 p-3">
              <div className="text-xs font-bold uppercase tracking-wide text-slate-500">Acción requerida</div>
              <p className="text-lg font-semibold text-slate-900">{a.accion_requerida}</p>
            </div>
          )}
        </div>

        <div className="flex flex-wrap items-center justify-between gap-2 border-t border-slate-200 bg-slate-50 px-6 py-4">
          <span className="text-xs text-slate-500">
            La alerta sigue activa en el tablero hasta que se cumpla la condición. Queda registrada en trazabilidad.
          </span>
          <div className="flex gap-2">
            <Boton variante="secundario" className="!px-4 !py-2 !text-base" onClick={() => onIrAResolver(a)}>
              Ir a resolver
            </Boton>
            <Boton variante={a.severidad === 'alta' ? 'peligro' : 'primario'} className="!px-5 !py-2 !text-base" onClick={() => onReconocer(a)} autoFocus>
              Entendido
            </Boton>
          </div>
        </div>
      </div>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { api } from '../api'
import { Boton, Campo, INPUT, Modal } from './ui'

const NUM = new Set(['edad', 'peso', 'talla', 'frecuencia_cardiaca', 'saturacion_o2', 'temperatura'])

const CAMPOS = [
  ['nombre', 'Nombre completo *'],
  ['documento', 'Identificación'],
  ['edad', 'Edad (años)'],
  ['peso', 'Peso (kg)'],
  ['talla', 'Talla (m)'],
  ['alergias', 'Alergias'],
  ['presion_arterial', 'Presión arterial'],
  ['frecuencia_cardiaca', 'Frecuencia cardiaca'],
  ['saturacion_o2', 'Saturación O₂ (%)'],
  ['temperatura', 'Temperatura (°C)'],
]

export default function NuevaCirugia({ ejecutar, onCreada, onCerrar }) {
  const [procs, setProcs] = useState([])
  const [grupos, setGrupos] = useState([])
  const [procId, setProcId] = useState('')
  const [sitio, setSitio] = useState('')
  const [quirofano, setQuirofano] = useState('Quirófano 3')
  const [pac, setPac] = useState({ grupo_sanguineo: '' })

  useEffect(() => {
    api.get('/procedimientos').then((r) => r.ok && setProcs(r.data.filter((p) => p.activo)))
    api.get('/catalogos').then((r) => r.ok && setGrupos(r.data.grupos_sanguineos))
  }, [])

  const proc = procs.find((p) => p.id === Number(procId))

  const elegir = (id) => {
    setProcId(id)
    const p = procs.find((x) => x.id === Number(id))
    setSitio(p?.sitio_sugerido || '')
  }

  const crear = async () => {
    const paciente = {}
    for (const [k, v] of Object.entries(pac)) {
      if (v === '' || v == null) continue
      paciente[k] = NUM.has(k) ? Number(String(v).replace(',', '.')) : v
    }
    const r = await ejecutar({
      url: '/cirugias',
      body: { tipo_procedimiento_id: Number(procId), paciente, sitio, quirofano },
      exito: () => 'Cirugía creada con sus insumos en 0',
    })
    if (r) onCreada(r.cirugia_id)
  }

  return (
    <Modal
      titulo="Nueva cirugía"
      onCerrar={onCerrar}
      ancho="max-w-3xl"
      pie={
        <>
          <Boton variante="secundario" onClick={onCerrar}>
            Cancelar
          </Boton>
          <Boton onClick={crear} disabled={!proc || !(pac.nombre || '').trim()}>
            Crear cirugía
          </Boton>
        </>
      }
    >
      <div className="grid gap-4 md:grid-cols-2">
        <Campo etiqueta="Tipo de procedimiento *">
          <select className={INPUT} value={procId} onChange={(e) => elegir(e.target.value)}>
            <option value="">Seleccione…</option>
            {procs.map((p) => (
              <option key={p.id} value={p.id}>
                {p.nombre}
              </option>
            ))}
          </select>
        </Campo>
        <Campo etiqueta="Sitio quirúrgico">
          <input className={INPUT} value={sitio} onChange={(e) => setSitio(e.target.value)} />
        </Campo>
        <Campo etiqueta="Quirófano">
          <input className={INPUT} value={quirofano} onChange={(e) => setQuirofano(e.target.value)} />
        </Campo>
        <Campo etiqueta="Grupo sanguíneo">
          <select className={INPUT} value={pac.grupo_sanguineo} onChange={(e) => setPac({ ...pac, grupo_sanguineo: e.target.value })}>
            <option value="">Sin registrar</option>
            {grupos.map((g) => (
              <option key={g}>{g}</option>
            ))}
          </select>
        </Campo>
      </div>

      {proc && (
        <div className="mt-4 rounded-lg border border-sky-200 bg-sky-50 p-3 text-sm">
          <div className="font-semibold text-sky-900">Insumos que se cargarán (cantidad inicial 0):</div>
          {proc.insumos.length ? (
            <ul className="mt-1 flex flex-wrap gap-1.5">
              {proc.insumos.map((i) => (
                <li key={i.id} className="rounded-full bg-white px-2.5 py-0.5 text-xs ring-1 ring-sky-200">
                  {i.nombre}
                  {i.cantidad_sugerida ? <span className="text-slate-400"> · sugerido {i.cantidad_sugerida}</span> : null}
                </li>
              ))}
            </ul>
          ) : (
            <p className="text-xs text-slate-500">Este procedimiento no tiene insumos asociados.</p>
          )}
          <p className="mt-1 text-xs text-slate-500">El instrumentador o el auxiliar registra la cantidad inicial real en el tablero.</p>
        </div>
      )}

      <h4 className="mt-5 mb-2 text-sm font-bold uppercase tracking-wide text-slate-600">Paciente</h4>
      <div className="grid gap-3 md:grid-cols-3">
        {CAMPOS.map(([k, etiqueta]) => (
          <Campo key={k} etiqueta={etiqueta}>
            <input
              className={INPUT}
              inputMode={NUM.has(k) ? 'decimal' : undefined}
              value={pac[k] ?? ''}
              onChange={(e) => setPac({ ...pac, [k]: e.target.value })}
            />
          </Campo>
        ))}
      </div>
    </Modal>
  )
}

import { useEffect, useState } from 'react'
import { api, hora, rolColor } from '../api'
import { ACCION_NOMBRE, CANAL_ESTILO, RESULTADO_ESTILO, describir } from '../traza'
import { Badge, Boton, Campo, Card, INPUT, Modal, SEVERIDAD, useDialogo } from './ui'

const SIN_ALERGIAS = /^(ninguna|niega|no conocidas?|ninguna conocida|no refiere)/i

// ------------------------------------------------------------------ paciente

const CAMPOS_FICHA = [
  ['nombre', 'Nombre', 'texto'],
  ['documento', 'Identificación', 'texto'],
  ['edad', 'Edad (años)', 'numero'],
  ['peso', 'Peso (kg)', 'numero'],
  ['talla', 'Talla (m)', 'numero'],
  ['grupo_sanguineo', 'Grupo sanguíneo', 'grupo'],
  ['alergias', 'Alergias', 'texto'],
  ['presion_arterial', 'Presión arterial (mmHg)', 'texto'],
  ['frecuencia_cardiaca', 'Frecuencia cardiaca (lpm)', 'numero'],
  ['saturacion_o2', 'Saturación O₂ (%)', 'numero'],
  ['temperatura', 'Temperatura (°C)', 'numero'],
  ['glucometria', 'Glucometría (mg/dL)', 'numero'],
  ['reserva_sangre', 'Reserva de sangre', 'texto'],
  ['info_clinica', 'Información clínica relevante', 'texto'],
]

function EditarFicha({ paciente, grupos, ejecutar, cirugiaId, onCerrar }) {
  const [v, setV] = useState(() => Object.fromEntries(CAMPOS_FICHA.map(([k]) => [k, paciente[k] ?? ''])))

  const guardar = async () => {
    const campos = {}
    for (const [k, , tipo] of CAMPOS_FICHA) {
      const nuevo = tipo === 'numero' && v[k] !== '' ? Number(String(v[k]).replace(',', '.')) : v[k] === '' ? null : v[k]
      if (tipo === 'numero' && nuevo !== null && Number.isNaN(nuevo)) continue
      if ((paciente[k] ?? null) !== nuevo) campos[k] = nuevo
    }
    if (!Object.keys(campos).length) return onCerrar()
    const r = await ejecutar({
      metodo: 'patch',
      url: `/cirugias/${cirugiaId}/paciente`,
      body: { campos },
      cambios: ['paciente'],
      exito: () => `Ficha actualizada (${Object.keys(campos).length} campo/s)`,
    })
    if (r) onCerrar()
  }

  return (
    <Modal
      titulo="Editar ficha del paciente"
      onCerrar={onCerrar}
      ancho="max-w-3xl"
      pie={
        <>
          <Boton variante="secundario" onClick={onCerrar}>
            Cancelar
          </Boton>
          <Boton onClick={guardar}>Guardar cambios</Boton>
        </>
      }
    >
      <div className="grid gap-3 md:grid-cols-3">
        {CAMPOS_FICHA.map(([k, etiqueta, tipo]) => (
          <Campo key={k} etiqueta={etiqueta} className={k === 'info_clinica' || k === 'alergias' ? 'md:col-span-3' : ''}>
            {tipo === 'grupo' ? (
              <select className={INPUT} value={v[k]} onChange={(e) => setV({ ...v, [k]: e.target.value })}>
                <option value="">Sin registrar</option>
                {grupos.map((g) => (
                  <option key={g}>{g}</option>
                ))}
              </select>
            ) : (
              <input
                className={INPUT}
                inputMode={tipo === 'numero' ? 'decimal' : undefined}
                value={v[k]}
                onChange={(e) => setV({ ...v, [k]: e.target.value })}
              />
            )}
          </Campo>
        ))}
      </div>
      <p className="mt-3 text-xs text-slate-500">Cada cambio queda en la trazabilidad con el valor anterior y el nuevo.</p>
    </Modal>
  )
}

function Vital({ etiqueta, valor, unidad, falta }) {
  return (
    <div className={`rounded-lg border px-3 py-2 ${falta ? 'border-amber-400 bg-amber-50' : 'border-slate-200 bg-slate-50'}`}>
      <div className="text-[11px] font-semibold uppercase tracking-wide text-slate-500">{etiqueta}</div>
      <div className={`text-xl font-bold ${falta ? 'text-amber-700' : 'text-slate-900'}`}>
        {valor ?? (falta ? 'Falta' : '—')}
        {valor != null && unidad && <span className="ml-1 text-xs font-medium text-slate-500">{unidad}</span>}
      </div>
    </div>
  )
}

function Paciente({ estado, ejecutar, resaltar, catalogos, operativo }) {
  const [editar, setEditar] = useState(false)
  const { paciente: p, cirugia: c, equipo } = estado
  const faltan = new Set(p.faltantes)
  const alergico = p.alergias && !SIN_ALERGIAS.test(p.alergias.trim())
  const activas = estado.anestesias.filter((a) => a.estado === 'activo')

  return (
    <Card id="sec-paciente" resaltar={resaltar.has('paciente')} className="col-span-12">
      <div className="grid gap-4 lg:grid-cols-12">
        <div className="lg:col-span-5">
          <div className="text-xs font-semibold uppercase tracking-wide text-slate-500">
            {c.quirofano} · Paciente · {c.estado.replace('_', ' ')}
          </div>
          <div className="text-3xl font-bold leading-tight">{p.nombre}</div>
          <div className="mt-1 flex flex-wrap gap-x-4 text-sm text-slate-700">
            <span>{p.documento || <b className="text-amber-700">ID sin registrar</b>}</span>
            <span>{p.edad != null ? `${p.edad} años` : <b className="text-amber-700">Edad sin registrar</b>}</span>
            <span>{p.peso != null ? `${p.peso} kg` : <b className="text-amber-700">Peso sin registrar</b>}</span>
            <span>{p.talla != null ? `${p.talla} m` : '—'}</span>
          </div>
          <div className="mt-3 rounded-lg bg-slate-900 px-4 py-3 text-white">
            <div className="text-[11px] font-semibold uppercase tracking-wide text-slate-400">Procedimiento</div>
            <div className="text-lg font-bold">{c.procedimiento_programado}</div>
            <div className="text-sm text-slate-300">Sitio: {c.sitio_programado}</div>
            {activas.length > 0 && (
              <div className="mt-1 text-sm text-slate-300">Anestesia: {activas.map((a) => a.tipo).join(' + ')}</div>
            )}
