              <div className="text-xs font-bold uppercase tracking-widest text-slate-500">Grupo sanguíneo</div>
              <div className={`text-4xl font-black ${p.grupo_sanguineo ? 'text-red-700' : 'text-amber-700'}`}>{p.grupo_sanguineo || 'Falta'}</div>
            </div>
            <div className="flex-1 rounded-xl border border-slate-200 bg-white px-4 py-2">
              <div className="text-xs font-bold uppercase tracking-widest text-slate-500">Reserva</div>
              <div className="text-base font-semibold">{p.reserva_sangre || '—'}</div>
            </div>
          </div>
        </div>

        <div className="lg:col-span-3">
          <div className="grid grid-cols-2 gap-2">
            <Vital etiqueta="PA" valor={p.presion_arterial} unidad="mmHg" />
            <Vital etiqueta="FC" valor={p.frecuencia_cardiaca} unidad="lpm" />
            <Vital etiqueta="SpO₂" valor={p.saturacion_o2} unidad="%" />
            <Vital etiqueta="Temp." valor={p.temperatura} unidad="°C" />
            <Vital etiqueta="Glucometría" valor={p.glucometria} unidad="mg/dL" />
            <Vital etiqueta="Peso" valor={p.peso} unidad="kg" falta={faltan.has('peso')} />
          </div>
          {operativo && c.estado !== 'finalizada' && (
            <Boton variante="secundario" className="mt-2 w-full" onClick={() => setEditar(true)}>
              Editar ficha del paciente
            </Boton>
          )}
        </div>
      </div>

      {p.faltantes.length > 0 && (
        <div className="mt-3 rounded-lg border border-amber-400 bg-amber-50 px-3 py-2 text-sm font-semibold text-amber-900">
          Datos obligatorios faltantes: {p.faltantes.join(', ').replace('grupo_sanguineo', 'grupo sanguíneo')}
        </div>
      )}

      <div className="mt-3 flex flex-wrap items-center gap-x-4 gap-y-1 border-t border-slate-100 pt-2 text-sm">
        <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">Equipo</span>
        {equipo.map((m) => (
          <span key={m.usuario_id} className="flex items-center gap-1.5">
            {m.nombre}
            <Badge className={rolColor(m.rol)}>{m.rol_nombre}</Badge>
          </span>
        ))}
      </div>

      {editar && (
        <EditarFicha paciente={p} grupos={catalogos.grupos_sanguineos || []} ejecutar={ejecutar} cirugiaId={c.id} onCerrar={() => setEditar(false)} />
      )}
    </Card>
  )
}

// --------------------------------------------------------------------- hitos

function Hitos({ estado, ejecutar, resaltar, operativo }) {
  const pedir = useDialogo()
  const siguiente = estado.hitos.find((h) => !h.hora)
  const finalizada = estado.cirugia.estado === 'finalizada'
  const d = estado.duraciones

  const registrar = async (h) => {
    const ok = await pedir({ titulo: 'Registrar hito', mensaje: `¿Registrar «${h.nombre}» ahora?` })
    if (!ok) return
    ejecutar({
      url: `/cirugias/${estado.cirugia.id}/eventos`,
      body: { hito: h.codigo },
      cambios: ['hitos'],
      exito: () => `${h.nombre} registrado`,
    })
  }

  return (
    <Card
      titulo="Tiempos quirúrgicos"
      resaltar={resaltar.has('hitos')}
      className="col-span-12"
      extra={
        <div className="flex gap-3 text-xs text-slate-500">
          {d.preparacion_min != null && <span>Preparación → ingreso: {d.preparacion_min} min</span>}
          {d.anestesia_a_incision_min != null && <span>Anestesia → incisión: {d.anestesia_a_incision_min} min</span>}
          {d.cirugia_min != null && <span>Cirugía: {d.cirugia_min} min</span>}
          {d.en_quirofano_min != null && <span>En quirófano: {d.en_quirofano_min} min</span>}
        </div>
      }
    >
      <ol className="grid grid-cols-3 gap-2 md:grid-cols-5 xl:grid-cols-9">
        {estado.hitos.map((h, i) => {
          const hecho = !!h.hora
          const esSiguiente = siguiente?.codigo === h.codigo && !finalizada
          return (
            <li
              key={h.codigo}
              className={`relative rounded-lg border p-2.5 ${
                hecho ? 'border-emerald-300 bg-emerald-50' : esSiguiente ? 'border-sky-400 bg-sky-50 ring-2 ring-sky-200' : 'border-slate-200'
              }`}
            >
              <div className="flex items-start gap-1.5">
                <span
                  className={`flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-xs font-bold ${
                    hecho ? 'bg-emerald-600 text-white' : 'bg-slate-200 text-slate-600'
                  }`}
                >
                  {hecho ? '✓' : i + 1}
                </span>
                <span className="text-xs font-semibold leading-tight">{h.nombre}</span>
              </div>
              <div className={`mt-1.5 font-mono text-lg ${hecho ? 'text-emerald-800' : 'text-slate-300'}`}>{hora(h.hora)}</div>
              {h.automatico && !hecho && <div className="text-[10px] text-slate-500">Automático (checklist)</div>}
              {h.automatico && hecho && <div className="text-[10px] text-emerald-700">Automático</div>}
              {esSiguiente && !h.automatico && operativo && (
                <Boton className="mt-1 w-full !px-2 !py-1 !text-xs" onClick={() => registrar(h)}>
                  Registrar
                </Boton>
              )}
            </li>
          )
        })}
      </ol>
    </Card>
  )
}

// ----------------------------------------------------------------- checklist

function ItemChecklist({ it, habilitado, operativo, onVerificar, resaltado, motivo }) {
  const ok = it.estado === 'verificado'
  return (
    <li className={`flex items-center gap-3 rounded px-2 py-2.5 ${resaltado ? 'resaltado' : ''}`}>
      <span
        className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-full border-2 text-sm font-bold ${
          ok ? 'border-emerald-600 bg-emerald-600 text-white' : 'border-slate-300 text-transparent'
        }`}
      >
        ✓
      </span>
      <div className="min-w-0 flex-1">
        <div className="flex flex-wrap items-center gap-1.5">
          <span className={`font-medium ${ok ? 'text-slate-500' : ''}`}>{it.descripcion}</span>
          {it.tipo === 'equipo' && <Badge className="bg-slate-100 text-slate-600">Equipo</Badge>}
          {it.tipo === 'recuento' && <Badge className="bg-orange-100 text-orange-700">Recuento</Badge>}
          {it.tipo === 'insumos' && <Badge className="bg-sky-100 text-sky-700">Requiere cantidades iniciales</Badge>}
          {it.tipo === 'drenes' && <Badge className="bg-violet-100 text-violet-700">Desde registro de drenes</Badge>}
          {!it.obligatorio && <Badge className="bg-slate-100 text-slate-500">Opcional</Badge>}
        </div>
        <div className="mt-0.5 text-xs text-slate-500">
          {ok ? (
            <>
              <span className="font-medium text-emerald-700">{it.verificado_por_nombre}</span> · {hora(it.verificado_en)} · {it.resultado}
            </>
          ) : (
            <>
              Referencia: {it.rol_responsable_nombre}
              {motivo ? <span className="text-amber-700"> · {motivo}</span> : null}
            </>
          )}
        </div>
      </div>
      {!ok && operativo && it.tipo !== 'drenes' && (
        <Boton variante={habilitado ? 'primario' : 'secundario'} disabled={!habilitado} onClick={() => onVerificar(it)}>
          Verificar
        </Boton>
      )}
    </li>
  )
}

function Checklist({ estado, usuario, ejecutar, resaltar, refs, operativo }) {
  const pedir = useDialogo()
  const { cirugia: c, fases } = estado
  const [ver, setVer] = useState(Math.min(Math.max(c.fase_actual, 1), 3))

  useEffect(() => {
    setVer(Math.min(Math.max(c.fase_actual, 1), 3))
  }, [c.fase_actual])

  useEffect(() => {
    if (refs.item_id) {
      const f = fases.find((x) => x.items.some((i) => i.id === refs.item_id))
      if (f) setVer(f.numero)
    }
  }, [refs, fases])

  const fase = fases.find((f) => f.numero === ver)
  const cerrable = fase.estado === 'en_curso' && c.estado !== 'finalizada'

  const verificar = async (it) => {
    const resultado = await pedir({
      titulo: 'Verificar ítem',
      mensaje: `«${it.descripcion}» quedará registrado a nombre de ${usuario.nombre} (${usuario.rol_nombre}).`,
      campo: 'Resultado',
      valorInicial: 'Conforme',
    })
    if (resultado === null) return
    ejecutar({
      url: `/cirugias/${c.id}/checklist/${it.id}/verificar`,
      body: { resultado },
      cambios: ['checklist', 'fases', 'hitos'],
      refs: { item_id: it.id },
      exito: (d) => `Verificado: ${it.descripcion}${d.hito_automatico ? ' · hito automático registrado' : ''}`,
    })
  }

  const cerrar = async () => {
    const ok = await pedir({
      titulo: `Cerrar fase ${fase.numero}`,
      mensaje: `¿Cerrar «${fase.nombre}»? Se validará que no haya verificaciones obligatorias pendientes.`,
    })
    if (!ok) return
    ejecutar({
      url: `/cirugias/${c.id}/fases/${fase.numero}/cerrar`,
      body: {},
      cambios: ['fases', 'checklist'],
      exito: () => `Fase ${fase.numero} cerrada`,
    })
  }

  const enFase = fase.numero <= c.fase_actual && c.estado !== 'finalizada'
  const itemsPorId = Object.fromEntries(fase.items.map((i) => [i.id, i]))
  const resaltado = (it) => refs.item_id === it.id && resaltar.size > 0

  return (
    <Card id="sec-checklist" titulo="Checklist de seguridad quirúrgica" resaltar={resaltar.has('checklist') || resaltar.has('fases')}>
      <div className="mb-4 grid grid-cols-3 gap-2">
        {fases.map((f) => {
          const pct = f.total ? Math.round((100 * f.verificados) / f.total) : 0
          const estilo =
            f.estado === 'cerrada' ? 'border-emerald-400 bg-emerald-50' : f.estado === 'en_curso' ? 'border-sky-500 bg-sky-50' : 'border-slate-200 bg-slate-50 opacity-70'
          return (
            <button
              key={f.numero}
              onClick={() => setVer(f.numero)}
              className={`rounded-lg border-2 p-2.5 text-left transition ${estilo} ${ver === f.numero ? 'ring-2 ring-slate-800' : ''}`}
            >
              <div className="flex items-center justify-between">
                <span className="text-xs font-semibold uppercase text-slate-500">Fase {f.numero}</span>
                <span className={`text-xs font-bold ${f.estado === 'en_curso' ? 'text-sky-700' : ''}`}>
                  {f.estado === 'cerrada' ? 'Cerrada' : f.estado === 'en_curso' ? '● En curso' : 'Pendiente'}
                </span>
              </div>
              <div className="text-sm font-semibold">{f.nombre}</div>
              <div className="mt-1.5 h-1.5 overflow-hidden rounded bg-slate-200">
                <div className={`h-full ${f.estado === 'cerrada' ? 'bg-emerald-500' : 'bg-sky-500'}`} style={{ width: `${pct}%` }} />
              </div>
              <div className="mt-1 text-xs text-slate-500">
                {f.verificados}/{f.total} obligatorios
              </div>
            </button>
          )
        })}
      </div>

      {fase.numero === 1 ? (
        <div className="space-y-3">
          {fase.bloques.map((b, n) => (
            <div key={b.codigo} className={`rounded-lg border ${b.completado ? 'border-emerald-200' : b.habilitado ? 'border-sky-200' : 'border-slate-200 bg-slate-50'}`}>
              <div className="flex items-center justify-between gap-2 border-b border-slate-100 px-3 py-2">
                <div className="text-sm font-bold">
                  1.{n + 1} · {b.nombre}
                </div>
                {b.completado ? (
                  <Badge className="bg-emerald-100 text-emerald-800">Completado · {hora(estado.hitos.find((h) => h.codigo === b.hito)?.hora)}</Badge>
                ) : b.habilitado ? (
                  <Badge className="bg-sky-100 text-sky-800">En curso</Badge>
                ) : (
                  <Badge className="bg-slate-200 text-slate-600">🔒 Después de: {b.requisito}</Badge>
                )}
              </div>
              <ul className="divide-y divide-slate-100 px-1">
                {b.items.map((id) => {
                  const it = itemsPorId[id]
                  return (
                    <ItemChecklist
                      key={id}
                      it={it}
                      operativo={operativo}
                      habilitado={enFase && b.habilitado}
                      motivo={!b.habilitado ? `Disponible después de «${b.requisito}»` : null}
                      onVerificar={verificar}
                      resaltado={resaltado(it)}
                    />
                  )
                })}
              </ul>
            </div>
          ))}
          <p className="text-xs text-slate-500">
            Al completar cada bloque se registra automáticamente su hito. «Ingreso del paciente» e «Inicio de anestesia» se registran en Tiempos
            quirúrgicos o por voz. La fase 1 se cierra después del inicio de anestesia.
          </p>
        </div>
      ) : (
        <>
          {fase.numero === 3 && !fase.habilitado && (
            <p className="mb-2 rounded bg-slate-100 px-3 py-2 text-sm text-slate-600">Las verificaciones de la fase 3 se habilitan con el inicio de la cirugía.</p>
          )}
          <ul className="divide-y divide-slate-100">
            {fase.items.map((it) => (
              <ItemChecklist
                key={it.id}
                it={it}
                operativo={operativo}
                habilitado={enFase && (fase.numero !== 3 || fase.habilitado)}
                onVerificar={verificar}
                resaltado={resaltado(it)}
              />
            ))}
          </ul>
        </>
      )}

      {cerrable && operativo && (
        <div className="mt-4 flex items-center justify-between border-t border-slate-100 pt-3">
          <span className="text-sm text-slate-500">
            {fase.verificados < fase.total ? `Faltan ${fase.total - fase.verificados} verificaciones obligatorias` : 'Todas las verificaciones obligatorias completas'}
          </span>
          <Boton variante={fase.verificados < fase.total ? 'secundario' : 'exito'} onClick={cerrar}>
            Cerrar fase {fase.numero}
          </Boton>
        </div>
      )}
    </Card>
  )
}

// ------------------------------------------------------------------- insumos

function FilaInsumo({ ins, cid, ejecutar, puede, resaltado }) {
  const pedir = useDialogo()
  const [inicial, setInicial] = useState('')
  const agotado = ins.inicial_registrada && ins.cantidad_disponible === 0
  const preventivo = ins.inicial_registrada && !agotado && ins.cantidad_disponible <= ins.umbral_preventivo
  const pct = ins.cantidad_inicial ? (100 * ins.cantidad_disponible) / ins.cantidad_inicial : 0

  const registrarInicial = async (cantidad) => {
    const n = parseInt(cantidad, 10)
    if (!(n >= 0)) return
    const r = await ejecutar({
      metodo: 'put',
      url: `/cirugias/${cid}/insumos/${ins.id}/inicial`,
      body: { cantidad: n },
      cambios: ['insumos'],
      refs: { insumo_id: ins.id },
      exito: () => `Cantidad inicial de ${ins.nombre.toLowerCase()}: ${n}`,
    })
    if (r) setInicial('')
  }

  const corregir = async () => {
    const v = await pedir({
      titulo: `Corregir cantidad inicial · ${ins.nombre}`,
      mensaje: `Valor actual: ${ins.cantidad_inicial}. Ya utilizado: ${ins.cantidad_utilizada}. La corrección queda en trazabilidad.`,
      campo: 'Nueva cantidad inicial',
      valorInicial: String(ins.cantidad_inicial),
    })
    if (v !== null && v !== '') registrarInicial(v)
  }

  const consumir = async (cantidad) => {
    if (cantidad == null) {
      const v = await pedir({ titulo: `Consumo de ${ins.nombre.toLowerCase()}`, campo: 'Cantidad', valorInicial: '1' })
      if (!v) return
      cantidad = parseInt(v, 10)
      if (!(cantidad > 0)) return
    }
    ejecutar({
      url: `/cirugias/${cid}/consumos`,
      body: { insumo_id: ins.id, cantidad },
      cambios: ['insumos'],
      refs: { insumo_id: ins.id },
      exito: (d) => `Consumo: ${cantidad} ${ins.nombre.toLowerCase()}. Disponible ${d.restante}`,
    })
  }

  return (
    <tr className={`${agotado ? 'bg-red-50' : preventivo ? 'bg-amber-50' : ''} ${resaltado ? 'resaltado' : ''}`}>
      <td className="py-2 pr-2">
        <div className="font-semibold">{ins.nombre}</div>
        <div className="text-[11px] text-slate-500">
          {ins.unidad} · umbral {ins.umbral_preventivo}
          {ins.inicial_registrada && ` · inicial por ${ins.inicial_registrada_por_nombre} ${hora(ins.inicial_registrada_en)}`}
        </div>
      </td>
      {ins.inicial_registrada ? (
        <>
          <td className="py-2 text-center font-mono text-base">{ins.cantidad_inicial}</td>
          <td className="py-2 text-center font-mono text-base">{ins.cantidad_utilizada}</td>
          <td className="py-2 text-center">
            <span className={`font-mono text-2xl font-black ${agotado ? 'text-red-700' : preventivo ? 'text-amber-700' : 'text-emerald-700'}`}>
              {ins.cantidad_disponible}
            </span>
            <div className="mx-auto mt-0.5 h-1.5 w-16 overflow-hidden rounded bg-slate-200">
              <div className={`h-full ${agotado ? 'bg-red-600' : preventivo ? 'bg-amber-500' : 'bg-emerald-500'}`} style={{ width: `${pct}%` }} />
            </div>
            {agotado && <Badge className="mt-1 bg-red-700 text-white">AGOTADO</Badge>}
            {preventivo && <Badge className="mt-1 bg-amber-400 text-amber-950">Por agotarse</Badge>}
          </td>
          <td className="py-2 text-right whitespace-nowrap">
            {puede && (
              <>
                <Boton variante="secundario" disabled={agotado} onClick={() => consumir(1)}>
                  −1
                </Boton>{' '}
                <Boton variante="fantasma" disabled={agotado} onClick={() => consumir(null)}>
                  Otro…
                </Boton>
                <button onClick={corregir} className="ml-1 text-xs text-slate-400 hover:text-slate-700" title="Corregir cantidad inicial">
                  ✎
                </button>
              </>
            )}
          </td>
        </>
      ) : (
        <td colSpan={4} className="py-2">
          {puede ? (
            <form
              className="flex items-center justify-end gap-2"
              onSubmit={(e) => {
                e.preventDefault()
                registrarInicial(inicial)
              }}
            >
              <span className="text-xs font-semibold text-amber-700">Cantidad inicial:</span>
              <input
                value={inicial}
                onChange={(e) => setInicial(e.target.value.replace(/\D/g, ''))}
                inputMode="numeric"
                placeholder="0"
                className="w-20 rounded-lg border-2 border-amber-400 px-2 py-1 text-right font-mono text-base outline-none focus:border-sky-500"
              />
              <Boton type="submit" disabled={inicial === ''}>
                Registrar
              </Boton>
            </form>
          ) : (
            <span className="text-xs text-amber-700">Cantidad inicial sin registrar</span>
          )}
        </td>
      )}
    </tr>
  )
}

function Insumos({ estado, ejecutar, resaltar, refs, operativo, catalogoInsumos }) {
  const cid = estado.cirugia.id
  const puede = operativo && estado.cirugia.estado !== 'finalizada'
  const [agregar, setAgregar] = useState('')
  const presentes = new Set(estado.insumos.map((i) => i.catalogo_id))
  const disponibles = catalogoInsumos.filter((c) => c.activo && !presentes.has(c.id))
  const sinInicial = estado.insumos.filter((i) => !i.inicial_registrada).length

  const tot = estado.insumos.reduce(
    (a, i) => ({ ini: a.ini + i.cantidad_inicial, uso: a.uso + i.cantidad_utilizada, disp: a.disp + i.cantidad_disponible }),
    { ini: 0, uso: 0, disp: 0 },
  )

  const agregarInsumo = async () => {
    if (!agregar) return
    const r = await ejecutar({
      url: `/cirugias/${cid}/insumos`,
      body: { catalogo_id: Number(agregar) },
      cambios: ['insumos'],
      exito: () => 'Insumo agregado con cantidad 0',
    })
    if (r) setAgregar('')
  }

  return (
    <Card
      id="sec-insumos"
      titulo="Insumos de la cirugía"
      resaltar={resaltar.has('insumos')}
      extra={
        <div className="flex gap-3 font-mono text-xs">
          <span>Inicial {tot.ini}</span>
          <span>Utilizado {tot.uso}</span>
          <span className="font-bold text-emerald-700">Disponible {tot.disp}</span>
        </div>
      }
    >
      {sinInicial > 0 && (
        <div className="mb-3 rounded-lg border border-amber-400 bg-amber-50 px-3 py-2 text-sm font-medium text-amber-900">
          {sinInicial} insumo(s) sin cantidad inicial. Todos inician en 0: registre la cantidad real con la que inicia esta cirugía.
        </div>
      )}
      <table className="w-full text-sm">
        <thead>
          <tr className="text-xs uppercase tracking-wide text-slate-500">
            <th className="pb-2 text-left font-semibold">Insumo</th>
            <th className="pb-2 font-semibold">Inicial</th>
            <th className="pb-2 font-semibold">Utilizado</th>
            <th className="pb-2 font-semibold">Disponible</th>
            <th className="pb-2" />
          </tr>
        </thead>
        <tbody className="divide-y divide-slate-100">
          {estado.insumos.map((ins) => (
            <FilaInsumo key={ins.id} ins={ins} cid={cid} ejecutar={ejecutar} puede={puede} resaltado={refs.insumo_id === ins.id && resaltar.size > 0} />
          ))}
        </tbody>
      </table>
      {puede && disponibles.length > 0 && (
        <div className="mt-3 flex items-center gap-2 border-t border-slate-100 pt-3">
          <select className={`${INPUT} max-w-xs`} value={agregar} onChange={(e) => setAgregar(e.target.value)}>
            <option value="">Agregar insumo del catálogo…</option>
            {disponibles.map((c) => (
              <option key={c.id} value={c.id}>
                {c.nombre}
              </option>
            ))}
          </select>
          <Boton variante="secundario" disabled={!agregar} onClick={agregarInsumo}>
            Agregar
          </Boton>
        </div>
      )}
      {!operativo && <p className="mt-2 text-xs text-slate-400">Su tipo de persona solo puede consultar.</p>}
    </Card>
  )
}

// ----------------------------------------------------------------- anestesia

function Anestesia({ estado, ejecutar, resaltar, operativo, catalogos }) {
  const pedir = useDialogo()
  const c = estado.cirugia
  const [tipo, setTipo] = useState('')
  const [obs, setObs] = useState('')
  const puede = operativo && c.estado !== 'finalizada'
  const activos = new Set(estado.anestesias.filter((a) => a.estado === 'activo').map((a) => a.tipo))

  const agregar = async (e) => {
    e.preventDefault()
    if (!tipo) return
    const r = await ejecutar({
      url: `/cirugias/${c.id}/anestesias`,
      body: { tipo, observaciones: obs || null },
      cambios: ['anestesia'],
      exito: () => `Anestesia ${tipo.toLowerCase()} registrada`,
    })
    if (r) {
      setTipo('')
      setObs('')
    }
  }

  const anular = async (a) => {
    const motivo = await pedir({ titulo: `Anular anestesia ${a.tipo}`, campo: 'Motivo (obligatorio)', requerido: true, confirmar: 'Anular', peligro: true })
    if (!motivo) return
    ejecutar({ metodo: 'patch', url: `/anestesias/${a.id}/anular`, body: { motivo }, cambios: ['anestesia'], exito: () => 'Registro anulado' })
  }

  return (
    <Card titulo="Anestesia" resaltar={resaltar.has('anestesia')}>
      <div className="mb-3 flex items-center justify-between rounded-lg bg-slate-50 px-3 py-2">
        <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">Inicio de anestesia</span>
        <span className={`font-mono text-xl font-bold ${c.t_inicio_anestesia ? 'text-emerald-700' : 'text-slate-300'}`}>{hora(c.t_inicio_anestesia)}</span>
      </div>
      {estado.anestesias.length === 0 ? (
        <p className="text-sm text-slate-400">Sin tipos de anestesia registrados.</p>
      ) : (
        <ul className="space-y-1.5">
          {estado.anestesias.map((a) => (
            <li key={a.id} className={`flex items-center justify-between rounded-lg border px-3 py-2 text-sm ${a.estado === 'anulado' ? 'border-slate-200 text-slate-400 line-through' : 'border-emerald-200 bg-emerald-50'}`}>
              <div>
                <span className="font-semibold">{a.tipo}</span>
                <span className="ml-2 text-xs">
                  {a.registrado_por_nombre} · {hora(a.ts)}
                  {a.observaciones ? ` · ${a.observaciones}` : ''}
                </span>
              </div>
              {a.estado === 'activo' && puede && (
                <button onClick={() => anular(a)} className="text-xs text-red-600 hover:underline">
                  Anular
                </button>
              )}
            </li>
          ))}
        </ul>
      )}
      {puede && (
        <form onSubmit={agregar} className="mt-3 flex flex-wrap gap-2">
          <select className={`${INPUT} flex-1`} value={tipo} onChange={(e) => setTipo(e.target.value)}>
            <option value="">Tipo de anestesia…</option>
            {(catalogos.tipos_anestesia || []).map((t) => (
              <option key={t} disabled={activos.has(t)}>
                {t}
              </option>
            ))}
          </select>
          <input className={`${INPUT} flex-1`} placeholder="Observaciones (opcional)" value={obs} onChange={(e) => setObs(e.target.value)} />
          <Boton type="submit" disabled={!tipo}>
            Agregar
          </Boton>
        </form>
      )}
    </Card>
  )
}

// -------------------------------------------------------------------- drenes

function Drenes({ estado, ejecutar, resaltar, operativo, catalogos }) {
  const pedir = useDialogo()
  const c = estado.cirugia
  const [f, setF] = useState({ tipo: '', cantidad: '1', observaciones: '' })
  const puede = operativo && c.estado !== 'finalizada'
  const habilitado = !!c.t_inicio_cirugia

  const registrar = async (e) => {
    e.preventDefault()
    const r = await ejecutar({
      url: `/cirugias/${c.id}/drenes`,
      body: { tipo: f.tipo || null, cantidad: parseInt(f.cantidad, 10) || 1, observaciones: f.observaciones || null },
      cambios: ['drenes', 'checklist'],
      exito: (d) => `Dren #${d.dren.numero} registrado`,
    })
    if (r) setF({ tipo: '', cantidad: '1', observaciones: '' })
  }

  const sinDrenes = async () => {
    const ok = await pedir({ titulo: 'Sin drenes', mensaje: '¿Confirma que el paciente sale sin drenes?' })
    if (ok) ejecutar({ url: `/cirugias/${c.id}/sin-drenes`, body: {}, cambios: ['drenes', 'checklist'], exito: () => 'Registrado: sin drenes' })
  }

  return (
    <Card titulo="Drenes" resaltar={resaltar.has('drenes')}>
      <div className="mb-2 text-sm">
        Presencia de drenes:{' '}
        <b>{c.drenes_presentes === true ? 'Sí' : c.drenes_presentes === false ? 'No (sin drenes)' : 'Sin registrar'}</b>
      </div>
      {estado.drenes.length > 0 && (
        <ul className="mb-2 space-y-1.5">
          {estado.drenes.map((d) => (
            <li key={d.id} className="rounded-lg border border-violet-200 bg-violet-50 px-3 py-2 text-sm">
              <span className="font-semibold">#{d.numero} · {d.tipo || 'Tipo sin especificar'}</span> × {d.cantidad}
              <div className="text-xs text-slate-500">
                {d.registrado_por_nombre} · {hora(d.ts)}
                {d.observaciones ? ` · ${d.observaciones}` : ''}
              </div>
            </li>
          ))}
        </ul>
      )}
      {!habilitado ? (
        <p className="text-sm text-slate-400">Los drenes se registran después del inicio de la cirugía.</p>
      ) : (
        puede && (
          <form onSubmit={registrar} className="grid grid-cols-6 gap-2">
            <select className={`${INPUT} col-span-3`} value={f.tipo} onChange={(e) => setF({ ...f, tipo: e.target.value })}>
              <option value="">Tipo de dren…</option>
              {(catalogos.tipos_dren || []).map((t) => (
                <option key={t}>{t}</option>
              ))}
            </select>
            <input className={`${INPUT} col-span-1`} inputMode="numeric" value={f.cantidad} onChange={(e) => setF({ ...f, cantidad: e.target.value.replace(/\D/g, '') })} title="Cantidad" />
            <Boton type="submit" className="col-span-2">
              Registrar dren
            </Boton>
            <input className={`${INPUT} col-span-6`} placeholder="Observaciones (ubicación, características…)" value={f.observaciones} onChange={(e) => setF({ ...f, observaciones: e.target.value })} />
            {estado.drenes.length === 0 && c.drenes_presentes !== false && (
              <Boton type="button" variante="secundario" className="col-span-6" onClick={sinDrenes}>
                El paciente sale sin drenes
              </Boton>
            )}
          </form>
        )
      )}
    </Card>
  )
}

// ----------------------------------------------------------------- novedades

function Novedades({ estado, ejecutar, resaltar, refs, operativo }) {
  const pedir = useDialogo()
  const [desc, setDesc] = useState('')
  const [sev, setSev] = useState('media')
  const cid = estado.cirugia.id
  const puede = operativo && estado.cirugia.estado !== 'finalizada'

  const registrar = async (e) => {
    e.preventDefault()
    if (desc.trim().length < 3) return
    const r = await ejecutar({
      url: `/cirugias/${cid}/novedades`,
      body: { descripcion: desc, severidad: sev },
      cambios: ['novedades'],
      exito: (d) => `Novedad #${d.novedad.numero} registrada`,
    })
    if (r) setDesc('')
  }

  const resolver = async (n) => {
    const accion = await pedir({ titulo: `Resolver novedad #${n.numero}`, mensaje: n.descripcion, campo: 'Acción correctiva', requerido: true, placeholder: 'Ej.: se cambió el cable' })
    if (!accion) return
    ejecutar({
      metodo: 'patch',
      url: `/novedades/${n.id}/resolver`,
      body: { accion_correctiva: accion },
      cambios: ['novedades'],
      refs: { novedad_id: n.id },
      exito: () => `Novedad #${n.numero} resuelta`,
    })
  }

  return (
    <Card id="sec-novedades" titulo="Novedades" resaltar={resaltar.has('novedades')}>
      {puede && (
        <form onSubmit={registrar} className="mb-3 flex gap-2">
          <input value={desc} onChange={(e) => setDesc(e.target.value)} placeholder="Describa la novedad (ej.: falla en el cable de la cámara)" className={`${INPUT} flex-1`} />
          <select value={sev} onChange={(e) => setSev(e.target.value)} className="rounded-lg border border-slate-300 px-2 text-sm">
            <option value="baja">Baja</option>
            <option value="media">Media</option>
            <option value="alta">Alta</option>
          </select>
          <Boton type="submit" disabled={desc.trim().length < 3}>
            Registrar
          </Boton>
        </form>
      )}
      {estado.novedades.length === 0 ? (
        <p className="text-sm text-slate-400">Sin novedades registradas.</p>
      ) : (
        <ul className="space-y-2">
          {estado.novedades.map((n) => (
            <li
              key={n.id}
              className={`rounded-lg border p-2.5 text-sm ${n.estado === 'abierta' ? SEVERIDAD[n.severidad].borde : 'border-slate-200 bg-slate-50'} ${
                refs.novedad_id === n.id && resaltar.size ? 'resaltado' : ''
              }`}
            >
              <div className="flex items-start justify-between gap-2">
                <div>
                  <span className="font-semibold">#{n.numero}</span> {n.descripcion}
                  <div className="mt-0.5 text-xs text-slate-500">
                    {n.categoria} · {n.registrada_por_nombre} · {hora(n.ts)}
                  </div>
                  {n.estado === 'resuelta' && (
                    <div className="mt-1 text-xs text-emerald-700">
                      Resuelta por {n.resuelta_por_nombre} a las {hora(n.ts_resolucion)}: {n.accion_correctiva}
                    </div>
                  )}
                </div>
                {n.estado === 'abierta' ? (
                  puede && (
                    <Boton variante="secundario" onClick={() => resolver(n)}>
                      Resolver
                    </Boton>
                  )
                ) : (
                  <Badge className="bg-emerald-100 text-emerald-800">Resuelta</Badge>
                )}
              </div>
            </li>
          ))}
        </ul>
      )}
    </Card>
  )
}

// ------------------------------------------------------------------- alertas

const ORDEN_SEV = { alta: 0, media: 1, baja: 2 }

function Alertas({ estado, resaltar }) {
  const alertas = [...estado.alertas].sort((a, b) => ORDEN_SEV[a.severidad] - ORDEN_SEV[b.severidad])
  const criticas = alertas.filter((a) => a.severidad === 'alta').length
  return (
    <Card
      titulo="Alertas activas"
      resaltar={resaltar.has('alertas')}
      extra={
        <Badge className={`!text-sm ${alertas.length ? (criticas ? 'bg-red-700 text-white' : 'bg-amber-400 text-amber-950') : 'bg-emerald-100 text-emerald-800'}`}>
          {alertas.length}
        </Badge>
      }
    >
      {alertas.length === 0 ? (
        <p className="text-base font-semibold text-emerald-700">✓ Sin alertas activas.</p>
      ) : (
        <ul className="space-y-2.5">
          {alertas.map((a) => (
            <li key={a.id} className={`rounded-lg border-l-8 p-3 shadow-sm ${SEVERIDAD[a.severidad].tarjeta}`}>
              <div className="flex flex-wrap items-center gap-2">
                <Badge className={`!text-xs font-bold uppercase ${SEVERIDAD[a.severidad].chip}`}>
                  {SEVERIDAD[a.severidad].texto} · {a.regla}
                </Badge>
                <span className="text-xs opacity-70">desde {hora(a.creada_en)}</span>
                {a.reconocida_en && <span className="text-xs opacity-70">· vista por {a.reconocida_por_nombre}</span>}
              </div>
              <div className="mt-1 text-base font-bold leading-snug">{a.mensaje}</div>
              {a.accion_requerida && <div className="mt-1 text-sm">→ {a.accion_requerida}</div>}
            </li>
          ))}
        </ul>
      )}
      <p className="mt-3 text-xs text-slate-400">Las alertas se calculan por reglas y se resuelven solas al cumplirse la condición.</p>
    </Card>
  )
}

// -------------------------------------------------------------- trazabilidad

export function FilaTraza({ t, compacta = false }) {
  return (
    <li className="flex gap-2 py-2 text-sm">
      <span className="w-11 shrink-0 font-mono text-xs text-slate-500">{hora(t.ts)}</span>
      <div className="min-w-0 flex-1">
        <div className="flex flex-wrap items-center gap-1">
          <span className="font-semibold">{ACCION_NOMBRE[t.accion] || t.accion}</span>
          <Badge className={CANAL_ESTILO[t.canal]}>{t.canal.toUpperCase()}</Badge>
          {t.resultado !== 'ok' && <Badge className={RESULTADO_ESTILO[t.resultado]}>{t.resultado}</Badge>}
        </div>
        <div className="text-slate-700">{describir(t)}</div>
        <div className="text-xs text-slate-500">
          {t.usuario_nombre}
          {t.rol_nombre ? ` · ${t.rol_nombre}` : ''}
