function Feed({ estado, resaltar, onVerTodo }) {
  return (
    <Card
      titulo="Trazabilidad en vivo"
      resaltar={resaltar.has('trazabilidad')}
      extra={
        <button onClick={onVerTodo} className="text-xs font-medium text-sky-700 hover:underline">
          Ver completa
        </button>
      }
    >
      <ul className="max-h-96 divide-y divide-slate-100 overflow-y-auto pr-1">
        {estado.trazabilidad.slice(0, 25).map((t) => (
          <FilaTraza key={t.id} t={t} />
        ))}
      </ul>
