}

// --------------------------------------------------------------------- vista

export default function Quirofano({ estado, usuario, ejecutar, resaltar, refs, agente, onVerTrazabilidad, version }) {
  const [catalogos, setCatalogos] = useState({})
  const [catalogoInsumos, setCatalogoInsumos] = useState([])

  useEffect(() => {
    api.get('/catalogos').then((r) => r.ok && setCatalogos(r.data))
  }, [])
  useEffect(() => {
    api.get('/catalogo-insumos').then((r) => r.ok && setCatalogoInsumos(r.data))
  }, [version])

  const operativo = !!usuario.acceso_operativo
  const props = { estado, usuario, ejecutar, resaltar, refs, operativo, catalogos }
  const fase = estado.fases.find((f) => f.estado === 'en_curso')
  return (
    <div className="grid grid-cols-12 gap-4">
      <div className="col-span-12 flex flex-wrap items-center gap-3 rounded-xl bg-sky-900 px-4 py-2 text-white">
        <span className="text-xs font-semibold uppercase tracking-widest text-sky-200">Fase actual</span>
        <span className="text-lg font-bold">{fase ? `Fase ${fase.numero} · ${fase.nombre}` : estado.fase_nombre}</span>
        <span className="ml-auto text-sm text-sky-100">
          Estado: <b>{estado.cirugia.estado.replace('_', ' ')}</b> · Próximo hito:{' '}
          <b>{estado.hitos.find((h) => !h.hora)?.nombre || 'ninguno'}</b>
        </span>
        {!operativo && <Badge className="bg-amber-400 text-amber-950">Modo consulta</Badge>}
      </div>
      <Paciente {...props} />
      <Hitos {...props} />
      <div className="col-span-12 space-y-4 xl:col-span-8">
        <Checklist {...props} />
        <Insumos {...props} catalogoInsumos={catalogoInsumos} />
        <div className="grid gap-4 lg:grid-cols-2">
          <Anestesia {...props} />
          <Drenes {...props} />
        </div>
        <Novedades {...props} />
      </div>
      <div className="col-span-12 space-y-4 xl:col-span-4">
        <Alertas {...props} />
        {agente}
        <Feed {...props} onVerTodo={onVerTrazabilidad} />
      </div>
    </div>
  )
}

import { useCallback, useEffect, useState } from 'react'
import { Bar, BarChart, CartesianGrid, Cell, Legend, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import { api, fechaHora, rolColor } from '../api'
import { FilaTraza } from './Quirofano'
import { Badge, Boton, Campo, Card, INPUT, Interruptor } from './ui'

function Kpi({ titulo, valor, unidad, detalle, tono = 'slate' }) {
  const tonos = { slate: 'text-slate-900', verde: 'text-emerald-700', ambar: 'text-amber-700', rojo: 'text-red-700' }
  return (
    <div className="rounded-xl border border-slate-200 bg-white p-4 shadow-sm">
      <div className="text-xs font-semibold uppercase tracking-wide text-slate-500">{titulo}</div>
      <div className={`mt-1 text-3xl font-bold ${tonos[tono]}`}>
        {valor ?? '—'}
        {valor != null && unidad && <span className="ml-1 text-base font-medium text-slate-500">{unidad}</span>}
      </div>
      {detalle && <div className="mt-1 text-xs text-slate-500">{detalle}</div>}
    </div>
  )
}

const ESTADO = {
  en_curso: 'bg-sky-100 text-sky-800',
  programada: 'bg-slate-100 text-slate-700',
  finalizada: 'bg-emerald-100 text-emerald-800',
}

// ---------------------------------------------------------------- indicadores

function Indicadores({ onAbrir, version, reglas }) {
  const [d, setD] = useState(null)
  useEffect(() => {
    api.get('/dashboard').then((r) => r.ok && setD(r.data))
  }, [version])
  if (!d) return <p className="text-slate-500">Cargando indicadores…</p>
  const k = d.kpis
  const cumpl = k.cumplimiento_checklist
  const nombreRegla = Object.fromEntries(reglas.map((r) => [r.codigo, r.nombre]))

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-2 gap-4 md:grid-cols-3 xl:grid-cols-6">
        <Kpi titulo="Cirugías finalizadas" valor={k.cirugias_finalizadas} detalle={`${k.cirugias_en_curso} en curso`} />
        <Kpi titulo="Cumplimiento checklist" valor={cumpl} unidad="%" tono={cumpl >= 95 ? 'verde' : cumpl >= 85 ? 'ambar' : 'rojo'} detalle="Obligatorios verificados en fases cerradas" />
        <Kpi titulo="Duración media cirugía" valor={k.duracion_cirugia_prom} unidad="min" detalle="Inicio → fin" />
        <Kpi titulo="Tiempo medio en quirófano" valor={k.tiempo_quirofano_prom} unidad="min" detalle="Ingreso → salida" />
        <Kpi titulo="Novedades" valor={k.novedades_total} tono={k.novedades_abiertas ? 'ambar' : 'slate'} detalle={`${k.novedades_abiertas} abiertas`} />
        <Kpi
          titulo="Alertas generadas"
          valor={k.alertas_total}
          tono={k.alertas_activas ? 'rojo' : 'slate'}
          detalle={`${k.alertas_activas} activas · ${k.alertas_suprimidas} suprimidas`}
        />
      </div>

      <div className="grid gap-4 lg:grid-cols-3">
        <Card titulo="Cumplimiento por fase (%)">
          <div className="h-64">
            <ResponsiveContainer>
              <BarChart data={d.cumplimiento_por_fase}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} />
                <XAxis dataKey="fase" />
                <YAxis domain={[0, 100]} />
                <Tooltip formatter={(v) => `${v}%`} labelFormatter={(l, p) => p?.[0]?.payload?.nombre || l} />
                <Bar dataKey="cumplimiento" radius={[4, 4, 0, 0]}>
                  {d.cumplimiento_por_fase.map((f) => (
                    <Cell key={f.fase} fill={f.cumplimiento >= 95 ? '#059669' : f.cumplimiento >= 85 ? '#d97706' : '#dc2626'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </Card>
        <Card titulo="Tiempos por cirugía (min)" className="lg:col-span-2">
          <div className="h-64">
            <ResponsiveContainer>
              <BarChart data={d.tiempos}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} />
                <XAxis dataKey="fecha" fontSize={11} />
                <YAxis />
                <Tooltip labelFormatter={(l, p) => `${l} · ${p?.[0]?.payload?.procedimiento || ''}`} />
                <Legend />
                <Bar dataKey="preparacion" name="Ingreso → incisión" stackId="t" fill="#94a3b8" />
                <Bar dataKey="cirugia" name="Cirugía" stackId="t" fill="#0284c7" />
                <Bar dataKey="salida" name="Fin → recuperación" stackId="t" fill="#a78bfa" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </Card>
      </div>

      <div className="grid gap-4 lg:grid-cols-3">
        <Card titulo="Alertas por regla">
          <div className="h-56">
            <ResponsiveContainer>
              <BarChart data={d.alertas_por_regla} layout="vertical">
                <XAxis type="number" allowDecimals={false} />
                <YAxis type="category" dataKey="regla" width={32} />
                <Tooltip labelFormatter={(l) => `${l} · ${nombreRegla[l] || ''}`} />
                <Bar dataKey="total" fill="#f59e0b" radius={[0, 4, 4, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </Card>
        <Card titulo="Cirugías" className="lg:col-span-2">
          <div className="max-h-80 overflow-y-auto">
            <table className="w-full text-sm">
              <thead className="sticky top-0 bg-white">
                <tr className="text-left text-xs text-slate-500">
                  <th className="pb-2 font-medium">Fecha</th>
                  <th className="pb-2 font-medium">Paciente</th>
                  <th className="pb-2 font-medium">Procedimiento</th>
                  <th className="pb-2 font-medium">Estado</th>
                  <th className="pb-2 font-medium">Checklist</th>
                  <th className="pb-2 font-medium">Novedades</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {d.cirugias.map((c) => (
                  <tr key={c.id} onClick={() => onAbrir(c.id)} className="cursor-pointer hover:bg-sky-50">
                    <td className="py-1.5 whitespace-nowrap">{fechaHora(c.fecha)}</td>
                    <td className="py-1.5">{c.paciente}</td>
                    <td className="py-1.5">{c.procedimiento}</td>
                    <td className="py-1.5">
                      <Badge className={ESTADO[c.estado]}>{c.estado.replace('_', ' ')}</Badge>
                      {c.alertas_activas > 0 && <Badge className="ml-1 bg-red-600 text-white">{c.alertas_activas} alertas</Badge>}
                    </td>
                    <td className="py-1.5 font-mono">{c.checklist}</td>
                    <td className="py-1.5">{c.novedades}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </Card>
      </div>
      <p className="text-xs text-slate-400">Indicadores calculados desde la base de datos: 20 cirugías históricas de datos semilla (ficticios) más las cirugías actuales.</p>
    </div>
  )
}

// ------------------------------------------------------------- reglas de alerta

function Reglas({ datos, puede, ejecutar, recargar }) {
  const [pct, setPct] = useState('')
  useEffect(() => setPct(String(datos.umbral_preventivo_pct)), [datos.umbral_preventivo_pct])

  const cambiar = async (r, campo, valor) => {
    await ejecutar({
      metodo: 'patch',
      url: `/reglas/${r.codigo}`,
      body: { [campo]: valor },
      cambios: ['alertas'],
      exito: () =>
        campo === 'activa' ? `Regla ${r.codigo} ${valor ? 'activada' : 'suprimida'}` : `Regla ${r.codigo}: ${valor ? 'interrumpe con modal' : 'solo notificación'}`,
    })
    recargar()
  }

  const guardarPct = async () => {
    await ejecutar({
      metodo: 'put',
      url: '/configuracion/umbral',
      body: { umbral_preventivo_pct: Number(pct) },
      cambios: ['insumos', 'alertas'],
      exito: () => `Umbral preventivo general: ${pct} %`,
    })
    recargar()
  }

  return (
    <div className="grid gap-4 xl:grid-cols-3">
      <Card titulo="Reglas de alerta" className="xl:col-span-2">
        {!puede && <p className="mb-3 rounded bg-amber-50 px-3 py-2 text-sm text-amber-800">Su tipo de persona no puede modificar la configuración.</p>}
        <table className="w-full text-sm">
          <thead>
            <tr className="text-left text-xs uppercase tracking-wide text-slate-500">
              <th className="pb-2">Regla</th>
              <th className="pb-2">Acción requerida</th>
              <th className="pb-2 text-center">Activa</th>
              <th className="pb-2 text-center">Modal</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {datos.reglas.map((r) => (
              <tr key={r.codigo} className={r.activa ? '' : 'bg-slate-50 text-slate-400'}>
                <td className="py-2.5 pr-3">
                  <div className="flex items-center gap-2">
                    <Badge className="bg-slate-800 text-white">{r.codigo}</Badge>
                    <span className="font-semibold">{r.nombre}</span>
                    {!r.activa && <Badge className="bg-slate-300 text-slate-700">Suprimida</Badge>}
                  </div>
                  <div className="mt-0.5 text-xs">{r.descripcion}</div>
                </td>
                <td className="py-2.5 pr-3 text-xs">{r.accion_requerida}</td>
                <td className="py-2.5 text-center">
                  <Interruptor etiqueta={`Activar ${r.codigo}`} activo={r.activa} disabled={!puede} onChange={(v) => cambiar(r, 'activa', v)} />
                </td>
                <td className="py-2.5 text-center">
                  <Interruptor etiqueta={`Modal ${r.codigo}`} activo={r.modal} disabled={!puede || !r.activa} onChange={(v) => cambiar(r, 'modal', v)} />
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        <p className="mt-3 text-xs text-slate-500">
          Activa: la regla se evalúa. Suprimida: no genera alertas y las activas pasan a «suprimida» (siguen en la BD). Modal: la alerta interrumpe con una
          ventana central; las alertas de severidad crítica siempre interrumpen. Cada cambio queda en el historial de configuración.
        </p>
      </Card>
      <Card titulo="Umbral preventivo de insumos">
        <p className="text-sm text-slate-600">
          Porcentaje general usado cuando el insumo no tiene un umbral propio en el catálogo. Ejemplo: inicial 20 y 25 % → advertencia al quedar 5.
        </p>
        <div className="mt-3 flex items-end gap-2">
          <Campo etiqueta="Umbral general (%)" className="flex-1">
            <input className={INPUT} inputMode="numeric" value={pct} disabled={!puede} onChange={(e) => setPct(e.target.value.replace(/\D/g, ''))} />
          </Campo>
          <Boton disabled={!puede || !pct || Number(pct) === datos.umbral_preventivo_pct} onClick={guardarPct}>
            Guardar
          </Boton>
        </div>
      </Card>
    </div>
  )
}

// ------------------------------------------------------ insumos por procedimiento

function InsumosProcedimiento({ puede, ejecutar, version }) {
  const [procs, setProcs] = useState([])
  const [catalogo, setCatalogo] = useState([])
  const [sel, setSel] = useState(null)
  const [nuevoProc, setNuevoProc] = useState({ nombre: '', sitio_sugerido: '' })
  const [asoc, setAsoc] = useState({ insumo_id: '', cantidad_sugerida: '' })
  const [nuevoIns, setNuevoIns] = useState({ nombre: '', unidad: 'unidades', umbral_preventivo: '', aliases: '' })

  const cargar = useCallback(async () => {
    const [p, c] = await Promise.all([api.get('/procedimientos'), api.get('/catalogo-insumos')])
    if (p.ok) {
      setProcs(p.data)
      setSel((s) => s ?? p.data[0]?.id)
    }
    if (c.ok) setCatalogo(c.data)
  }, [])
  useEffect(() => {
    cargar()
  }, [cargar, version])

  const proc = procs.find((p) => p.id === sel)
  const yaAsociados = new Set(proc?.insumos.map((i) => i.insumo_id))

  const hacer = async (opts) => {
    const r = await ejecutar(opts)
    await cargar()
    return r
  }

  return (
    <div className="grid gap-4 xl:grid-cols-2">
      <Card titulo="Insumos asociados por tipo de procedimiento">
        <div className="flex gap-2">
          <select className={INPUT} value={sel ?? ''} onChange={(e) => setSel(Number(e.target.value))}>
            {procs.map((p) => (
              <option key={p.id} value={p.id}>
                {p.nombre}
              </option>
            ))}
          </select>
        </div>
        {proc && (
          <>
            <p className="mt-2 text-xs text-slate-500">Sitio sugerido: {proc.sitio_sugerido || '—'}. Al crear una cirugía de este tipo, estos insumos se cargan con cantidad 0.</p>
            <ul className="mt-3 divide-y divide-slate-100 rounded-lg border border-slate-200">
              {proc.insumos.length === 0 && <li className="px-3 py-2 text-sm text-slate-400">Sin insumos asociados.</li>}
              {proc.insumos.map((i) => (
                <li key={i.id} className="flex items-center justify-between px-3 py-2 text-sm">
                  <span>
                    <b>{i.nombre}</b> <span className="text-xs text-slate-500">· {i.unidad}{i.cantidad_sugerida ? ` · sugerido ${i.cantidad_sugerida}` : ''}</span>
                  </span>
                  {puede && (
                    <button
                      className="text-xs text-red-600 hover:underline"
                      onClick={() => hacer({ metodo: 'delete', url: `/procedimientos/insumos/${i.id}?usuario_id=__U__`, exito: () => `${i.nombre} retirado` })}
                    >
                      Quitar
                    </button>
                  )}
                </li>
              ))}
            </ul>
            {puede && (
              <form
                className="mt-3 flex gap-2"
                onSubmit={async (e) => {
                  e.preventDefault()
                  const r = await hacer({
                    url: `/procedimientos/${proc.id}/insumos`,
                    body: { insumo_id: Number(asoc.insumo_id), cantidad_sugerida: asoc.cantidad_sugerida ? Number(asoc.cantidad_sugerida) : null },
                    exito: () => 'Insumo asociado',
                  })
                  if (r) setAsoc({ insumo_id: '', cantidad_sugerida: '' })
                }}
              >
                <select className={INPUT} value={asoc.insumo_id} onChange={(e) => setAsoc({ ...asoc, insumo_id: e.target.value })}>
                  <option value="">Insumo del catálogo…</option>
                  {catalogo
                    .filter((c) => c.activo && !yaAsociados.has(c.id))
                    .map((c) => (
                      <option key={c.id} value={c.id}>
                        {c.nombre}
                      </option>
                    ))}
                </select>
                <input className={`${INPUT} w-28`} placeholder="Sugerido" inputMode="numeric" value={asoc.cantidad_sugerida} onChange={(e) => setAsoc({ ...asoc, cantidad_sugerida: e.target.value.replace(/\D/g, '') })} />
                <Boton type="submit" disabled={!asoc.insumo_id}>
                  Asociar
                </Boton>
              </form>
            )}
          </>
        )}
        {puede && (
          <form
            className="mt-5 grid grid-cols-5 gap-2 border-t border-slate-100 pt-4"
            onSubmit={async (e) => {
              e.preventDefault()
              const r = await hacer({ url: '/procedimientos', body: nuevoProc, exito: () => 'Procedimiento creado' })
              if (r) {
                setNuevoProc({ nombre: '', sitio_sugerido: '' })
                setSel(r.id)
              }
            }}
          >
            <input className={`${INPUT} col-span-2`} placeholder="Nuevo procedimiento" value={nuevoProc.nombre} onChange={(e) => setNuevoProc({ ...nuevoProc, nombre: e.target.value })} />
            <input className={`${INPUT} col-span-2`} placeholder="Sitio sugerido" value={nuevoProc.sitio_sugerido} onChange={(e) => setNuevoProc({ ...nuevoProc, sitio_sugerido: e.target.value })} />
            <Boton type="submit" disabled={nuevoProc.nombre.trim().length < 3}>
              Crear
            </Boton>
          </form>
        )}
      </Card>

      <Card titulo="Catálogo general de insumos">
        <table className="w-full text-sm">
          <thead>
            <tr className="text-left text-xs uppercase tracking-wide text-slate-500">
              <th className="pb-2">Insumo</th>
              <th className="pb-2">Unidad</th>
              <th className="pb-2">Umbral propio</th>
              <th className="pb-2 text-center">Activo</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {catalogo.map((c) => (
              <tr key={c.id} className={c.activo ? '' : 'text-slate-400'}>
                <td className="py-2 font-medium">{c.nombre}</td>
                <td className="py-2">{c.unidad}</td>
                <td className="py-2">
                  <input
                    key={`${c.id}-${c.umbral_preventivo}`}
                    className={`${INPUT} w-24`}
                    defaultValue={c.umbral_preventivo ?? ''}
                    placeholder="% general"
                    disabled={!puede}
                    inputMode="numeric"
                    onBlur={(e) => {
                      const v = e.target.value.trim()
                      const nuevo = v === '' ? null : Number(v)
                      if (nuevo !== c.umbral_preventivo && (nuevo === null || nuevo >= 0))
                        hacer({ metodo: 'patch', url: `/catalogo-insumos/${c.id}`, body: { umbral_preventivo: nuevo }, cambios: ['insumos', 'alertas'], exito: () => `Umbral de ${c.nombre} actualizado` })
                    }}
                  />
                </td>
                <td className="py-2 text-center">
                  <Interruptor
                    etiqueta={`Activo ${c.nombre}`}
                    activo={c.activo}
                    disabled={!puede}
                    onChange={(v) => hacer({ metodo: 'patch', url: `/catalogo-insumos/${c.id}`, body: { activo: v }, exito: () => `${c.nombre} ${v ? 'activado' : 'desactivado'}` })}
                  />
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        <p className="mt-2 text-xs text-slate-500">Umbral propio en unidades; vacío = usa el porcentaje general.</p>
        {puede && (
          <form
            className="mt-4 grid grid-cols-6 gap-2 border-t border-slate-100 pt-4"
            onSubmit={async (e) => {
              e.preventDefault()
              const r = await hacer({
                url: '/catalogo-insumos',
                body: { ...nuevoIns, umbral_preventivo: nuevoIns.umbral_preventivo ? Number(nuevoIns.umbral_preventivo) : null },
                exito: () => 'Insumo creado en el catálogo',
              })
              if (r) setNuevoIns({ nombre: '', unidad: 'unidades', umbral_preventivo: '', aliases: '' })
            }}
          >
            <input className={`${INPUT} col-span-2`} placeholder="Nombre" value={nuevoIns.nombre} onChange={(e) => setNuevoIns({ ...nuevoIns, nombre: e.target.value })} />
            <input className={`${INPUT} col-span-1`} placeholder="Unidad" value={nuevoIns.unidad} onChange={(e) => setNuevoIns({ ...nuevoIns, unidad: e.target.value })} />
            <input className={`${INPUT} col-span-1`} placeholder="Umbral" inputMode="numeric" value={nuevoIns.umbral_preventivo} onChange={(e) => setNuevoIns({ ...nuevoIns, umbral_preventivo: e.target.value.replace(/\D/g, '') })} />
            <Boton type="submit" className="col-span-2" disabled={nuevoIns.nombre.trim().length < 2}>
              Crear insumo
            </Boton>
            <input className={`${INPUT} col-span-6`} placeholder="Sinónimos para voz, separados por coma (ej.: compresa, paño)" value={nuevoIns.aliases} onChange={(e) => setNuevoIns({ ...nuevoIns, aliases: e.target.value })} />
          </form>
        )}
      </Card>
    </div>
  )
}

// ------------------------------------------------------------------- personas

function Personas({ puede, ejecutar, version, onCambio }) {
  const [tipos, setTipos] = useState([])
  const [usuarios, setUsuarios] = useState([])
  const [nuevoTipo, setNuevoTipo] = useState({ nombre: '', acceso_operativo: false, puede_configurar: false })
  const [nuevoU, setNuevoU] = useState({ nombre: '', rol: '' })

  const cargar = useCallback(async () => {
    const [t, u] = await Promise.all([api.get('/tipos-persona'), api.get('/usuarios?todos=true')])
    if (t.ok) setTipos(t.data)
    if (u.ok) setUsuarios(u.data)
  }, [])
  useEffect(() => {
    cargar()
  }, [cargar, version])

  const hacer = async (opts) => {
    const r = await ejecutar(opts)
    await cargar()
    onCambio()
    return r
  }

  const tipoPatch = (t, campo, valor) =>
    hacer({ metodo: 'patch', url: `/tipos-persona/${t.id}`, body: { [campo]: valor }, exito: () => `${t.nombre} actualizado` })

  return (
    <div className="grid gap-4 xl:grid-cols-2">
      <Card titulo="Tipos de persona (roles)">
        <table className="w-full text-sm">
          <thead>
            <tr className="text-left text-xs uppercase tracking-wide text-slate-500">
              <th className="pb-2">Nombre</th>
              <th className="pb-2 text-center">Acceso operativo</th>
              <th className="pb-2 text-center">Configura</th>
              <th className="pb-2 text-center">Activo</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {tipos.map((t) => (
              <tr key={t.id} className={t.activo ? '' : 'text-slate-400'}>
                <td className="py-2">
                  <Badge className={rolColor(t.codigo)}>{t.nombre}</Badge>
                  {t.predefinido && <span className="ml-1 text-[10px] text-slate-400">predefinido</span>}
                </td>
                <td className="py-2 text-center">
                  <Interruptor etiqueta="Acceso operativo" activo={t.acceso_operativo} disabled={!puede} onChange={(v) => tipoPatch(t, 'acceso_operativo', v)} />
                </td>
                <td className="py-2 text-center">
                  <Interruptor etiqueta="Configura" activo={t.puede_configurar} disabled={!puede} onChange={(v) => tipoPatch(t, 'puede_configurar', v)} />
                </td>
                <td className="py-2 text-center">
                  <Interruptor etiqueta="Activo" activo={t.activo} disabled={!puede} onChange={(v) => tipoPatch(t, 'activo', v)} />
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        <p className="mt-2 text-xs text-slate-500">
          Acceso operativo: registra verificaciones, insumos, hitos, anestesia, drenes y novedades sin cambiar de usuario. Sin acceso operativo: solo consulta.
        </p>
        {puede && (
          <form
            className="mt-4 flex flex-wrap items-center gap-3 border-t border-slate-100 pt-4"
            onSubmit={async (e) => {
              e.preventDefault()
              const r = await hacer({ url: '/tipos-persona', body: nuevoTipo, exito: () => `Tipo «${nuevoTipo.nombre}» creado` })
              if (r) setNuevoTipo({ nombre: '', acceso_operativo: false, puede_configurar: false })
            }}
          >
            <input className={`${INPUT} flex-1`} placeholder="Nuevo tipo (ej.: Circulante)" value={nuevoTipo.nombre} onChange={(e) => setNuevoTipo({ ...nuevoTipo, nombre: e.target.value })} />
            <label className="flex items-center gap-1 text-xs">
              <input type="checkbox" checked={nuevoTipo.acceso_operativo} onChange={(e) => setNuevoTipo({ ...nuevoTipo, acceso_operativo: e.target.checked })} /> Operativo
            </label>
            <label className="flex items-center gap-1 text-xs">
              <input type="checkbox" checked={nuevoTipo.puede_configurar} onChange={(e) => setNuevoTipo({ ...nuevoTipo, puede_configurar: e.target.checked })} /> Configura
            </label>
            <Boton type="submit" disabled={nuevoTipo.nombre.trim().length < 3}>
              Crear tipo
            </Boton>
          </form>
        )}
      </Card>

      <Card titulo="Personas">
        <ul className="divide-y divide-slate-100">
          {usuarios.map((u) => (
            <li key={u.id} className={`flex items-center justify-between py-2 text-sm ${u.activo && u.tipo_activo ? '' : 'text-slate-400'}`}>
              <span className="flex items-center gap-2">
                <b>{u.nombre}</b>
                <Badge className={rolColor(u.rol)}>{u.rol_nombre}</Badge>
                {u.acceso_operativo && <Badge className="bg-emerald-100 text-emerald-800">Operativo</Badge>}
                {!u.tipo_activo && <Badge className="bg-slate-200 text-slate-600">Tipo inactivo</Badge>}
              </span>
              <Interruptor
                etiqueta={`Activo ${u.nombre}`}
                activo={u.activo}
                disabled={!puede}
                onChange={(v) => hacer({ metodo: 'patch', url: `/usuarios/${u.id}`, body: { activo: v }, exito: () => `${u.nombre} ${v ? 'activado' : 'desactivado'}` })}
              />
            </li>
          ))}
        </ul>
        {puede && (
          <form
            className="mt-4 flex gap-2 border-t border-slate-100 pt-4"
            onSubmit={async (e) => {
              e.preventDefault()
              const r = await hacer({ url: '/usuarios', body: nuevoU, exito: () => `${nuevoU.nombre} creado` })
              if (r) setNuevoU({ nombre: '', rol: '' })
            }}
          >
            <input className={`${INPUT} flex-1`} placeholder="Nombre de la persona" value={nuevoU.nombre} onChange={(e) => setNuevoU({ ...nuevoU, nombre: e.target.value })} />
            <select className={`${INPUT} w-56`} value={nuevoU.rol} onChange={(e) => setNuevoU({ ...nuevoU, rol: e.target.value })}>
              <option value="">Tipo de persona…</option>
              {tipos
                .filter((t) => t.activo)
                .map((t) => (
                  <option key={t.id} value={t.codigo}>
                    {t.nombre}
                  </option>
                ))}
            </select>
            <Boton type="submit" disabled={nuevoU.nombre.trim().length < 3 || !nuevoU.rol}>
              Crear
            </Boton>
          </form>
        )}
      </Card>
    </div>
  )
}

// ---------------------------------------------------------- historial config

function HistorialConfig({ version }) {
  const [filas, setFilas] = useState([])
  useEffect(() => {
    api.get('/trazabilidad/configuracion').then((r) => r.ok && setFilas(r.data))
  }, [version])
  return (
    <Card titulo="Historial de configuración">
      {filas.length === 0 ? (
        <p className="text-sm text-slate-400">Sin cambios de configuración registrados.</p>
      ) : (
        <ul className="divide-y divide-slate-100">
          {filas.map((t) => (
            <FilaTraza key={t.id} t={t} />
          ))}
        </ul>
      )}
    </Card>
  )
}

// --------------------------------------------------------------------- vista

const PESTANAS = [
  ['indicadores', 'Indicadores'],
  ['reglas', 'Reglas de alerta'],
  ['insumos', 'Insumos por procedimiento'],
  ['personas', 'Personas y tipos'],
  ['historial', 'Historial de configuración'],
]

export default function Gestion({ onAbrir, version, usuario, ejecutar, onCambioConfig }) {
  const [tab, setTab] = useState('indicadores')
  const [reglas, setReglas] = useState({ reglas: [], umbral_preventivo_pct: 25 })
  const puede = !!usuario.puede_configurar

  const cargarReglas = useCallback(() => api.get('/reglas').then((r) => r.ok && setReglas(r.data)), [])
  useEffect(() => {
    cargarReglas()
  }, [cargarReglas, version])

  const ejecutarConfig = useCallback(
    (opts) => ejecutar({ ...opts, url: opts.url.replace('__U__', usuario.id) }),
    [ejecutar, usuario.id],
  )

  return (
    <div className="space-y-4">
      <nav className="flex flex-wrap gap-1 rounded-xl bg-white p-1 shadow-sm">
        {PESTANAS.map(([id, nombre]) => (
          <button
            key={id}
            onClick={() => setTab(id)}
            className={`rounded-lg px-4 py-2 text-sm font-semibold ${tab === id ? 'bg-slate-900 text-white' : 'text-slate-600 hover:bg-slate-100'}`}
          >
            {nombre}
          </button>
        ))}
        {!puede && tab !== 'indicadores' && <span className="ml-auto self-center pr-3 text-xs text-amber-700">Solo lectura para {usuario.rol_nombre}</span>}
      </nav>
      {tab === 'indicadores' && <Indicadores onAbrir={onAbrir} version={version} reglas={reglas.reglas} />}
      {tab === 'reglas' && <Reglas datos={reglas} puede={puede} ejecutar={ejecutarConfig} recargar={cargarReglas} />}
      {tab === 'insumos' && <InsumosProcedimiento puede={puede} ejecutar={ejecutarConfig} version={version} />}
      {tab === 'personas' && <Personas puede={puede} ejecutar={ejecutarConfig} version={version} onCambio={onCambioConfig} />}
      {tab === 'historial' && <HistorialConfig version={version} />}
    </div>
  )
}

