]

function SelectorInicial({ usuarios, onElegir }) {
  return (
    <div className="fixed inset-0 z-40 flex items-center justify-center bg-slate-900/80 p-4">
      <div className="w-full max-w-2xl rounded-2xl bg-white p-6 shadow-2xl">
        <h2 className="text-xl font-bold">¿Quién está usando el tablero?</h2>
        <p className="mt-1 text-sm text-slate-500">Cada acción queda registrada con su usuario, rol y hora. (Simula el inicio de sesión.)</p>
        <div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-3">
          {usuarios.map((u) => (
            <button
              key={u.id}
              onClick={() => onElegir(u)}
              className="rounded-xl border-2 border-slate-200 p-4 text-left transition hover:border-sky-500 hover:bg-sky-50"
            >
              <div className="font-semibold">{u.nombre}</div>
              <Badge className={`mt-2 ${rolColor(u.rol)}`}>{u.rol_nombre}</Badge>
              {u.acceso_operativo && <div className="mt-1 text-[11px] text-emerald-700">Acceso operativo completo</div>}
            </button>
          ))}
        </div>
      </div>
    </div>
  )
}

function Tablero() {
  const pedir = useDialogo()
  const toast = useToast()
  const [usuarios, setUsuarios] = useState([])
  const [usuario, setUsuario] = useState(null)
  const [cirugias, setCirugias] = useState([])
  const [cirugiaId, setCirugiaId] = useState(null)
  const [estado, setEstado] = useState(null)
  const [reglas, setReglas] = useState({})
  const [vista, setVista] = useState(() => location.hash.replace('#', '') || 'quirofano')
  const [resaltar, setResaltar] = useState({ secciones: new Set(), refs: {} })
  const [version, setVersion] = useState(0)
  const [conexion, setConexion] = useState(true)
  const [nueva, setNueva] = useState(false)
  const timerResaltado = useRef(null)
  const cargando = useRef(false)
  const alertasVistas = useRef(null)

  useEffect(() => {
    location.hash = vista
  }, [vista])

  useEffect(() => {
    const alCambiar = () => {
      const h = location.hash.replace('#', '')
      if (VISTAS.some(([id]) => id === h)) setVista(h)
    }
    window.addEventListener('hashchange', alCambiar)
    return () => window.removeEventListener('hashchange', alCambiar)
  }, [])

  const cargarListas = useCallback(async () => {
    const [u, c, r] = await Promise.all([api.get('/usuarios'), api.get('/cirugias'), api.get('/reglas')])
    if (u.ok) {
      setUsuarios(u.data)
      const guardado = Number(localStorage.getItem('usuario_id'))
      setUsuario((actual) => u.data.find((x) => x.id === (actual?.id ?? guardado)) || null)
    }
    if (c.ok) {
      setCirugias(c.data)
      setCirugiaId((actual) => actual ?? c.data.find((x) => x.estado === 'en_curso')?.id ?? c.data[0]?.id)
    }
    if (r.ok) setReglas(Object.fromEntries(r.data.reglas.map((x) => [x.codigo, x])))
  }, [])

  useEffect(() => {
    cargarListas()
  }, [cargarListas, version])

  const refrescar = useCallback(async () => {
    if (!cirugiaId || cargando.current) return
    cargando.current = true
    try {
      const r = await api.get(`/cirugias/${cirugiaId}`)
      setConexion(r.ok)
      if (r.ok) setEstado(r.data)
    } catch {
      setConexion(false)
    } finally {
      cargando.current = false
    }
  }, [cirugiaId])

  useEffect(() => {
    refrescar()
    const t = setInterval(refrescar, 2000)
    return () => clearInterval(t)
  }, [refrescar])

  // Notificaciones menores (no interrumpen): aviso breve al aparecer
  useEffect(() => {
    if (!estado) return
    const ids = new Set(estado.alertas.map((a) => a.id))
    if (alertasVistas.current) {
      estado.alertas
        .filter((a) => !alertasVistas.current.has(a.id) && !a.interrumpe)
        .forEach((a) => toast(`${a.regla}: ${a.mensaje}`, 'info'))
    }
    alertasVistas.current = ids
  }, [estado, toast])

  useEffect(() => {
    alertasVistas.current = null
  }, [cirugiaId])

  const marcar = useCallback((secciones = [], refs = {}) => {
    clearTimeout(timerResaltado.current)
    setResaltar({ secciones: new Set(secciones), refs })
    timerResaltado.current = setTimeout(() => setResaltar({ secciones: new Set(), refs: {} }), 2600)
  }, [])

  const elegirUsuario = (u) => {
    setUsuario(u)
    localStorage.setItem('usuario_id', u.id)
  }

  /** Ejecuta una acción de pantalla con el mismo manejo de confirmaciones y bloqueos que el agente. */
  const ejecutar = useCallback(
    async ({ metodo = 'post', url, body = {}, cambios = [], refs = {}, exito }) => {
      const base = { usuario_id: usuario.id, ...body }
      let r = await api[metodo](url, base)
      if (r.status === 409 && r.data?.estado === 'confirmar') {
        const ok = await pedir({ titulo: 'Confirmación requerida', mensaje: r.data.texto, confirmar: 'Sí, confirmar', peligro: true })
        if (!ok) {
          toast('Cancelado. No se registró nada.')
          return null
        }
        r = await api[metodo](url, { ...base, confirmado: true })
      }
      if (!r.ok && r.data?.datos?.requiere_justificacion) {
        const just = await pedir({
          titulo: 'Autorización con justificación',
          mensaje: r.data.texto,
          campo: 'Justificación (obligatoria)',
          requerido: true,
          confirmar: 'Autorizar',
          peligro: true,
        })
        if (!just) {
          await refrescar()
          return null
        }
        r = await api[metodo](url, { ...base, justificacion: just })
      }
      if (!r.ok) {
        const texto = typeof r.data?.detail === 'string' ? r.data.detail : Array.isArray(r.data?.detail) ? 'Datos inválidos' : r.data?.texto
        toast(texto || 'Error', 'error')
        marcar(['trazabilidad'])
        await refrescar()
        return null
      }
      toast(exito ? exito(r.data) : 'Registrado', 'ok')
      marcar([...cambios, 'trazabilidad', ...(r.data?.alertas_nuevas?.length ? ['alertas'] : [])], refs)
      await refrescar()
      setVersion((v) => v + 1)
      return r.data
    },
    [usuario, pedir, toast, marcar, refrescar],
  )

  const onRespuestaAgente = useCallback(
    async (res) => {
      marcar([...(res.cambios || []), ...(res.alertas_nuevas?.length ? ['alertas'] : [])], res.refs || {})
      await refrescar()
      setVersion((v) => v + 1)
    },
    [marcar, refrescar],
  )

  const reconocer = useCallback(
    async (a) => {
      await api.post(`/alertas/${a.id}/reconocer`, { usuario_id: usuario.id })
      await refrescar()
    },
    [usuario, refrescar],
  )

  const irAResolver = async (a) => {
    await reconocer(a)
    setVista('quirofano')
    setTimeout(() => {
      const el = document.getElementById(REGLA_SECCION[a.regla] || 'sec-paciente')
      el?.scrollIntoView({ behavior: 'smooth', block: 'start' })
      marcar([{ 'sec-insumos': 'insumos', 'sec-checklist': 'checklist', 'sec-novedades': 'novedades' }[REGLA_SECCION[a.regla]] || 'paciente'])
    }, 150)
  }

  const reiniciar = async () => {
    const ok = await pedir({
      titulo: 'Reiniciar demo',
      mensaje: 'Se borran todos los registros y se vuelve a cargar la semilla. ¿Continuar?',
      confirmar: 'Reiniciar',
      peligro: true,
    })
    if (!ok) return
    await api.post('/demo/reset')
    setEstado(null)
    setCirugiaId(null)
    await cargarListas()
    setVersion((v) => v + 1)
    toast('Datos de demo reiniciados', 'ok')
  }

  const abrirCirugia = (id) => {
    setCirugiaId(id)
    setEstado(null)
    setVista('quirofano')
  }

  return (
    <div className="min-h-screen">
      <header className="no-print sticky top-0 z-30 bg-slate-900 text-white shadow">
        <div className="mx-auto flex max-w-[1600px] flex-wrap items-center gap-4 px-4 py-2.5">
          <div className="flex items-center gap-2">
            <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-sky-500 text-lg font-black">+</div>
            <div>
              <div className="text-sm font-bold leading-tight">Tablero Inteligente de Seguridad Quirúrgica</div>
              <div className="text-xs text-slate-400">Registrar sin dejar de operar</div>
            </div>
          </div>
          <nav className="flex gap-1">
            {VISTAS.map(([id, nombre]) => (
              <button
                key={id}
                onClick={() => setVista(id)}
                className={`rounded-lg px-3 py-1.5 text-sm font-medium ${vista === id ? 'bg-white text-slate-900' : 'text-slate-300 hover:bg-slate-800'}`}
              >
                {nombre}
              </button>
            ))}
          </nav>
          <div className="ml-auto flex items-center gap-3">
            {!conexion && <Badge className="bg-red-600 text-white">Sin conexión con el servidor</Badge>}
            {estado?.alertas?.length > 0 && (
              <button onClick={() => setVista('quirofano')}>
                <Badge className={`!text-sm ${estado.alertas.some((a) => a.severidad === 'alta') ? 'bg-red-600 text-white' : 'bg-amber-400 text-amber-950'}`}>
                  ⚠ {estado.alertas.length} alerta{estado.alertas.length !== 1 ? 's' : ''}
                </Badge>
              </button>
            )}
            <select
              value={cirugiaId ?? ''}
              onChange={(e) => abrirCirugia(Number(e.target.value))}
              className="max-w-64 rounded-lg bg-slate-800 px-2 py-1.5 text-sm"
            >
              {cirugias.map((c) => (
                <option key={c.id} value={c.id}>
                  {c.estado === 'en_curso' ? '● ' : ''}
                  {c.procedimiento} · {c.paciente}
                </option>
              ))}
            </select>
            {usuario?.acceso_operativo && (
              <Boton onClick={() => setNueva(true)} className="!bg-sky-600">
                + Nueva cirugía
              </Boton>
            )}
            <select
              value={usuario?.id ?? ''}
              onChange={(e) => elegirUsuario(usuarios.find((u) => u.id === Number(e.target.value)))}
              className="rounded-lg bg-slate-800 px-2 py-1.5 text-sm"
              title="Usuario activo"
            >
              {usuarios.map((u) => (
                <option key={u.id} value={u.id}>
                  {u.nombre} · {u.rol_nombre}
                </option>
              ))}
            </select>
            <Boton variante="secundario" onClick={reiniciar} className="!bg-slate-800 !text-slate-200 !border-slate-700">
              Reiniciar demo
            </Boton>
          </div>
        </div>
      </header>

      <main className="mx-auto max-w-[1600px] p-4">
        {!estado || !usuario ? (
          <p className="text-slate-500">{conexion ? 'Cargando…' : 'No se pudo conectar con la API en el puerto 8000.'}</p>
        ) : vista === 'gestion' ? (
          <Gestion onAbrir={abrirCirugia} version={version} usuario={usuario} ejecutar={ejecutar} onCambioConfig={cargarListas} />
        ) : vista === 'trazabilidad' ? (
          <Trazabilidad cirugiaId={cirugiaId} estado={estado} usuarios={usuarios} version={version} />
        ) : (
          <Quirofano
            estado={estado}
            usuario={usuario}
            ejecutar={ejecutar}
            resaltar={resaltar.secciones}
            refs={resaltar.refs}
            version={version}
            onVerTrazabilidad={() => setVista('trazabilidad')}
            agente={
              estado.cirugia.estado !== 'finalizada' && (
                <AgenteVoz key={`${cirugiaId}-${usuario.id}`} usuario={usuario} cirugiaId={cirugiaId} onRespuesta={onRespuestaAgente} />
              )
            }
          />
        )}
      </main>

      {estado && usuario && <AlertaModal alertas={estado.alertas} reglas={reglas} onReconocer={reconocer} onIrAResolver={irAResolver} />}

      {nueva && (
        <NuevaCirugia
          ejecutar={ejecutar}
          onCerrar={() => setNueva(false)}
          onCreada={async (id) => {
            setNueva(false)
            await cargarListas()
            abrirCirugia(id)
          }}
        />
      )}

      {usuarios.length > 0 && !usuario && <SelectorInicial usuarios={usuarios} onElegir={elegirUsuario} />}
    </div>
  )
}

export default function App() {
  return (
    <Proveedores>
      <Tablero />
    </Proveedores>
  )
}

